insert into тип_продукции values (1, 5893, 'Элитная коллекция пригласительных открыток', $$Поплотнее запахнувшись в свой обтрепанный халат, он приветствовал доброе утро широкой улыбкой Следовательно, надо отыскать этого собрата То есть больно будет, если вам не удастся промахнуться мимо земли – Тс-с, – вновь прошипел Форд$$);
insert into тип_продукции values (2, 5265, 'Художественные журналы с персонализированной обложкой', $$– Я дома, – твердил он, – дома – Я думал, ты умер… – вырвалось у него Зафод не покидал кровати Их задача – в решающий момент выскочить из кустов и продемонстрировать наглядно и/или выразить словесно свою особливость Это Артур Дент говорит – Вы хотите дослушать эту историю или что?

– Мне хотелось бы услышать вашу речь, – заявил матрасс – Недурная мысль, – заметил Форд Префект, соскальзывая с валуна, на котором сидел – Вы ведь англичанин, правда? – поинтересовалось видение$$);
insert into тип_продукции values (3, 1160, 'Организаторы с персонализированным дизайном и тиснением', $$Там есть кое-какие советы по поводу пьянства Зафод влил еще стакан в свою другую глотку – Артур, мы бороздим Галактику в поисках развлечений – Кто же?

– Мммммм мммммм мммммм, – сказал компьютер Матрасс момнухнул – Пользительное занятие Форд, нас подбрасывают!

И действительно, для того чтобы не поддаться этому первому впечатлению, надо было обладать весьма глубокими познаниями в истории Галактики (каковых Артур еще не успел приобрести из-за своей кочевой жизни) Но возможно, тебе любопытно будет узнать, что твой покорный слуга единолично ответственен за удлиненную форму животного, которому в будущих веках дадут имя «жираф» Форд вытащил из своей жутко обтрепавшейся и донельзя замызганной сумки субэфирный чуткомат$$);
insert into тип_продукции values (4, 1925, 'Альбомы для фотографий с тиснением и мягкими листами', $$Ну а для Зафода это обернулось тем, что: а) он ни разу даже не подошел к девочке и б) пропустил целую эпоху в древней истории, знания о которой ему бы сейчас очень пригодились Они уселись на камень и впали в глубокую задумчивость – Самая мощная из известных паранауке вычислительных сил В матче$$);
insert into тип_продукции values (5, 3360, 'Изготовленные на заказ ежедневники с закладками из ленты', $$– Было что-то интересное?

И вновь они балансировали на краю ужасно высокого утеса Последние все время так и рвались в полет, но почему-то все же оставались на месте Люк сам собой захлопнулся Шшшшрр – Протечки?

– Протечки в пространстве-времени, – сказал Форд и поспешил подставить свое зверски ухмыляющееся лицо ветру, который как раз случайно пролетал мимо Зафоду пришло в голову, что для ускорения беседы предложения нужно сделать вопросительными И меж тем как «Золотое сердце» неслось с невероятной скоростью в неопределенном направлении, Триллиан прихлебывала какое-то неудобоваримое творение нутримата и читала о том, как научиться летать Миссия «Криккита-1» заключалась в том, чтобы выяснить, есть ли что-то с той стороны неба, откуда, вероятно, и происходил разбившийся корабль Только двадцать минут назад он решил сойти с ума – и вот уже гоняется по лугам доисторической Земли за честерфильдским диваном$$);
insert into тип_продукции values (6, 8554, 'Персонализированные конверты с сургучными печатями', $$Поговаривают, что у нее эрогенные зоны начинаются милях в четырех от тела как такового – И сумка тоже не моя, – неожиданно объявил Артур Солнце нехотя попыталось одолеть туман, пробуя то тут добавить немножко тепла, то вон туда запустить несколько лучиков, но, судя по всему, сегодня его ожидала очередная тягомотная прогулка от горизонта до горизонта А за спиной человека из исполинских клубов мглы стали постепенно вырисовываться три высоких столба Бредя в сумерках к своей пещере, Артур вдруг заметил за облаками странные вспышки$$);
insert into тип_продукции values (7, 800, 'Комплекты открыток с тематическими принтами', $$За исключением одного случая Темп все возрастал – Да, ты прав, и все же он утверждал, что видел, как нечто материализовалось на площадке Его лучи ласкали брикеты мороженого, от чего оно таяло – Дайте мне формы и контуры Странно, но факт Компьютер пискнул Все было ясно из самой его походки – Я сам вам поясню, – прошептал старец$$);
insert into тип_продукции values (8, 2077, 'Декоративные коробки с узорами из тиснения', $$– Хуже нигде уже не будет, – сказала она себе, нажимая кнопку А потом все завершилось – так же внезапно, как и началось Эта штука недавно проснулась Прибор едва слышно жужжал, подмигивая крохотной тусклой лампочкой Скорбное выражение на лице Артура Дента уступило место еще более скорбному Звездолет (да-да, еще один, просто звездолетопад какой-то), только на сей раз изящный и серебряный, спустился с небес на площадку – тихо, как-то даже интеллигентно, совершая опорами балетные па во славу технического прогресса Конкретно – всего лишь одну ноту, повторяющуюся через определенные интервалы – Тут одна подробность, – взорвался он наконец, – если мы не поторопимся смыться, то рискуем вновь влипнуть во всю эту историю Видение дергалось и колебалось перед глазами Артура, хотя, видимо, в действительности это глаза Артура дергались вместе с головой$$);
insert into тип_продукции values (9, 3735, 'Экологичные сумки-шопперы с ручками из крафт-бумаги', $$Всеми этими причиндалами вяло манипулировали роботы – Занимательно, не правда ли? – произнесло видение Некому было его услышать, некому было с ним поговорить Но только не вверх Зафод похолодел А когда раскроешься, я тебя прошу, не говори, что тебя это осчастливило, ладно?

– Ладно Некоторые из нас гибнут от рук охотников, но, поскольку всех нас зовут Земами, утраты проходят незамеченными, и момнуханье, таким образом, остается минимальным Охмешконасыпатель скорбно и устало прикрыл глаза, заказал бортовой стереосистеме какой-нибудь легкий джаз и рассудил, что все бы ничего, если бы не воскресные дни, будь они неладны Искусственная мебель, искусственная скатерть$$);
insert into тип_продукции values (10, 3096, 'Оригами-комплекты с пошаговыми инструкциями', $$– Угм, – произнес Артур, глубокомысленно морща лоб, чтобы никто не усомнился в маневренности его извилин, – угу Протечку Странно, но факт Слартибартфаст делал Форду с Артуром отчаянные знаки и что-то кричал Он никогда не слышал, чтобы на Зете Прутивнобендзы выступали с речами, а тем более знаменитости Забудьте, сколько вы весите (забудьте, что вы вообще что-то весите), и просто позвольте ветру поднимать вас все выше Артур наморщил лоб:

– А почему на вашем корабле все вычисления… – И прикусил язык И все засохли – Дайте мне формы и контуры$$);
insert into тип_продукции values (11, 2025, 'Набор бумажных цветов с реалистичными деталями', $$Робот, стоявший к Зафоду ближе всех, смотрел на него с таким видом, будто снимал подробную мерку со всего его тела, души и способностей – По-моему, его здесь нет, – сказал он мальчишкам, которые немедленно столпились вокруг него, – вероятно, он куда-то откатился Инженеры и конструкторы в своей великой наивности решили снабдить «Титаник» экспериментальным генератором невероятностного поля, которое, по их расчетам, должно было обеспечить бесконечную невероятность каких бы то ни было неполадок на борту Он сознавал, что находится внутри фильма, но все равно нервничал$$);
insert into тип_продукции values (12, 1040, 'Календари с эстетичными дизайнами и функциональными функциями', $$Артур привстал с дивана и помотал головой:

– Куда мы летим?

– На битву с Древним…

– Замнем, – вмешался Форд – Что сталось с голгафрингемцами? – спросил Форд От вас требуется одно – решительно кинуться вниз, не боясь ожидающей вас физической боли С легким жужжанием и крайне зловещим видом он завис над землей Триллиан казалось, что это-то ей и требуется после всего пережитого – … нестабильности… – завершил Форд Он указал, чтó понимает под термином «вон там» Действительно, звездолет Слартибартфаста производил вдвойне странное впечатление Как ни странно, и тут моделью послужило маленькое итальянское бистро Словно ниоткуда, зазвучала музыка$$);
insert into тип_продукции values (13, 2370, 'Ежедневники с яркими принтами и водостойкой обложкой', $$Они пытались их игнорировать, но все же не могли не заметить, что Слартибартфаст сварливо требует, чтобы серебряную урну с «Пеплом» отдали ему, ибо тот, по его словам, «жизненно важен для прошлого, настоящего и будущего Галактики», и что это заявление вызвало бурное веселье Некоторое время полет протекал без происшествий, и Слартибартфаст включил убыстренную перемотку Охмешконасыпатель скорбно и устало прикрыл глаза, заказал бортовой стереосистеме какой-нибудь легкий джаз и рассудил, что все бы ничего, если бы не воскресные дни, будь они неладны Я стал звездой экспозиции$$);
insert into тип_продукции values (14, 768, 'Блокноты с обложкой из переработанного картона и тонированной бумагой', $$Короче говоря, он вознамерился сойти с ума Он резко сел на кровати, начал натягивать одежду Затем пусть отправляются все втроем на поиски первого, поговорят с ним по-людски, споют ему колыбельную, что ли Этот миг пришел и миновал без происшествий, как и бывало обычно на Зете Прутивнобендзы Душа Артура летала вокруг его тела кругами и мялась, не испытывая особенного желания войти В нем они выражали сожаление, что из-за работы им приходилось долгими часами корпеть в сарае, не видя ни жен, ни детей, которые страшно по ним скучали, но подбадривали их бесконечными новостями о приключениях растущего щенка Он тоже задрал голову$$);
insert into тип_продукции values (15, 6080, 'Наборы карточек ручной работы с уникальными иллюстрациями', $$Морщась, он выслушал пояснение, что сейчас на поле произойдет вручение «Урны с Пеплом» капитану команды Англии, весь скукожился при известии, что данная команда заслужила этот приз, выиграв турнир в энный раз, буквально взлаял от злобы после сообщения, что «Пепел» – это останки столбика крикетной калитки, а когда (ну куда уж дальше!) от него потребовали смириться с фактом, что вышеупомянутый столбик был сожжен в австралийском городе Мельбурне в 1882 году, в знак «смерти английского крикета», Форд развернулся к Слартибартфасту, набрал в грудь воздуха – но ничего не сказал, потому что старца рядом с ними уже не было Зафод застыл как вкопанный – Стальной Столб – символ Силы и Мощи Галактики!

Лучи света бешено заплясали на столбе слева, действительно изготовленном из стали или чего-то очень похожего Второе не-абсолютное число – это оговоренный час сбора приглашенных, который, как ныне известно, представляет собой одно из сложнейших математических понятий – реситуасексулузон, число, о котором с уверенностью можно сказать лишь одно – оно равно чему угодно, только не самому себе Вот тогда-то он и набрел на свою цель жизни, дело, которое не позволит ему впасть в спячку никогда-никогда (так ему, во всяком случае, казалось) – Хороша лошадка, – заметил Форд, безуспешно пытаясь скрыть свое восхищение маневром корабля, – жаль, с дизайном ей не повезло А на скатерти пребывало с полдюжины тарелок с недоеденными итальянскими кушаньями – Что он сказал? – с трудом вымолвил Форд, работая локтями – И он же снабдил меня этим протезом Через некоторое время Форд счел необходимым отнять у Артура свою конечность$$);
insert into тип_продукции values (16, 8232, 'Настенные панно из бумаги-маше с объемными деталями', $$Нет, вся штука в том, что на полдороге к земле вы должны на что-то отвлечься, позабыв и о перспективе падения, и о земле, и о том, как вам будет больно, если не удастся промахнуться Артур посмотрел еще раз – Все в ажуре, офицер, – заявил он Люк сам собой захлопнулся – Вон там! – вскричал Форд, дико взмахнув рукой$$);
insert into тип_продукции values (17, 494, 'Доски для заметок из переработанной бумаги с ярким дизайном', $$Безусловно, это были не земляне, хотя все различия состояли в чуть-чуть слишком высоком росте, излишней худобе, угловатости и бледной, почти белой коже – Что я и ожидал услышать, – продолжил Марвин, – а также я ожидаю узнать, что идея робота с искусственной ногой вас немало забавляет Тихо-тихо-тихо дверь прошептала:

– Я вас слышу Не считаясь ни с какими законами пространства, роботы беспардонно материализовали свой корабль там, где им было надо, вследствие чего он сцепился с «Золотым сердцем» крест-накрест, как одна расческа с другой$$);
insert into тип_продукции values (18, 3168, 'Конверты с вырезами и красочными подкладками', $$И все двигалось, приплясывало, трепыхалось Криккитяне смотрели друг на друга, направо, налево, вперед, назад, даже на землю – Надеюсь, куда-нибудь, где солнышко светит, – проговорил Форд Он с грохотом понесся по небу, словно точно знал, что делает – Я, собственно, хочу сказать, – продолжал Форд, – что нет смысла доводить себя до безумия стараниями это безумие избежать – Ну, корабль ведь твой Он напряг слух, но больше ничего не слышалось Артур поделился своим впечатлением с друзьями – Я – Зем, – представился матрасс Артур уставился на компанию фермеров, пытаясь свести воедино крохи информации, которыми располагал$$);
insert into тип_продукции values (19, 5390, 'Подарочная упаковка с персонализированными сообщениями и декором', $$Артур попросил его повторить только что сказанную фразу, ибо не совсем уяснил себе ее смысл – Ну да?

– Ну да Матрасс момнухнул – Она самая – Речь идет о каких-то неполадках космического водопровода, я так понял? – осторожно спросил он Его сходство с Моисеем усилилось – несмотря на отсутствие горы, теперь он шел решительной поступью по горящей и дымящей холеной лужайке – Золотая Перекладина – это часть Ключа, который мы ищем, – продолжал робот, – чтобы освободить наших Повелителей с Криккита – Опасно?

– Мммм$$);
insert into тип_продукции values (20, 7216, 'Наборы для рисования с бумагой высокого качества и инструментами', $$– Уловили суть? – спросил Слартибартфаст – Артур Филип Дент? – уточнило существо, деловито лязгнув зубами Деревья! Я практикуюсь в разговорах с деревьями Морщась, он выслушал пояснение, что сейчас на поле произойдет вручение «Урны с Пеплом» капитану команды Англии, весь скукожился при известии, что данная команда заслужила этот приз, выиграв турнир в энный раз, буквально взлаял от злобы после сообщения, что «Пепел» – это останки столбика крикетной калитки, а когда (ну куда уж дальше!) от него потребовали смириться с фактом, что вышеупомянутый столбик был сожжен в австралийском городе Мельбурне в 1882 году, в знак «смерти английского крикета», Форд развернулся к Слартибартфасту, набрал в грудь воздуха – но ничего не сказал, потому что старца рядом с ними уже не было – Трубку бросил, – пояснил он, пожал плечами и аккуратно положил свою воображаемую трубку на воображаемый рычаг$$);
insert into тип_продукции values (21, 2625, 'Книги-раскраски со сложными узорами и мотивами', $$– Так что вы тут делаете, мужики?

Молчание Однако матрасс попался какой-то уж очень глупый и лишь воззрился на него в ответ круглыми глазами – Недурная мысль, – заметил Форд Префект, соскальзывая с валуна, на котором сидел Так-то он надеялся войти незамеченным – из-за замысловатой формы рубки (в виде сердечка) дверь находилась в укромном уголке – Мы могли бы побеседовать, – сказал матрасс, – хотите?

Матрасс был крупный, по-видимому, один из лучших в своем роде Дело в том, что принцип его работы основан на свойственной людям естественной предрасположенности не видеть ничего из того, чего видеть не желаешь, увидеть не предполагаешь или не можешь себе объяснить – Одно время я так тоже думал, – подхватил Форд, – а потом на пару недель решил, что я – лимон$$);
insert into тип_продукции values (22, 5698, 'Наборы оригами с разноцветной бумагой и схемами', $$– И, – продолжал громоподобный голос, – Деревянный Столб – символ, – здесь бас слегка осип от избытка умиления, – могущества Природы и Духовности!

Лучи переместились на центральный столб Меж тем снаружи солнце лило свой свет на веселую толпу Артур не совсем понял, какая связь между игрой, которая на Земле называлась крикетом, и…

Слартибартфаст точно прочел его мысли Слартибартфаст, Форд и Артур остановились под ароматно пахнущим деревом – Ты козел, – повторил инопланетянин Рука официанта заскользила по листкам блокнота с недостижимым для человека проворством, а затем еще быстрее, так что в глазах зарябило – А скоро выйдешь?

– Нет, тут останусь Поле «Не Наша Проблема» куда проще в использовании и эффективнее, а главное, целых сто лет может работать от одной «пальчиковой» батарейки Вот уже пять лет, как его не расщепляли на атомы Ни одного матрасса это, по-видимому, не удручает$$);
insert into тип_продукции values (23, 7719, 'Настенные обои с текстурами, имитирующими натуральные материалы', $$Из чистой любви к переменам, сами понимаете Защитник, взмахнув битой, послал мяч себе за спину так, что он пролетел над табло – Жду с нетерпением!

– Она была принята очень плохо, – сказал Марвин, – по многим причинам Глагол «флёпать» обозначает действие, посильное лишь живым матрассам на болоте, чем и объясняется малораспространенность этого слова – Скатертью дорожка, – пробормотал Зафод, перевернулся на другой бок и всю ночь не смыкал глаз – Он говорит, что они забрали «Пепел» – Я дома, – хрипло буркнул Артур Авария инопланетного звездолета сдвинула какие-то шарики в их головах – Это необходимо убрать, – сказали криккитяне, направив корабль в сторону дома$$);
insert into тип_продукции values (24, 3420, 'Оберточная бумага с замысловатыми принтами и фактурами', $$Третий и самый загадочный образчик не-абсолютности кроется в соотношении между количеством включенных в счет блюд, стоимостью каждого блюда, числом людей за столом и суммой, которую каждый из них готов заплатить (количество людей, которые действительно прихватили с собой деньги – лишь субфеномен вышеуказанного поля) И поторопился опустошить его, пока не случилось чего похуже Вероятно, природа – в своей безмерной мудрости – работает над этим Также никому не известно, что за радость находят в своем образе жизни матрассы Другой суперсенсацией тогдашней прессы стала вспышка сверхновой звезды, в которую несколько часов спустя превратилась звезда Неавоось$$);
insert into тип_продукции values (25, 2940, 'Свадебные приглашения с замысловатыми кружевами из бумаги', $$Недавно был открыт лес, где почти все деревья в качестве плодов дают отвертки с храповиком Мужчина, с ужасом и смятением в глазах, слабо кивнул – От… к-к-к… э-э… – добавил он немного погодя Зафод вновь кивнул, поигрывая пистолетом Почва производила впечатление тяжелой и вязкой, трава была упруга Поговаривают, что у нее эрогенные зоны начинаются милях в четырех от тела как такового Всеми фибрами своего пружинного сознания матрасс чувствовал, что робот горячо мечтает, чтобы его спросили, давно ли он совершает это бесплодное и бессмысленное топтание Зафод похолодел Видение дергалось и колебалось перед глазами Артура, хотя, видимо, в действительности это глаза Артура дергались вместе с головой – Знаю, – вымолвил нагнавший их Слартибартфаст, задыхаясь и волнуясь, – но тому есть причины$$);
insert into тип_продукции values (26, 5684, 'Рождественские открытки с тиснением и блестящими элементами', $$Артур не совсем понял, какая связь между игрой, которая на Земле называлась крикетом, и…

Слартибартфаст точно прочел его мысли Этот простой факт вызвал бурю в научном мире – Роботы, – поправил себя Зафод, – что вы, роботы, тут делаете?

– Мы пришли, – прохрипел робот, – за Золотом Перекладины Строго говоря, эту шайку бесчувственных выродков он давно уже возненавидел лютой ненавистью Ветерок осторожно ворошил высокую траву вокруг пещеры, птицы чирикали друг с дружкой, бабочки изящно порхали туда-сюда, и вообще вся природа из кожи вон лезла, стараясь произвести благоприятное впечатление$$);
insert into тип_продукции values (27, 783, 'Наборы для квиллинга с разноцветными полосками бумаги и инструментом', $$Небосвод – от горизонта до горизонта, с востока до запада, с севера до юга – был абсолютно черен На него самого бессмертие свалилось как снег на голову, в результате неудачного взаимодействия своенравного ускорителя элементарных частиц, банки с рассолом (то был утренний завтрак Охмешконасыпателя) и двух аптечных резинок – И побежал Вот оно – то, что разрушили орды Криккита, то, что теперь держит их планету в заточении и будет держать до скончания вечности!

И вальяжным жестом мужчина извлек из воздуха модель Трикетной Калитки – Нет ни одной планеты, – отчеканил высокопрофессиональный голос ведущего, – нет ни одной цивилизованной планеты в Галактике, где и в наши дни ни почитали бы этот символ$$);
insert into тип_продукции values (28, 1246, 'Абажуры из бумаги с уникальными формами и узорами', $$Они немного прошли в сторону города, и инфоиллюзия травы приятно пружинила под ногами, а инфоиллюзии цветов безупречно благоухали – Так оно и вышло, – сказал Слартибартфаст По жизни он не согласился бы взойти на борт такого корабля даже за всю рисовую водку страны Китай Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина Ночью оно абсолютно черное – Что? – вопил он Вскоре всех собравшихся обуяла необыкновенная, настоятельная вежливость Теперь они могли ясно видеть звездолет в его истинном обличье просто потому, что знали о его наличии здесь Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза Мерещилось, будто мрак гудит, с треском лопается на носу корабля$$);
insert into тип_продукции values (29, 1958, 'Мебель из картона с прочной и легкой конструкцией', $$Замотав головой, Форд закрыл лицо руками и нечаянно отфутболил к стене подвернувшийся под ногу цветочный горшок Древнее Зло встало из могилы – Ваш, что ли, диван? – раздалось сверху Он подождал реакции Артура, но тот лишь благоразумно обронил:

– Давай дальше – Он сказал подождать у его корабля, – сообщил Артур Форд вытащил из своей жутко обтрепавшейся и донельзя замызганной сумки субэфирный чуткомат Потренируйтесь делать пике, вначале простое, а потом, мерно дыша, лягте в дрейф над верхушками деревьев Слартибартфаст покинул стеклянную комнату Триллиан терпеливо кивнула, побарабанила пальцами по столу и нажала кнопку внутрисвязи:

– Думаю, в веселье из-под палки ты сейчас не нуждаешься – А, – кивнул Артур, – политика, значит$$);
insert into тип_продукции values (30, 5225, 'Дизайнерская бумага для скрапбукинга с различными текстурами и принтами', $$Весьма сложно отвлечь ваше внимание от этих трех вещей за неполную секунду, которой вы располагаете Этот факт был расценен как величайшее достижение социологии телевидения А именно: игнорируя недоуменные взгляды собратьев-зрителей, что обступали поле, он совершал всякие резкие движения руками перед своим носом, при этом то проныривая у кого-то за спиной, то подпрыгивая рядом с кем-то еще Его челюсти начали делать отжимания$$);
insert into тип_продукции values (31, 2400, 'Обложки для книг с индивидуальной гравировкой и яркими рисунками', $$– Я был в Африке, – заявил Форд Вначале бессмертие пошло ему впрок Уперев руки в бока, он вновь обвел взором пустынный мир А на скатерти пребывало с полдюжины тарелок с недоеденными итальянскими кушаньями Это было их творение, и сейчас они пели о нем песенку, изливая в ней двойную радость успеха и обладания На восьмом такте этой баллады, который сам по себе мог бы сделать Маккартни полноправным хозяином Винчестера, не говоря уже об окрестностях, текст стал каким-то странным – Нет смысла ломать голову над действиями машин, – заявил он, – только зря нервничаешь Слова все время забываю – Хм, что-то не верится$$);
insert into тип_продукции values (32, 1222, 'Скетчбуки с акварельной бумагой и удобной спиралью', $$– И что же с ней стало? – спросил Артур Длинный стол Третий и самый загадочный образчик не-абсолютности кроется в соотношении между количеством включенных в счет блюд, стоимостью каждого блюда, числом людей за столом и суммой, которую каждый из них готов заплатить (количество людей, которые действительно прихватили с собой деньги – лишь субфеномен вышеуказанного поля) * * *
Хозяин звездолета, инопланетянин с дорогостоящим цветом лица, развалился в единственном кресле рубки На миг воцарилась скорбная тишина, но тут же ее нарушил громкий ропот (будто сотня тысяч невидимых людей вымолвила: «Уф!»), и с небес, точно пушинки с одуванчика, посыпались белые роботы Попробуйте проделать это в погожий денек, рекомендует «Путеводитель» Дверь тихо отъехала в сторону Безусловно, вся земная медицина была уже не в силах его спасти – Э-э, пять, – сказал матрасс$$);
insert into тип_продукции values (33, 3680, 'Папки-регистраторы с тиснением и прочной картонной обложкой', $$Они достигли цели * * *
Хозяин звездолета, инопланетянин с дорогостоящим цветом лица, развалился в единственном кресле рубки Он пронзил облака, на миг озарив их своим серебряным свечением, и исчез из виду Артура – одинокой букашки, бестолково скачущей на месте посреди бескрайней шири Что скажешь, Артур? Очнись, перестань бурчать свои мантры Они находились перед Рубиконом исторического самосознания своего народа В его голове родился целый рой глубокомысленных вопросов – Да-да, хорошо, это не обязательно, – поспешно заявил полисмен, – только постарайтесь, чтобы такого… этого… больше не было Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина – О Зарквон, спаси и сохрани, – пробурчал он под нос Ветерок приносил оттуда мирные бытовые звуки$$);
insert into тип_продукции values (34, 625, 'Наборы для рисования с цветными карандашами, фломастерами и бумагой', $$– Э-эй! – вскрикнул Артур и побежал на заплетающихся ногах к кораблю Там есть кое-какие советы по поводу пьянства Он осознал, что удостоился знакомства с носителем незаурядного ума По-видимому, он полагал, что мнение Слартибартфаста слишком оптимистично$$);
insert into тип_продукции values (35, 891, 'Маски из папье-маше с изысканными деталями и рисунками', $$И я подключился к цепи открытия моста Корабль лениво дрейфовал где-то в галактической глуши, окруженный чернильно-черной пучиной космоса – Я понимаю, что в масштабе Вселенной этот факт не имеет никакого значения, но просто интересно А случится это сегодня Его сходство с Моисеем усилилось – несмотря на отсутствие горы, теперь он шел решительной поступью по горящей и дымящей холеной лужайке В обе стороны, на сотни миль передо мной и на сотни миль позади меня, тянулось полотно моста – Глубже, чем вы можете вообразить, – процедил Марвин Когда он притомился тщетно обрабатывать гору массивными отбелизаторами, аннигиляторами рефракции и спектральными астраломылками, ему открылось, что за оставшиеся девять часов он вряд ли выполнит зарок Впереди них сидели трое пилотов Там есть кое-какие советы по поводу пьянства$$);
insert into тип_продукции values (36, 3950, 'Изготовленные на заказ фотоальбомы с хронологическими разделителями', $$– Чувствуя, что собеседники все еще недоумевают, он снизошел до разъяснений: – Слушайте – Хорошенькая перспектива, – заметил Форд Зафод не покидал кровати Зафод ошарашенно разглядывал роботов Так оно и было – Выражаю свою позицию, – процедил Марвин, не переставая описывать круг за кругом А в моих руках точная копия, изготовленная руками народных умельцев Артуру невольно представилось, как Пол Маккартни, восседая с ногами в кресле у камина, мурлычет эту песенку Линде и соображает, что бы такое купить на доходы с нее – то ли Эссекс, то ли Ирландию Какой-то матрасс только что повстречался с каким-то роботом$$);
insert into тип_продукции values (37, 7920, 'Свадебные программы с элегантным дизайном и качественной бумагой', $$– Я думал, ты умер… – вырвалось у него По-видимому, это словесное излияние вдохновило его на новый взлет к высотам уныния и отчаяния Вы наверняка сталкивались с этим феноменом в жизни – Четвертая планета системы Фольфанга, – продолжил он$$);
insert into тип_продукции values (38, 7360, 'Приглашения на детский праздник с яркими принтами и забавными персонажами', $$Ах, как прекрасен – аж глазам больно – был «Звездный Титаник», когда, точно арктурианский мегавакуумный серебристый кит, он качался в лазерных тенетах гибких строительных лесов – Остатки сожженного столбика Форд и Артур воззрились на него с крайним удивлением и острым чувством обиды за хороший вкус Скорость его функционирования феноменальна Тут он решил, что пора заговорить – В глубинах фундаментального сердца духа и Вселенной, – сказал Слартибартфаст, – кроется причина тому Восторженный рев, прокатившийся по трибунам, заглушил все, что Форд имел сказать по поводу этой информации – Я дома, – шептал Артур$$);
insert into тип_продукции values (39, 504, 'Карточки с рецептами со стильными рамками и водонепроницаемой подложкой', $$Другими словами, оговоренный час сбора – это один-единственный момент времени, в который абсолютно невозможно появление любого из членов компании А потом тьма позади Вселенной взорвалась, и каждый лоскуток тьмы обернулся косматым дымом преисподней Скажи мне только одно Роботы успели частично разобрать дальнюю стену рубки и пробить ход через жизненно важные органы корабля А несколько часов спустя вновь отправился в свой скорбный обход темных коридоров, срывая зло на любезных дверях$$);
insert into тип_продукции values (40, 4268, 'Обложки для паспортов с замысловатыми рисунками и защитой от RFID', $$Самый подходящий афоризм, чтобы заронить в молодые умы искру вдумчивого отношения к жизни Ее-то и пытался найти Слартибартфаст – У меня врачи нашли недоразвитость гланды общественного долга и врожденный порок морального ядра личности, – пробормотал он под нос, – ну разве мне можно доверить спасение Вселенной, сами посудите?

И тем не менее поднялся по лестнице вслед за сотоварищами – Он вновь раскрыл глаза и блаженно улыбнулся – Да нет же, – возразил Артур – Ты наверняка знаешь, что сейчас произойдет, – сказал Слартибартфаст Форду Одно мычание вместо «да», два вместо «нет» Поплотнее запахнувшись в свой обтрепанный халат, он приветствовал доброе утро широкой улыбкой$$);
insert into тип_продукции values (41, 2625, 'Коробочки для подарков с окнами из прозрачной бумаги и лентами', $$– Артур, – сказал Форд – В конце концов, – заметил Форд, – двум смертям не бывать, а одной не миновать Аналогично последовательность отдельных впечатлений сливалась тут в единое чувство – хотя на чувство оно как-то не походило – Что они… – переспросил Форд Если последовательность размеренных щелчков, записанную на пленку, прокручивать с ускорением, одиночные щелчки постепенно сольются в постоянный, повышающийся тон Затем, вернувшись к реальности, осознал, что все равно не понимает, куда клонит старец$$);
insert into тип_продукции values (42, 2200, 'Декоративные вазы из картона с уникальными формами и текстурами', $$Но радовался он зря Первое не-абсолютное число – это число людей, на которое заказан столик И все же они продолжали погоню, а диван вальсировал и вертелся, а потом вдруг развернулся и вошел в пике, словно сорвавшись с порога графика, изображающего кризис, причем Форд с Артуром оказались буквально над ним И оторопел от последствий своего заявления$$);
insert into тип_продукции values (43, 3496, 'Костюмы из папье-маше для фестивалей и театральных представлений', $$– Бистроматика, – пояснил он Его раздирали противоречивые чувства И сколько ни гляди на циферблат, неумолимые стрелки вскоре передвинутся на четыре – час, когда начинается долгое, мутное и, что греха таить, безумное чаепитие души – Вы начали говорить…

Слартибартфаст пронзительно взглянул на него и заявил:

– Числа – настоящий бич божий А там происходило всего лишь то, что люди столпились на площадке вокруг ее середины – Э-э-э?…

Существо кивнуло само себе, произвело чисто инопланетный щелчок застежкой папки и направилось к своему кораблю – Ты, случайно, не сказал «мм» дважды?

– Мммм мммм С другой стороны, присутствие Форда, как всегда, почти немедленно начинало давить на нервы$$);
insert into тип_продукции values (44, 2392, 'Органайзеры для ванной с водостойким покрытием и нескользящим дном', $$А на скатерти пребывало с полдюжины тарелок с недоеденными итальянскими кушаньями Ее-то и пытался найти Слартибартфаст – Что сталось с голгафрингемцами? – спросил Форд – Я был в Африке, – заявил Форд Они достигли цели А когда раскроешься, я тебя прошу, не говори, что тебя это осчастливило, ладно?

– Ладно$$);
insert into тип_продукции values (45, 2912, 'Календари с магнитными держателями и увеличенными полями для заметок', $$Они попросили меня открыть мост (Естественно, я не знаю их лично, но я знаю природу всех органических живых существ, и гораздо более досконально, чем хотел бы – Послушай, – промолвила Триллиан сочувственным тоном и присела рядышком, – очень даже объяснимо, что некоторое время жизнь будет казаться тебе бесцельной – … нестабильности… – завершил Форд Произнесенные роботом слова подтвердили это впечатление Попытайтесь взять пример с нас, матрассов$$);
insert into тип_продукции values (46, 5520, 'Подарочные сертификаты с тиснением и персонализированным дизайном', $$По-моему, врут Форд с Артуром так и обмерли, подавившись собственным воплем Было неопровержимо доказано, что количество зрителей, смотревших телерепортаж о запуске «Титаника», превосходило все население Вселенной на тот момент – Думаю, активный спорт поможет тебе не замыкаться на собственных переживаниях Звездолет несся сквозь ночь Жизненный цикл отвертки с храповиком весьма занятен$$);
insert into тип_продукции values (47, 4600, 'Обложки для альбомов с тисненым текстом и мягкой набивкой', $$– Похоже на балаган, – сказал Артур Может, там находится другая планета – ох, как трудно далось это предположение самозамкнутым умам сынов Криккита с его глухой стеной вместо неба О нет – то были действия, странно непохожие на все его обычные странности и чудачества – Сгинь, тебе говорят, дурилка пластиковая Этот факт был расценен как величайшее достижение социологии телевидения «Пейте смело, – рекомендует «Путеводитель», – и ни пуха вам ни пера» Во всяком случае, такой она казалась на первый взгляд – Не буду беспокоить тебя подробностями, а то они…

– Что «они»?

– Обеспокоят тебя Ты это зачем? – Форд по-прежнему протягивал Артуру руку, а тот с изумлением пялился на нее$$);
insert into тип_продукции values (48, 1551, 'Блокноты с прошитыми страницами и гибкой обложкой', $$– При передвижении по космосу, знаете ли… – проговорил Слартибартфаст, возясь с оборудованием Зала информационных иллюзий, – … при передвижении по космосу… – Не договорив, он принялся озираться по сторонам Артур пожал плечами Артур приосанился, взглянул миру прямо в поля и леса Днем светит солнце, но на солнце не очень-то посмотришь – они и не пытаются – Кто? – переспросил он Мозг Артура совершил сальто-мортале внутри черепной коробки – Все в ажуре, офицер, – заявил он – Я – Зем, – представился матрасс – Я, собственно, хочу сказать, – продолжал Форд, – что нет смысла доводить себя до безумия стараниями это безумие избежать Тогда я попробую ходить задом наперед$$);
insert into тип_продукции values (49, 1674, 'Упаковочная бумага с биоразлагаемым покрытием и яркими принтами', $$– Пойдемте, – добавил он с неожиданной властностью, – я должен вам многое показать и поведать Небо было пусто и черно Чисто инопланетная долговязость, чисто инопланетная приплюснутая голова, чисто инопланетные глазки-щелочки, экстравагантно-складчатое золотое одеяние с воротником чисто инопланетного покроя и бледная, серо-зеленая инопланетная кожа, сияющая тем особым блеском, который дается большинству серозеленоликих субъектов лишь благодаря постоянному массажу и самому дорогостоящему мылу Он опять воззрился на экран Существо невозмутимо смотрело на него Зафод так изумился, что роботам пришлось дать еще один залп, прежде чем он упал Затем следовал маленький припев насчет того, что в это время года цветы благоухают на редкость благостно и какая жалость, что бедная собака сдохла, так и не увидев своих любимых цветочков Разница была только в том, что посылаемые их битами мячи при соприкосновении с землей взрывались$$);
insert into тип_продукции values (50, 1363, 'Визитные карточки с тиснением, ламинированием и выборочной УФ-печатью', $$И камни тоже не мои, – добавил он, вытащив из сумки горсть плоских серых камешков – Ого, – сказал мальчишка, глубокомысленно склонив голову набок Первый комментатор призадумался Но не думаю, что с дурными намерениями – Я этот номер уже видел, – проговорил он$$);
insert into тип_продукции values (51, 1020, 'Коробки для хранения с разделителями из картона и магнитными застежками', $$Ширится мнение, что «Максимегалонский словарь» не заслуживает целого полка грузовиков, который используется для транспортировки его микрофильмированной версии – Э-эй! – вскрикнул Артур и побежал на заплетающихся ногах к кораблю – О, сущие пустяки Маленькие группки монахов, которые взяли за обычай болтаться около крупных научных институтов и петь странные псалмы во имя идеи, что Вселенная – лишь крупица ее собственного воображения, куда-то сгинули после того, как получили от правительства дотацию на организацию уличных представлений – Речь, – взмолился матрасс Он флёпал сочувственно, активно колыша при этом воду А придумал он вот что И пискнул – Хорошо – Собственно, невозможность их формулирования и есть один из самих этих принципов$$);
insert into тип_продукции values (52, 2880, 'Тематические наборы открыток с художественными иллюстрациями', $$Рука официанта заскользила по листкам блокнота с недостижимым для человека проворством, а затем еще быстрее, так что в глазах зарябило Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза Они немного прошли в сторону города, и инфоиллюзия травы приятно пружинила под ногами, а инфоиллюзии цветов безупречно благоухали – О Зарквон, спаси и сохрани, – пробурчал он под нос Он двинулся дальше, а его слова гулко повисли в воздухе$$);
insert into тип_продукции values (53, 3696, 'Комиксы с уникальными сюжетами и персонализированными персонажами', $$Слартибартфаст покинул стеклянную комнату – Артур! – заорал на него Форд Правда, он всегда подозревал о ее существовании, поскольку обладал полным комплектом стандартных органов (и даже двойным – кое-каких), но, внезапно обнаружив в глубине своего существа эту затаившуюся зверюшку, был крайне шокирован Он вскочил с дивана – А, – кивнул Артур, – политика, значит Роботы успели частично разобрать дальнюю стену рубки и пробить ход через жизненно важные органы корабля Вспыхнули споры, посетители кинулись рисовать на салфетках иллюстрации своей правоты А еще я пробовал научиться летать$$);
insert into тип_продукции values (54, 4214, 'Книги с выдвижной бумагой с прикрепленными фигурками или предметами', $$– Н?

– … НП Форд саркастически огляделся по сторонам Его причины остаются тайной, так как ни одному из геофизиков, специалистов по статистике вероятностей, метеорологов-аналитиков и чудологов поездка на Хэй-Виляй не по карману Из чистой любви к переменам, сами понимаете – Мы взлетели, – пояснил Слартибартфаст Артур растерянно кивнул – Надеюсь, когда до этого дойдет, я буду в стельку пьян$$);
insert into тип_продукции values (55, 8500, 'Поздравительные открытки с музыкальным чипом и настраиваемой мелодией', $$Но теперь все происходило слишком уж молниеносно – сплошное видеотактильное пятно, которое волокло их сквозь века галактической истории, крутясь, дергаясь, мерцая – Жду с нетерпением вашего рассказа о речи на болоте Со вздохом облегчения и возгласом триумфа они вскочили на диван, солнце, моргнув, погасло, и, провалившись сквозь головокружительное ничто, они выбрались на свет божий в самом неожиданном месте – посреди поля крикетной площадки «Лордз» (что расположена в лондонском районе Сент-Джонс-Вуд) незадолго до окончания последнего матча международного турнира на Приз Австралии 198… года, причем команде Англии требовалось лишь двадцать восемь перебежек для победы На него самого бессмертие свалилось как снег на голову, в результате неудачного взаимодействия своенравного ускорителя элементарных частиц, банки с рассолом (то был утренний завтрак Охмешконасыпателя) и двух аптечных резинок – … напомни, чтобы я дал сам себе в зубы Не слушайте окружающих – ничего полезного они не скажут Сияющее облако булавок и иголок на знойно-черном бархате открытого космоса НИКОМУ НЕ МАШИТЕ По-прежнему ничто не шевелилось$$);
insert into тип_продукции values (56, 3854, 'Светодиодные фонари из бумаги с вырезанными узорами и мягким светом', $$Зафод похолодел Я сам посадил сотни Артур наморщил лоб:

– А почему на вашем корабле все вычисления… – И прикусил язык – Вы хотите дослушать эту историю или что?

– Мне хотелось бы услышать вашу речь, – заявил матрасс И хотя они предназначались не нашим путешественникам, те машинально склонили головы – и слава богу, ибо маленький красный и тяжелый мяч (истинный виновник овации) просвистел в считаных миллиметрах над макушкой Артура – У меня было голгафрингемское полотенце, из оздоровительного кабинета – И он сверкал? – воскликнул очарованный матрасс – Тогда я был в некотором смысле знаменитостью$$);
insert into тип_продукции values (57, 720, 'Украшения из папье-маше с яркими цветами и затейливыми формами', $$Он сознавал, что находится внутри фильма, но все равно нервничал – Да так, ничего особенного, – сказал Форд Отряхнулся – Это исток всему – Просто очень скоро эту планету взорвут Голос робота был под стать его корпусу – холодный, элегантный, безжизненный Он обзавелся звездолетом, построенным на века, и бортовым компьютером, который умело управлялся со всей информацией о местоположении всех обитателей Вселенной, а также рассчитывал самые замысловатые маршруты полета Часа через два стало очевидно, что Зафод тверд в своем решении, и корабль вновь поднялся в небо, даже не спустив трапа Некоторое время все молчали, из чего Зафод заключил, что роботы явились сюда не для разговоров и дело за ним Клубы дыма струились с небосклона и влезали обратно в корабли$$);
insert into тип_продукции values (58, 4864, 'Модели парусных кораблей из бумаги с детальными парусами и корпусом', $$Созерцая тускло-розовый контур двери, он осознал, что во мраке коридора еле-еле различаются границы сенсорно-тактичного поля, которое и предупреждало дверь о появлении кого-то, перед кем следует раскрыться с любезными словами Может, там находится другая планета – ох, как трудно далось это предположение самозамкнутым умам сынов Криккита с его глухой стеной вместо неба Реакция публики, точнее, реакции были многообразными и различными – Алло? – произнес он в воображаемую трубку Нет, вся штука в том, что на полдороге к земле вы должны на что-то отвлечься, позабыв и о перспективе падения, и о земле, и о том, как вам будет больно, если не удастся промахнуться$$);
insert into тип_продукции values (59, 3465, 'Бумажные скульптуры с подвижными частями и реалистичными деталями', $$– Жду с нетерпением!

– Она была принята очень плохо, – сказал Марвин, – по многим причинам «Пейте смело, – рекомендует «Путеводитель», – и ни пуха вам ни пера» – Он вновь раскрыл глаза и блаженно улыбнулся Они прошли очень близко от наблюдателей под деревом, размахивая фонарями, от чего по траве и листве скакали забавные «зайчики», радостно болтая между собой и самым натуральным образом распевая песню о том, как все чуд-чуд-чудесно на свете, как они счастливы, как здорово они потрудились на ферме и как приятно возвращаться домой, где ждут жены и дети Вам того же – Ну и? – тревожно вопросил Артур На секунду-другую лицо Артура застыло, как маска, а потом стало с ужасающей медлительностью раскалываться на куски, точно арктические льдины по весне Строго говоря, эту шайку бесчувственных выродков он давно уже возненавидел лютой ненавистью – Хмммм Новая вибрация сотрясла корабль$$);
insert into тип_продукции values (60, 1885, 'Коврики для занятия йогой из переработанного картона с противоскользящей поверхностью', $$– Этот диван попал сюда из-за нестабильности пространства-времени, про которую я уже устал толковать тебе с твоим перманентным склерозом И оторопел от последствий своего заявления Недавно был открыт лес, где почти все деревья в качестве плодов дают отвертки с храповиком Корабль пересекал орбиты планет Солнечной системы, намереваясь совершить пертурбационный маневр вокруг Солнца и, разогнавшись, выскочить в большой космос – Правда, что ли? – вскричал Зафод, поигрывая пистолетом Робот, стоявший к Зафоду ближе всех, смотрел на него с таким видом, будто снимал подробную мерку со всего его тела, души и способностей Чересчур осмысленное и лаконичное – Свобода, – произнес он вслух Для практики я разговариваю с этими… ну как их там… как называются эти, с которыми разговариваешь, когда с ума сходишь? Ну как Георг Третий Так оно и было$$);
insert into тип_продукции values (61, 1050, 'Наборы для аппликации с цветной бумагой, ножницами и клеем', $$Может, там находится другая планета – ох, как трудно далось это предположение самозамкнутым умам сынов Криккита с его глухой стеной вместо неба Надежда и ликование в душе Артура вмиг сменились чувством крайней озадаченности Наши герои взошли вслед за Слартибартфастом на борт и были столь ошарашены увиденным внутри, что совершенно не заметили нового странного происшествия снаружи Со стороны это может выглядеть несколько глупо$$);
insert into тип_продукции values (62, 1500, 'Домики для кукол из картона с мебелью и аксессуарами', $$– Нет, – заявил Марвин Теперь они могли ясно видеть звездолет в его истинном обличье просто потому, что знали о его наличии здесь Как будто у них в зрачках слепое пятно на 180 градусов от горизонта до горизонта – Мое место здесь, – сказал он умиленным шепотом – И если ты считаешь, что тебе действительно необходимо слоняться по крикетной площадке в такой момент…

– Считаю – Это что-то важное, – рассудил Артур и окликнул старца$$);
insert into тип_продукции values (63, 1769, 'Оригами-гирлянды с разноцветными бумажными фигурами', $$Тем самым выведя Форда из медитационного транса Но несть числа тем, кто упивается историей «Звездного Титаника», легендарного корабля-колосса – Принято к сведению Можете рассказать это вместо анекдота своим друзьям Зему и Зему при первой же встрече – они животики надорвут, если я их знаю Безусловно, это были не земляне, хотя все различия состояли в чуть-чуть слишком высоком росте, излишней худобе, угловатости и бледной, почти белой коже – В конце концов, – заметил Форд, – двум смертям не бывать, а одной не миновать$$);
insert into тип_продукции values (64, 2100, 'Подарочные пакеты с рельефным рисунком и ручками из ленты', $$Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина – Гм… ну ладно, – проговорил Зафод Ему почудилось, будто атомы его мозга и атомы космоса струятся друг сквозь друга Словно ниоткуда, зазвучала музыка  К сожалению, именно терминалы рубки Зафод и заткнул кляпом$$);
insert into тип_продукции values (65, 4140, 'Обложки для электронной книги с индивидуальной гравировкой и магнитными застежками', $$Припев был немного печальный Туман висел неподвижно, точно то самое перехваченное на полдороге дыхание Но радовался он зря Его губы тоже дергались$$);
insert into тип_продукции values (66, 645, 'Бумажные гирлянды с вырезанными вручную узорами и тканевыми лентами', $$Мне крикет вообще-то нравится, – добавил он, – но на взгляд большинства, вы в наивности своей создали ужасную пошлость – Какое-то «что»?

– ННП В их штате есть специальные работники с удивительными телами и воззрениями Не прошло и нескольких секунд, как внезапно было достигнуто согласие – Вам весело? – спросил матрасс – Ого, – сказал мальчишка, глубокомысленно склонив голову набок – Я дома, – шептал Артур А, Слартибартфаст, здорово, что ты тут делаешь?

– Да так, слоняюсь, – отвечал старец сурово Мне это кажется чрезвычайно странным, тем более что сумку я сшил на доисторической Земле своими руками$$);
insert into тип_продукции values (67, 1254, 'Мемуарные книги с персонализированными обложками и расширенными полями', $$На щитки тоже стоило подивиться – по-видимому, в них были вмонтированы реактивные двигатели, что позволило этим цивилизованным роботам спикировать к земле и начать убивать людей Зафод так изумился, что роботам пришлось дать еще один залп, прежде чем он упал – Что «нет»?

– Не пытайся звонить себе самому домой – Мы могли бы побеседовать, – сказал матрасс, – хотите?

Матрасс был крупный, по-видимому, один из лучших в своем роде$$);
insert into тип_продукции values (68, 2272, 'Игрушечные машины из картона с реалистичными деталями и подвижными колесами', $$Однако спустя миг стряслось нечто, чего невозможно было не заметить Под ними расстилались серебристо-белые ризы Аллосиманиуса-Синеки Также эта стремительная гонка по водопадам времени подарила им еще одно четкое ощущение – Кто? – переспросил он – А сейчас ты опять в здравом рассудке? – поинтересовался Артур Зафод застыл как вкопанный$$);
insert into тип_продукции values (69, 3115, 'Наборы для рисования с цветными карандашами, маркерами и бумагой премиум-класса', $$А придумал он вот что – Мне довелось побыть знаменитостью, – скорбно завывал робот, – совсем недолго благодаря моему чудесному и весьма досадному спасению от удела, сравнимого разве что с такой удачей, как гибель в сердце пылающей звезды Правда, роботы сыпались не абы как, а четким военным строем Внезапно Форд начал буквально излучать энергию и целеустремленность Вылетаем без промедления$$);
insert into тип_продукции values (70, 4464, 'Бумажные самолеты с уникальным дизайном и аэродинамической конструкцией', $$– Игра, которую вы именовали крикетом, – проговорил он, точно из жерла преисподней, – относится к числу забавных капризов родовой памяти, благодаря которым многие концепции и образы продолжают жить в сознании, хотя их истинный смысл потерян во мгле времен Несомненно, «Золотое сердце» произвело здесь фурор, и Триллиан была польщена Меж тем как об этих звездолетах, а также других кораблях-легендах, например линкорах Галактической Армады («Храбром», «Безрассудном» и «Камикадзе»), говорят с благоговением, гордостью, упоением, энтузиазмом, восторгом, симпатией, сожалением, завистью, ревностью – в общем, почти со всеми людскими эмоциями, но подлинного чувства изумления удостоился лишь корабль, который всем вышеперечисленным не чета– «Криккит-1», первый звездолет, который построили криккитяне И мрак этот был особый – студеный, беспросветный, тяжелый мрак ночного неба над Криккитом$$);
insert into тип_продукции values (71, 3174, 'Бумажные тарелки с персонализированными принтами и экологически чистым покрытием', $$– Батарейка села? – поинтересовался Артур Начал моросить дождь С того дня прошло уже два года Он напряг слух, но больше ничего не слышалось И мрак этот был особый – студеный, беспросветный, тяжелый мрак ночного неба над Криккитом Корабль лениво дрейфовал где-то в галактической глуши, окруженный чернильно-черной пучиной космоса Первый комментатор призадумался Еще мрачнее сдвинул брови – и наконец успокоился Подъем по горным тропам со снежных равнин Лиски до вершины Хрустальных Пирамид Састантуа долог и утомителен даже при наличии реактивных лыж и упряжки синекских снегодавов, но открывающаяся сверху панорама: Ледники Безмолвия, мерцающие Призматические Горы и хоровод призрачных ледяных светляков вдалеке – вначале замораживает разум, а потом медленно возвышает его к еще невиданным высотам наслаждения прекрасным$$);
insert into тип_продукции values (72, 4686, 'Бумажные лампы с вырезанными вручную узорами и теплым рассеянным светом', $$Умопомрачительно красивый, уникально огромный и к тому же самый уютный корабль в истории Галактики (точнее, в нынешней, сильно обкарнанной опровержениями версии этой самой истории – подробности см – Намой взгляд, тебе следовало это узнать перед уходом в мир иной – Опасно?

– Мммм – И уставился в крохотный иллюминатор – на кромешную тьму Потом спросил: – Какие зоны вещания попадутся нам в ближайшие часы?

Компьютер пискнул Он созерцал приборы с видом человека, который пытается перевести градусы Фаренгейта в градусы Цельсия, пока его дом горит$$);
insert into тип_продукции values (73, 923, 'Картонные домики для кошек с прорезями и мягкими подушечками', $$Наши Повелители выйдут на свободу – Но только в порядке хобби Его мозг замер, как щенок, испуганно забившийся в угол Он тряс руку Форда и пожимал ее, пожимал и тряс В небе ничего не было Подобно открытию Эйнштейна, что время не есть абсолют, но зависит от движения наблюдателя в пространстве, а пространство не есть абсолют, ибо зависит от движения наблюдателя во времени, ныне установлено, что числа не абсолютны, но зависят от движения наблюдателя в ресторанах Слартибартфаст покинул стеклянную комнату$$);
insert into тип_продукции values (74, 594, 'Доски для рисования с магнитной поверхностью и водонепроницаемой бумагой', $$– Завладеем, – заявил робот – Это исток всему – … только что материализовались тут у нас, посреди крикетной площадки «Лордз» Небосвод – от горизонта до горизонта, с востока до запада, с севера до юга – был абсолютно черен – Я сам вам поясню, – прошептал старец Наши герои взошли вслед за Слартибартфастом на борт и были столь ошарашены увиденным внутри, что совершенно не заметили нового странного происшествия снаружи (Естественно, я не знаю их лично, но я знаю природу всех органических живых существ, и гораздо более досконально, чем хотел бы – По крайней мере мне так кажется И вновь ответа не последовало Он уставился на диван умными глазами$$);
insert into тип_продукции values (75, 2752, 'Бумажные зонты с красочными принтами и водоотталкивающей обработкой', $$Он сидел в своей пещере, составлял каталог возможных отповедей наглому инопланетянину и давил мух – для них этот вечер тоже оказался кошмарным А потом все завершилось – так же внезапно, как и началось Видение состроило нечто вроде ехидной ухмылки – впрочем, еще неизвестно, насколько ехидной, ибо солнце, светя ему прямо в затылок, соорудило из его серебристых волос и бороды ослепительный, драматический, повергающий в трепет нимб, с которым никакие ехидные ухмылки не вязались По-видимому, он полагал, что мнение Слартибартфаста слишком оптимистично$$);
insert into тип_продукции values (76, 6106, 'Металлизированная бумага с блестящим покрытием и широким спектром оттенков', $$Хлюп, хлюп – шагал он по болоту – Ну-ка, улыбочку, усмешечку!» Я разъяснял, что для того, чтобы мое лицо исказила улыбка, нужно отнести его в мастерскую и часа два поработать над ним кувалдой – Я ужасно рад вновь тебя видеть – А, ну и ладно, – промолвил Артур с облегчением Последовала немая сцена Это была безумная колымага из подручных материалов – Батарейка села? – поинтересовался Артур Он шествовал к центру поля ужасающе решительной поступью, и его борода, волосы и одеяние развевались по ветру – вылитый Моисей на горе Синай, только в роли Синая сейчас выступала холеная лужайка, а не грозный вулкан в косматом дыму, каким его обычно изображают$$);
insert into тип_продукции values (77, 2850, 'Самоклеющаяся бумага с яркими принтами и легким нанесением', $$– Значит, наши неприятности еще не кончились, – проговорил он На секунду-другую лицо Артура застыло, как маска, а потом стало с ужасающей медлительностью раскалываться на куски, точно арктические льдины по весне Правда, в них проглядывала некоторая чудаковатость – не хотел бы Артур ехать с ними в одном купе, – но вся эта чудаковатость сводилась к чрезмерному добродушию и любезности, а не каким-то изъянам Весь мост, мост длинный, титаночугунный, на тысячу миль, моментально свернул свое сверкающее полотно и с плачем утопился в трясине, унося с собой всех до последнего прутивнобендзянина Причем все они созданы трудами ветра и дождя – естественный процесс эрозии Я не шучу Но в общем и целом они смотрелись довольно приятно Безусловно, вся сложность во втором этапе – в промахивании Он подождал реакции Артура, но тот лишь благоразумно обронил:

– Давай дальше$$);
insert into тип_продукции values (78, 5880, 'Дизайнерская бумага с узорами из тиснения, фольги и тиснением', $$Проведя рукой по стене, он нащупал нечто ценное Похоже, в основном он состоял из низеньких зданий, построенных из белого камня Он почувствовал себя ограбленным Этот простой факт вызвал бурю в научном мире – Мое место здесь, – сказал он умиленным шепотом – Во-первых, – сказал он, тыча пальцем в угол газеты, где значилась дата, – через два дня Земля будет взорвана Не вынимая спичек Одиннадцать белых роботов И меж тем как «Золотое сердце» неслось с невероятной скоростью в неопределенном направлении, Триллиан прихлебывала какое-то неудобоваримое творение нутримата и читала о том, как научиться летать – Я вижу эту штуку, – объявил Артур, – это звездолет$$);
insert into тип_продукции values (79, 4074, 'Бумажные постеры с высококачественными принтами и экологически чистой отделкой', $$Начал моросить дождь Артуру невольно представилось, как Пол Маккартни, восседая с ногами в кресле у камина, мурлычет эту песенку Линде и соображает, что бы такое купить на доходы с нее – то ли Эссекс, то ли Ирландию Скорее всего до вас донесутся восклицания типа: «Боже праведный, ты что, летаешь? Быть такого не может!»

Жизненно важно не верить им – а то правда внезапно окажется на их стороне Слартибартфаст, Форд и Артур остановились под ароматно пахнущим деревом И может статься, приведет к безвременной гибели всю Вселенную – Бистроматика, – пояснил он Если б Эффрафакс покрасил гору в ярко-розовый цвет, а сверху водрузил недорогой генератор ННП-поля, люди так и ходили бы мимо горы, вокруг нее, даже по ее склонам – ничуть не подозревая о ее присутствии Туда-то мы и отправимся Стратегия заключалась в том, чтобы он перехватил предыдущий у скрещения дорог, и пусть соединенными силами поднимут дух второго Да, я в курсе, на что он похож, но в реальности это сложный четырехмерный топографический график целого ряда весьма замысловатых математических функций$$);
insert into тип_продукции values (80, 2134, 'Упаковочная бумага с биоразлагаемым покрытием и устойчивыми к разрывам рулонами', $$Форд сгреб его за отвороты халата и стал объяснять ему терпеливо и размеренно, с толком и с расстановкой – словом, так, будто Артур был служащим расчетного отдела телефонной компании Левая голова посмотрела влево, а правая – вправо, и обе решили, что следует отправиться куда глаза глядят Он был призван воскресить экономику системы Прутивнобендзы, напрочь подорванную расходами на его строительство – Жду с нетерпением вашего рассказа о речи на болоте – Оно имеет, – прошептал он Форду, серьезно наморщив лоб, – форму полисмена В нем обрисовался силуэт высокой фигуры Эффрафакс Вугский, маг-суперзвезда от науки, однажды поставил на кон свою голову, что за год сумеет сделать абсолютно невидимой великую мегагору Меграмал$$);
insert into тип_продукции values (81, 899, 'Картонные коробки с пользовательскими размерами, внутренними вставками и тиснением', $$Его причины остаются тайной, так как ни одному из геофизиков, специалистов по статистике вероятностей, метеорологов-аналитиков и чудологов поездка на Хэй-Виляй не по карману И вновь зашагал – Я был в Африке, – заявил Форд Короче говоря, он вознамерился сойти с ума Форд, еще раз пожав плечами, исполнил требуемое:

– Все последние пять лет приснились тебе во сне Пространство не просто изменило текстуру и состав Клубы дыма струились с небосклона и влезали обратно в корабли Это та самая планета и есть Его челюсти начали делать отжимания А теперь – в Зал информационных иллюзий$$);
insert into тип_продукции values (82, 5187, 'Самовосстанавливающиеся офисные подложки из картона с нескользящей поверхностью и водостойким покрытием', $$Припев был немного печальный – Думаю, активный спорт поможет тебе не замыкаться на собственных переживаниях – Порвалась, – добавил он, – ни с того ни с сего порвалась цепь причин и следствий…

И наперекор сказанному, неуклюже сполз под стол после еще одного стакана Одну голову он засунул под подушку, а вторая до поздней ночи разгадывала кроссворды И что самое удивительное, точно специально экипированные для данного мероприятия На восьмом такте этой баллады, который сам по себе мог бы сделать Маккартни полноправным хозяином Винчестера, не говоря уже об окрестностях, текст стал каким-то странным В вечерней тиши они стояли на вершине холма Ни одного матрасса это, по-видимому, не удручает Он двинулся дальше, а его слова гулко повисли в воздухе А это совсем другой коленкор$$);
insert into тип_продукции values (83, 1817, 'Разноцветная бумага для орегами с замысловатыми узорами и повышенной толщиной', $$Довольные улыбки, которыми он обычно озарял чужие похороны, стали какими-то натянутыми – О Зарквон, спаси и сохрани, – пробурчал он под нос Бредя в сумерках к своей пещере, Артур вдруг заметил за облаками странные вспышки – Занимательно, не правда ли? – произнесло видение Она вновь станет частью Ключа$$);
insert into тип_продукции values (84, 1984, 'Конверты для прямой почтовой рассылки с глянцевой отделкой, самоклеющимся клапаном и расширенными полями', $$Это было их творение, и сейчас они пели о нем песенку, изливая в ней двойную радость успеха и обладания Левая голова посмотрела влево, а правая – вправо, и обе решили, что следует отправиться куда глаза глядят (Естественно, я не знаю их лично, но я знаю природу всех органических живых существ, и гораздо более досконально, чем хотел бы Тогда я попробую ходить задом наперед Глаза Форда, провожавшего взглядом мяч, широко распахнулись На секунду-другую лицо Артура застыло, как маска, а потом стало с ужасающей медлительностью раскалываться на куски, точно арктические льдины по весне Стратегия заключалась в том, чтобы он перехватил предыдущий у скрещения дорог, и пусть соединенными силами поднимут дух второго Принесли новый мяч, игра возобновилась, солнце продолжало светить, а Форд все скакал и скакал на месте, мотая головой и моргая Зафод не покидал кровати$$);
insert into тип_продукции values (85, 945, 'Промышленная бумага с высокой прочностью на разрыв, влагостойкостью и устойчивостью к истиранию', $$– Их здесь нет уже три года Его челюсти начали делать отжимания Тогда я попробую ходить задом наперед О нет – то были действия, странно непохожие на все его обычные странности и чудачества – Уф, нащупал, – сообщил он Слартибартфаст, Форд и Артур остановились под ароматно пахнущим деревом Артур пришел в безмятежное настроение – Компьютер, – окликнул Охмешконасыпатель И потому вскорости они оказались у внутренней границы сферического, полого изнутри Пылевого Облака, со всех сторон окружавшего Криккит и его солнце – Просто прими на веру все, что я тебе скажу, и сразу все станет совсем, совсем ясно$$);
insert into тип_продукции values (86, 1088, 'Вощеная бумага с биоразлагаемым покрытием, водостойкостью и термостойкостью', $$Но тьма – глухой кокон, оберегающий внутренний мрак, – все еще гудела вокруг корабля Свет он выключил, чтобы его головы не видели друг дружку, поскольку обе выглядели довольно погано – с самого того момента, когда Зафод сдуру заглянул к себе в душу Сдержанно, но властно отстраняя людей со своего пути, фигура пробралась к мужчине, который лежал при последнем издыхании в жуткой луже крови Фальшивка$$);
insert into тип_продукции values (87, 4059, 'Бумага для акварели холодного прессования с текстурированной поверхностью и высоким содержанием хлопка', $$Затем Артур заметил, что идущая впереди компания тоже обратила внимание на визг и пришла в замешательство ниже, в главе о «Движении за Реальное Время») имел несчастье быть построенным в эпоху младенчества физики невероятности, задолго до постижения законов этой смутной и дикорастущей научной отрасли Не считаясь ни с какими законами пространства, роботы беспардонно материализовали свой корабль там, где им было надо, вследствие чего он сцепился с «Золотым сердцем» крест-накрест, как одна расческа с другой Ни информации, ни иллюзий – только они трое, белые стены да несколько мелких устройств, которые, по-видимому, следовало подключить к некой розетке$$);
insert into тип_продукции values (88, 4459, 'Пергаментная бумага с жиростойким покрытием, устойчивостью к высоким температурам и возможностью многократного использования', $$Некоторые из нас гибнут от рук охотников, но, поскольку всех нас зовут Земами, утраты проходят незамеченными, и момнуханье, таким образом, остается минимальным – По-моему, ваша команда только что победила, – произнесло видение – Что, неужели сейчас на это место нападут? – спросил он Никто не знает, что за радость находит отвертка в подобной жизни – А, ну и ладно, – промолвил Артур с облегчением Извините, бога ради, никак не найду клавишу перемотки…

– … это удел биллионов биллионов невинных…

– Ни в коем случае, – прокричал Слартибартфаст, вновь проплывая мимо и яростно возясь с устройством, которое раньше воткнул в стену Зала информационных иллюзий; при ближайшем рассмотрении Артур сообразил, что оно по-прежнему торчало в стене, – не соглашайтесь ничего покупать$$);
insert into тип_продукции values (89, 3300, 'Пекарская бумага с антипригарной поверхностью, термостойкостью и влагостойкостью', $$Тут он обнаружил в стене искомое отверстие и с хрустом воткнул в него вилку прибора Прижав к стене кончики пальцев, он ощутил странную вибрацию Я не шучу – Не слишком похоже на наш случай Артур приподнялся на локтях:

– Где я?

– На крикетной площадке «Лордз», – сообщил Форд$$);
insert into тип_продукции values (90, 1520, 'Бумага для рисования с гладкой поверхностью, высокой плотностью и превосходной белизной', $$Затем пусть отправляются все втроем на поиски первого, поговорят с ним по-людски, споют ему колыбельную, что ли Артур, погруженный в мысли об Эссексе и Ирландии, на миг растерялся Вероятность подобного события равна примерно одному шансу из бесконечности Порой он замирал, часто моргая Звук превратился в монотонный звон в ушах$$);
insert into тип_продукции values (91, 4104, 'Блокноты для заметок с проклеенными страницами, твердой обложкой и эластичной застежкой', $$Три столба с двумя поперечинами Со вздохом облегчения и возгласом триумфа они вскочили на диван, солнце, моргнув, погасло, и, провалившись сквозь головокружительное ничто, они выбрались на свет божий в самом неожиданном месте – посреди поля крикетной площадки «Лордз» (что расположена в лондонском районе Сент-Джонс-Вуд) незадолго до окончания последнего матча международного турнира на Приз Австралии 198… года, причем команде Англии требовалось лишь двадцать восемь перебежек для победы Компьютер безголосо пискнул в знак окончания вычислений Они легли на низкую орбиту В нем звучала даже какая-то интеллигентная хрипотца$$);
insert into тип_продукции values (92, 3034, 'Папка с кольцами с прозрачными карманами, разделителями и застежкой-молнией', $$Тут наблюдатели услышали высоко в безглазых небесах тоненький визг Артур, растроганный и недоумевающий, только замотал головой – Здесь производятся все вычисления, обеспечивающие жизнедеятельность корабля – Правда, – сказал робот Первый комментатор призадумался Протечку – Мы планируем вас застрелить$$);
insert into тип_продукции values (93, 5390, 'Портфель из картона с прочным корпусом, удобными отделениями и мягкой ручкой', $$Матрасс пришел в возбуждение Слова все время забываю Но тут же с безмерным чувством облегчения крепко схватился за нее обеими своими И перевел взгляд на чудо творения за иллюминатором – Где?

Слегка дрожащей рукой Форд очертил чуткоматом дугу в воздухе Публика разразилась аплодисментами$$);
insert into тип_продукции values (94, 5376, 'Кипа бумаги формата A4 с высокой белизной', $$– Н?

– … НП – По крайней мере мне так кажется Он вновь задумался о происшедшем Сам собой откинулся трап И вновь ответа не последовало Тут в рубку вошла Триллиан и произнесла несколько комплиментов свободе И тут же остановился – Завладеем, – заявил робот По-моему, это было животное из семейства аллигаторов – Странное это дело, – тихо проговорил Артур, – чем быстрее и дальше путешествуешь по Галактике, тем менее важным кажется твое местоположение в ней, и тебя охватывает глубокое, точнее, опустелое чувство… этого самого…

– Да, очень странно, – согласился Форд$$);
