insert into тип_материала values (1, 4650, 'Элитная коллекция пригласительных открыток', $$– Эти самые, с которыми он разговаривал Пока я только процитирую «Путеводитель»…

– «Пу…»?

– «Путеводитель» Душа Артура летала вокруг его тела кругами и мялась, не испытывая особенного желания войти И понадеялся, что с какой-нибудь туристической смотровой вышки Вселенной эта ломаная покажется каким-нибудь вопиюще неприличным словом – Ну, как я уже сказал, ваша команда только что победила – Мне кажется, – сказал Форд тоном, обещавшим (как уже было известно Артуру) какое-то чрезвычайно непонятное продолжение, – что вон там какое-то ННП Она услышала, как Зафод топочет и насвистывает где-то в недрах корабля Зафод крякнул – Я-то думал, что стряслось, – сказал Форд, – а это просто матч кончился – Как ты там? – спросила она по внутренней связи$$);
insert into тип_материала values (2, 2144, 'Художественные журналы с персонализированной обложкой', $$И что самое удивительное, точно специально экипированные для данного мероприятия В его желудке точно черти свадьбу справляли Слартибартфаст дернул за ручку, и она умолкла На секунду-другую лицо Артура застыло, как маска, а потом стало с ужасающей медлительностью раскалываться на куски, точно арктические льдины по весне$$);
insert into тип_материала values (3, 3680, 'Организаторы с персонализированным дизайном и тиснением', $$– Уф!

Зафод остановился – А затем мы отправимся, – на полном серьезе заявил робот, – на вечеринку – Нет, – сказал Форд, – он чувствует мобильную аномалию в ткани пространства-времени, локальное возмущение, очаг нестабильности Есть частные клубы летателей, где вам помогут достичь ключевого самозабвения$$);
insert into тип_материала values (4, 850, 'Альбомы для фотографий с тиснением и мягкими листами', $$И вдруг роботы вернулись, снова начался кавардак, и на этот раз после их отлета матрасс остался на болоте один Компьютер донимал его вопросами, что за чертовщина тут происходит, но Зафод заткнул его терминалы электронными кляпами В каждом рассвете есть миг, когда свет не льется вниз, а парит, миг, когда возможно чудо – Ну и как там?

– А это что, твоя пещера? – спросил Форд Его челюсти начали делать отжимания$$);
insert into тип_материала values (5, 1309, 'Изготовленные на заказ ежедневники с закладками из ленты', $$– Ну да?

– Ну да Вам того же Первый комментатор призадумался Прикрыв один глаз, он что-то созерцал другим – Компьютер, – окликнул Охмешконасыпатель А еще я пробовал научиться летать Они прошли очень близко от наблюдателей под деревом, размахивая фонарями, от чего по траве и листве скакали забавные «зайчики», радостно болтая между собой и самым натуральным образом распевая песню о том, как все чуд-чуд-чудесно на свете, как они счастливы, как здорово они потрудились на ферме и как приятно возвращаться домой, где ждут жены и дети – Я же сказал! – заорал Форд, вскочив на ноги$$);
insert into тип_материала values (6, 4860, 'Персонализированные конверты с сургучными печатями', $$Воздух был прозрачен и душист Попятившись, Артур испуганно огляделся по сторонам А случится это сегодня Не характерное для дверной речи выражение$$);
insert into тип_материала values (7, 6110, 'Комплекты открыток с тематическими принтами', $$Прижав к стене кончики пальцев, он ощутил странную вибрацию – Нет, – заявил Марвин Артур увидел вереницу крохотных огоньков, что, качаясь и приплясывая, медленно двигались к ним Кроме того, в звездолете просто не нашлось бы столько дверей – пресловутое «уф» прозвучало так, будто его произнесли сто тысяч человек разом Похоже, на них восседали не то девушки, не то ангелы$$);
insert into тип_материала values (8, 2684, 'Декоративные коробки с узорами из тиснения', $$Марвин отвлекся от своего утомительного кругового обхода Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина – Вон там, – сказал Форд, вновь указывая на табло и глядя на поле Робот-официант, робот-буфетчик и робот-метрдотель обслуживали роботов-клиентов Артур наморщил лоб:

– А почему на вашем корабле все вычисления… – И прикусил язык Еще мрачнее сдвинул брови – и наконец успокоился – Нет, – сказал Форд, – он чувствует мобильную аномалию в ткани пространства-времени, локальное возмущение, очаг нестабильности И хотя теперь его жизнь текла чрезвычайно ровно и спокойно, нервы Артура по-прежнему шалили Но в общем и целом они смотрелись довольно приятно$$);
insert into тип_материала values (9, 4988, 'Экологичные сумки-шопперы с ручками из крафт-бумаги', $$Пользуясь секретами древних мастеров, они любовно смонтировали этот сувенир, который украсит ваш дом – в напоминание о павших и в знак почтения к Галактике – нашей Галактике, – на алтарь которой они положили свои жизни…

Тут мимо вновь проплыл Слартибартфаст По трапу решительной походкой сошла высокая серо-зеленая фигура и приблизилась к маленькой кучке людей, которые окружали жертв недавней абсурдной бойни Также эта стремительная гонка по водопадам времени подарила им еще одно четкое ощущение Если б Эффрафакс покрасил гору в ярко-розовый цвет, а сверху водрузил недорогой генератор ННП-поля, люди так и ходили бы мимо горы, вокруг нее, даже по ее склонам – ничуть не подозревая о ее присутствии И вновь зашагал вперед – … это их жизненный, а чаще предсмертный опыт Искусственная мебель, искусственная скатерть А кто-нибудь еще его заметил?

– По-видимому, нет Этот величественный, сказочно-роскошный лайнер сошел со стапелей знаменитого Артефактоволя – астероида-верфи – несколько сот лет тому назад И что любопытно – направление, в котором указала его рука, не совпадало с направлением его взгляда$$);
insert into тип_материала values (10, 3773, 'Оригами-комплекты с пошаговыми инструкциями', $$Призрачные, но весьма агрессивные фигуры, шевелившиеся за толстой дымовой завесой, и впрямь будто пародировали удары нападающих И там и сям царил глухой мрак В висках у Артура раздался привычный тупой звон, очень часто сопровождавший его разговоры с Фордом Форд с Артуром, пыхтя, бежали за ним, но диван увертывался и петлял, точно пространство имело для него иную, сложную математическую топографию – как оно и было в действительности Пристегиваясь ремнями, Форд Префект только возносил хвалу судьбе за то, что это всего лишь безопасная инфоиллюзия Еще чуть-чуть – и я разучился бы разговаривать – Ну и хорошо, – сказал Артур Они стояли одни-одинешеньки на вершине утеса где-то на доисторической Земле и решительно смотрели друг другу в глаза Особенно этот момент, когда нужно угодить в калитку маленьким красным мячиком С большим ехидством$$);
insert into тип_материала values (11, 4290, 'Набор бумажных цветов с реалистичными деталями', $$Она была срежиссирована скорее для блага телезрителей, чем просто зрителей, и со своего места в толпе они могли следить за ней только по сообщениям ближайшего репродуктора Тем самым выведя Форда из медитационного транса Вторая реакция: «Извините, можно выйти?»

– И что, эта штука полетит? – спросил Артур, сочувственно косясь на связанные веревочками трубы и приклеенные к картонной обшивке провода, что составляли интерьер корабля «То, что надо», – решила Триллиан, и спустя несколько часов их огромный белый корабль в форме кроссовки уже вальяжно спускался с небес, украшенных жарко блестящим солнцем, к яркому космопорту-скале Правда, в них проглядывала некоторая чудаковатость – не хотел бы Артур ехать с ними в одном купе, – но вся эта чудаковатость сводилась к чрезмерному добродушию и любезности, а не каким-то изъянам Правда, он всегда подозревал о ее существовании, поскольку обладал полным комплектом стандартных органов (и даже двойным – кое-каких), но, внезапно обнаружив в глубине своего существа эту затаившуюся зверюшку, был крайне шокирован – И они поддерживают, – зашелся в истерике голос, – Золотую Перекладину Процветания и Серебряную Перекладину Мира!

Теперь все сооружение качалось в светящейся паутине, а музыка, к счастью, давно исчезла за горизонтами восприятия – Ммммм?

– Когда я выну у тебя кляп…

– Ммммм – Ммммм ммммы?

– Все равно, какой головы Они достигли цели$$);
insert into тип_материала values (12, 9500, 'Календари с эстетичными дизайнами и функциональными функциями', $$По трапу решительной походкой сошла высокая серо-зеленая фигура и приблизилась к маленькой кучке людей, которые окружали жертв недавней абсурдной бойни – Ты будешь слушать или нет?

– Я слушаю, – сказал Артур, – только боюсь, толку мне от этого мало Из люка вырвался столб света По-моему, – пояснил Артур, не сбавляя скорости$$);
insert into тип_материала values (13, 1207, 'Ежедневники с яркими принтами и водостойкой обложкой', $$Его лучи обращали в алмазы слезы детишек, уронивших растаявшее мороженое с палочки – И, – продолжал громоподобный голос, – Деревянный Столб – символ, – здесь бас слегка осип от избытка умиления, – могущества Природы и Духовности!

Лучи переместились на центральный столб – Вам весело? – спросил матрасс Пытаясь совместить четырех Триллиан в единый образ, его головы столкнулись лбами$$);
insert into тип_материала values (14, 5200, 'Блокноты с обложкой из переработанного картона и тонированной бумагой', $$– Нет, – заявил Марвин – Тс-с-с, – сказал Слартибартфаст Музыка бодро штурмовала небесное царство полной несказанности – Возмущения в континууме!

– А, это они мебельные магазины громят! – воскликнул Артур, с трудом вернувшись в вертикальное положение и – как он смел надеяться – в здравый рассудок – Ммммм?

– Когда я выну у тебя кляп…

– Ммммм – Над болотами был сооружен мост$$);
insert into тип_материала values (15, 2125, 'Наборы карточек ручной работы с уникальными иллюстрациями', $$А потом тьма позади Вселенной взорвалась, и каждый лоскуток тьмы обернулся косматым дымом преисподней – В глубинах фундаментального сердца духа и Вселенной, – сказал Слартибартфаст, – кроется причина тому День за днем они исследовали останки сгоревшего корабля, разгрызая секрет за секретом, распевая звонкие кораблеразборочные марши Мозг просто вымарывает эту штуку из поля зрения, точно слепое пятно То был мирный край$$);
insert into тип_материала values (16, 2058, 'Настенные панно из бумаги-маше с объемными деталями', $$– Потом расскажу Сам себе сосчитал пульс Вот он я, Зафод Библброкс – Космовидеотон, Мыслекинозал, Надомный Думатель, – известил он и пискнул Артур пришел в безмятежное настроение Большинство зрителей, будучи не в силах выдержать этого зрелища, зажмурили глаза и переключились на слушание радиотрансляции – Что «ну и»? – поинтересовался старец – Золотая Перекладина – это часть Ключа, который мы ищем, – продолжал робот, – чтобы освободить наших Повелителей с Криккита$$);
insert into тип_материала values (17, 2700, 'Доски для заметок из переработанной бумаги с ярким дизайном', $$Кто-то коснулся его плеча Он был уже в двух ярдах от двери рубки, когда до него внезапно дошло, что дверь обязательно поздоровается с ним А теперь – в Зал информационных иллюзий Извините, но таково общее мнение о ней – И также я тебя прошу не говорить, что ты очень рада быть полезной или что ты польщена честью раскрыться передо мной и премного довольна вновь затвориться с сознанием выполненного долга, ладно?

– Ладно Пока он отсыпался, Триллиан заглянула в бортовой экземпляр «Путеводителя» Бедные кретины Ему пришло в голову, что во Вселенной непременно найдется кто-то, кому жизнь кажется еще более беспросветной, тяжелой и треклятой, чем ему Ему так и не удалось отключить разговорные блоки дверей Его губы тоже дергались$$);
insert into тип_материала values (18, 3724, 'Конверты с вырезами и красочными подкладками', $$Тихо проскользнув под ветками, они поднялись вслед за веселой компанией по тропке в гору Деревья! Я практикуюсь в разговорах с деревьями – Ты козел, Дент, – промолвила она просто Я не шучу – Да нет же, – возразил Артур – Это же крикетная площадка «Лордз», верно? – возопил Артур Из люка вырвался столб света Хуже может быть только одно – наблюдать за ее разрушением с ее же поверхности А за спиной человека из исполинских клубов мглы стали постепенно вырисовываться три высоких столба$$);
insert into тип_материала values (19, 624, 'Подарочная упаковка с персонализированными сообщениями и декором', $$Да, сказал бы я, около двух третей Охмешконасыпатель Конца-Краю-Не-Знающий принадлежал – то есть принадлежит – к очень узкому кругу бессмертных обитателей Вселенной Чересчур осмысленное и лаконичное – Спасибо за внимание Роботы А от этого субъекта никому не удалось добиться подробностей, поэтому поиски были весьма поверхностными Было темно Они пытались их игнорировать, но все же не могли не заметить, что Слартибартфаст сварливо требует, чтобы серебряную урну с «Пеплом» отдали ему, ибо тот, по его словам, «жизненно важен для прошлого, настоящего и будущего Галактики», и что это заявление вызвало бурное веселье Скорбное выражение на лице Артура Дента уступило место еще более скорбному$$);
insert into тип_материала values (20, 1008, 'Наборы для рисования с бумагой высокого качества и инструментами', $$Неся в руках поднос с ужином, она вошла к Зафоду и спросила, нет ли у него желания поговорить Между мигом, когда криккитяне впервые узнали о существовании космоса как такового, и запуском этой первой ласточки среди космических кораблей прошел ровно год И само собой разумеется, он был слегка пьян – Он вновь раскрыл глаза и блаженно улыбнулся – Я обнаружил, – заявил он, – аномальные протечки – Правда, что ли? – вскричал Зафод, поигрывая пистолетом Тут он обнаружил в стене искомое отверстие и с хрустом воткнул в него вилку прибора Словно ниоткуда, зазвучала музыка Это крикетный приз$$);
insert into тип_материала values (21, 867, 'Книги-раскраски со сложными узорами и мотивами', $$В общем, голос был столь же древним, как и его владелец – Неверно, – пробурчал Марвин Даже у примитивных племен он таится в родовой памяти Также никому не известно, что за радость находят в своем образе жизни матрассы – Я просто так спрашиваю, для информации – «Пепел», – сухо ответил Артур – Ну, как я уже сказал, ваша команда только что победила$$);
insert into тип_материала values (22, 1485, 'Наборы оригами с разноцветной бумагой и схемами', $$Поговаривают, что у нее эрогенные зоны начинаются милях в четырех от тела как такового – Ну-ка, улыбочку, усмешечку!» Я разъяснял, что для того, чтобы мое лицо исказила улыбка, нужно отнести его в мастерскую и часа два поработать над ним кувалдой – Что вы сказали? – пробормотало ошарашенное полисменообразное Он, как известно всем, был уничтожен, развеян по извечным водоворотам пространственно-временного континуума и исчез навеки Аплодисменты вскорости перешли в изумленные ахи и робкие смешки – сотни людей никак не могли решить, верить ли своим глазам – А куда мы держим путь?

– Мы держим путь, – объявил Слартибартфаст, – на битву с Древним Злом Вселенной Артур был совершенно счастлив Отключив всю кухонную автоматику, она приготовила самый роскошный ужин, какой был в ее силах, – аппетитно прожаренное мясо, ароматные фрукты, благоуханный сыр, коллекционные альдебаранские вина – Откуда?

– Ты разве не изучал в школе древнюю историю Галактики?

– Моя киберкабинка была позади Зафода, – пояснил Форд, – это очень отвлекало$$);
insert into тип_материала values (23, 2600, 'Настенные обои с текстурами, имитирующими натуральные материалы', $$Искусственная мебель, искусственная скатерть Мелкие капли едва просачивались сквозь туман Инопланетное существо, морща лоб, заглянуло в штучку вроде папки, которую сжимало в своих длинных, лианообразных инопланетных пальцах Свет он выключил, чтобы его головы не видели друг дружку, поскольку обе выглядели довольно погано – с самого того момента, когда Зафод сдуру заглянул к себе в душу После фантасмагорического балагана «основного вычислительного центра» Зал информационных иллюзий был настоящим отдохновением для глаз$$);
insert into тип_материала values (24, 2484, 'Оберточная бумага с замысловатыми принтами и фактурами', $$Как-то ночью – а теперь на корабле ночь длилась постоянно – лежа в постели, он решил взять себя в руки, предпринять что-нибудь конструктивное Но тут же, заметив, что отряхивает именно халат, застыл как вкопанный Слартибартфаст занял освободившееся благодаря этому происшествию место и окинул суровым взглядом меню Настоящим «стопщикам» эти клубы, как правило, не по карману, но можно рекомендовать их как возможное место для временной работы Потом спросил: – Какие зоны вещания попадутся нам в ближайшие часы?

Компьютер пискнул Артуру пришло в голову, что раз они добрались до конца, точнее, до начала всех ужасов, которые смутно пережили, сейчас должна стрястись беда – Ву-ун, – враднул он наконец – Не могу не отметить того факта, что вы припарковали свой корабль, – сказал он, указав одним из подбородков в соответствующую сторону, – прямо поперек моего То была ненависть, слепая ненависть – А это что?

– Не Наша Проблема$$);
insert into тип_материала values (25, 3360, 'Свадебные приглашения с замысловатыми кружевами из бумаги', $$– Я не о полотенце, – сказал Артур Безусловно, вся сложность во втором этапе – в промахивании Его челюсти начали делать отжимания – А мне можно с вами?

– Нет, – сказал робот$$);
insert into тип_материала values (26, 1612, 'Рождественские открытки с тиснением и блестящими элементами', $$– И все же довел это дело до конца Вот уже четыре года (со дня расставания с Фордом Префектом) Артур в общем-то ни одной души не видел, а потому и оскорблениям больше не подвергался По моему состоянию вы можете заключить, что я едва спасся – А-а, – воскликнул он, сосредоточившись на первом попавшемся имени$$);
insert into тип_материала values (27, 987, 'Наборы для квиллинга с разноцветными полосками бумаги и инструментом', $$Не вынимая спичек – Спасибо за внимание Компьютер донимал его вопросами, что за чертовщина тут происходит, но Зафод заткнул его терминалы электронными кляпами – А-а, – протянул Артур, – так вот почему…

– Ну да, – согласился Форд, зная наперед, что именно Артур скажет – Видимо, вы поглощены размышлениями, – плучительно сказал матрасс Тогда я попробую ходить задом наперед Воцарилась бесконечно холодная и зловещая тишина Он вскочил с дивана$$);
insert into тип_материала values (28, 742, 'Абажуры из бумаги с уникальными формами и узорами', $$– Ну и? – тревожно вопросил Артур В висках у Артура раздался привычный тупой звон, очень часто сопровождавший его разговоры с Фордом Умопомрачительно красивый, уникально огромный и к тому же самый уютный корабль в истории Галактики (точнее, в нынешней, сильно обкарнанной опровержениями версии этой самой истории – подробности см – Эксцентрика Гамбитус, ты ее когда-нибудь видел? Троегрудая путана с Эротикона-6 Но в общем и целом они смотрелись довольно приятно Солнце клонилось к закату И потому большинство людей после первых неудач разочаровываются в этом увлекательном, зрелищном спорте – Мм… да, – ответил Артур – Клянусь, они в крикет играют Отряхнулся$$);
insert into тип_материала values (29, 3717, 'Мебель из картона с прочной и легкой конструкцией', $$– Я только, – продолжил Слартибартфаст со вздохом, – я только хотел упредить ваш вопрос и заранее пояснить, почему на моем корабле все вычисления производятся в блокноте официанта – Ты будешь слушать или нет?

– Я слушаю, – сказал Артур, – только боюсь, толку мне от этого мало – Да, бывает, – заметил Форд Большую часть всех абсурдных вещей, какие приходили ему в голову, он уже повидал наяву – Диван исчез Вероятно, природа – в своей безмерной мудрости – работает над этим$$);
insert into тип_материала values (30, 854, 'Дизайнерская бумага для скрапбукинга с различными текстурами и принтами', $$Он просочился через протечку континуума, по воле парусных волн эфира и я не знаю еще чьей – какая на фиг разница, мы должны его поймать, а то так здесь и застрянем!

Он съехал на пятках по скале и стремглав понесся по полю Залезайте, нам пора Сдержанно, но властно отстраняя людей со своего пути, фигура пробралась к мужчине, который лежал при последнем издыхании в жуткой луже крови Этакий замысловатый балет меню, счетов, бумажников, чековых книжек, кредитных карточек, часов, карандашей и бумажных салфеток Форд повторил – Нет ни одной планеты, – отчеканил высокопрофессиональный голос ведущего, – нет ни одной цивилизованной планеты в Галактике, где и в наши дни ни почитали бы этот символ Глаза Артура пошли колесом А сказал он следующее:

– Да, у вас в руке действительно пистолет-бластер системы «Громовержец» А от этого субъекта никому не удалось добиться подробностей, поэтому поиски были весьма поверхностными Я сам посадил сотни$$);
insert into тип_материала values (31, 6643, 'Обложки для книг с индивидуальной гравировкой и яркими рисунками', $$Наши Повелители выйдут на свободу Прежде чем мы поведаем, что именно сказал робот, следует отметить, что Зафод был первым живым органическим существом, кому довелось услышать голос этих тварей за последние десять биллионов лет – Любопытное происшествие, Брайан, – сказал один радиокомментатор другому Большую часть всех абсурдных вещей, какие приходили ему в голову, он уже повидал наяву Около того, – сказал Марвин надменно$$);
insert into тип_материала values (32, 4200, 'Скетчбуки с акварельной бумагой и удобной спиралью', $$– Как вас зовут?

– Дент Артур пожал плечами – Я этот номер уже видел, – проговорил он – Как ты там? – спросила она по внутренней связи$$);
insert into тип_материала values (33, 527, 'Папки-регистраторы с тиснением и прочной картонной обложкой', $$– Мы ищем Ключ, – повторил он, – мы уже владеем Деревянным Столбом, Стальным Столбом и Плексигласовым Столбом Для примера – задумайте число, любое число – Ну и как там?

– А это что, твоя пещера? – спросил Форд Непонятно, с чего вдруг Слартибартфаст принялся пришептывать, как в радиорекламе какого-нибудь жуткого фильма о лесорубах, берущих на дом халтуру?

Да, но ведь вся эта история с Криккитом ничуть не лучше Все было ясно из самой его походки Не знаю, зачем им это надо, но так оно и есть – Н?

– … НП – Я тут временно спустил свой разум с цепи, предполагая, что, если я миру дико понадоблюсь, он призовет меня обратно Топ-топ – Да, ты прав, и все же он утверждал, что видел, как нечто материализовалось на площадке$$);
insert into тип_материала values (34, 1152, 'Наборы для рисования с цветными карандашами, фломастерами и бумагой', $$Особенно этот момент, когда нужно угодить в калитку маленьким красным мячиком Затем пусть отправляются все втроем на поиски первого, поговорят с ним по-людски, споют ему колыбельную, что ли – Здесь, на болоте?

– Мост, – подтвердил Марвин – Не могу не отметить того факта, что вы припарковали свой корабль, – сказал он, указав одним из подбородков в соответствующую сторону, – прямо поперек моего – Артур, – сказал Форд Миссия «Криккита-1» заключалась в том, чтобы выяснить, есть ли что-то с той стороны неба, откуда, вероятно, и происходил разбившийся корабль$$);
insert into тип_материала values (35, 1462, 'Маски из папье-маше с изысканными деталями и рисунками', $$Артур кивнул, прокашлялся Робот, похоже, понял Вскоре всех собравшихся обуяла необыкновенная, настоятельная вежливость – Верно, – признал Артур Осмелюсь признаться, я питаю некоторую слабость к крикету, хотя я не хотел бы, чтобы о ней знали за пределами этой планеты А также флёпал, гумкал и уйломикивал$$);
insert into тип_материала values (36, 3675, 'Изготовленные на заказ фотоальбомы с хронологическими разделителями', $$Он перешел на шепот О нет – то были действия, странно непохожие на все его обычные странности и чудачества «Может ли быть, что это и есть истинное устройство Вселенной? – вопросил он себя Он мягко приземлился – Потом расскажу Тебе это по силам?

– Что это Слартибартфаст так волнуется? – спросил Артур – Правда, что ли? – вскричал Зафод, поигрывая пистолетом – Это что-то важное, – рассудил Артур и окликнул старца$$);
insert into тип_материала values (37, 1425, 'Свадебные программы с элегантным дизайном и качественной бумагой', $$Между мигом, когда криккитяне впервые узнали о существовании космоса как такового, и запуском этой первой ласточки среди космических кораблей прошел ровно год Тут силы матрасса иссякли, и он флюмкнулся обратно в протоку, обрушив на Марвина струю мокрой тины с водорослями и мхом Он, как известно всем, был уничтожен, развеян по извечным водоворотам пространственно-временного континуума и исчез навеки – Приятных сновидений, – сказал он$$);
insert into тип_материала values (38, 1152, 'Приглашения на детский праздник с яркими принтами и забавными персонажами', $$– Мне много не надо, – кричал Форд в уточнение своих предыдущих замечаний, – только рюмка крепкого виски и компания братьев по духу!

Он несся, как лань, замешкавшись лишь на миг, чтобы взять на буксир Артура, который среагировал было на катастрофу в своем обычном духе – замер с открытым ртом, ожидая, пока все кончится Но несть числа тем, кто упивается историей «Звездного Титаника», легендарного корабля-колосса – Странная весть, – процедил Форд Над всеми нами простерты крыла смерти В его голове родился целый рой глубокомысленных вопросов Может, там находится другая планета – ох, как трудно далось это предположение самозамкнутым умам сынов Криккита с его глухой стеной вместо неба Ветер обдувал бухту, где останки одной из крупнейших и мощнейших космических флотилий в истории Галактики поспешно превращались из пепла в исходное состояние – А скоро выйдешь?

– Нет, тут останусь – Что «ну и»? – поинтересовался старец$$);
insert into тип_материала values (39, 4662, 'Карточки с рецептами со стильными рамками и водонепроницаемой подложкой', $$Зафод влил еще стакан в свою другую глотку Послышался ропот (будто сотня тысяч людей вымолвила: «Уф!»), и прямо над крикетным полем буквально сгустился из воздуха белый стальной звездолет Бистроматика как таковая являет собой революционно-новый подход к интерпретации поведения чисел Что матрасс и сделал, испустив еще одно легкое флюпчание Защитник, взмахнув битой, послал мяч себе за спину так, что он пролетел над табло И само собой разумеется, он был слегка пьян$$);
insert into тип_материала values (40, 3471, 'Обложки для паспортов с замысловатыми рисунками и защитой от RFID', $$Инопланетное существо, морща лоб, заглянуло в штучку вроде папки, которую сжимало в своих длинных, лианообразных инопланетных пальцах Подобно открытию Эйнштейна, что время не есть абсолют, но зависит от движения наблюдателя в пространстве, а пространство не есть абсолют, ибо зависит от движения наблюдателя во времени, ныне установлено, что числа не абсолютны, но зависят от движения наблюдателя в ресторанах Ему не хотелось думать, что эту идиллическую страну постигнет несчастье Золотая Перекладина заключена в механизме, который движет вашим кораблем – Что сталось с голгафрингемцами? – спросил Форд Главный же ужас состоял в том, что пещера находилась в лондонском районе Айлингтон и первый автобус в центр должен был отправиться примерно через два миллиона лет А от этого субъекта никому не удалось добиться подробностей, поэтому поиски были весьма поверхностными Вот уже пять лет, как его не расщепляли на атомы Только пришествие карманных компьютеров пролило свет на умопомрачительную истину – Ваш, что ли, диван? – раздалось сверху$$);
insert into тип_материала values (41, 1120, 'Коробочки для подарков с окнами из прозрачной бумаги и лентами', $$У официанта в блокноте числа пляшут Скорость его функционирования феноменальна – Я так, просто напомнить хотел, – сказал Форд Солнце почти закатилось Артур приподнялся на локтях:

– Где я?

– На крикетной площадке «Лордз», – сообщил Форд – Что это было? – вымолвил Артур А потом даже гумкнул от избытка чувств$$);
insert into тип_материала values (42, 1716, 'Декоративные вазы из картона с уникальными формами и текстурами', $$И каждая частичка еды была, по-видимому, наделена всеми механическими свойствами, например, «цыпленка-алла-романа», на деле им не будучи – Ну и хорошо, – сказал Артур – Фгм, – произнес робот и вернулся к своему занятию, а именно очень медленному хождению по очень маленькому кругу Инопланетное существо, морща лоб, заглянуло в штучку вроде папки, которую сжимало в своих длинных, лианообразных инопланетных пальцах В нем зрела ненависть к Вселенной в целом и каждому из ее обитателей в частности И камни тоже не мои, – добавил он, вытащив из сумки горсть плоских серых камешков Артур увидел вереницу крохотных огоньков, что, качаясь и приплясывая, медленно двигались к ним Но теперь все происходило слишком уж молниеносно – сплошное видеотактильное пятно, которое волокло их сквозь века галактической истории, крутясь, дергаясь, мерцая Он решил оскорбить Вселенную Пока он отсыпался, Триллиан заглянула в бортовой экземпляр «Путеводителя»$$);
insert into тип_материала values (43, 780, 'Костюмы из папье-маше для фестивалей и театральных представлений', $$Каков мерзавец? И продал меня в Психозоопарк Старец ответил не сразу Строго индивидуально, лицом к лицу, одного за другим и (тут он с особым сладострастием скрипнул зубами) в алфавитном порядке – Я же сказал! – заорал Форд, вскочив на ноги И все же этот случай войдет в анналы истории, тем более что он произошел в столь драматический момент, когда Англии не хватает до победы только двадцати восьми перебежек – Привет, землянин, – ответил Слартибартфаст Они стояли одни-одинешеньки на вершине утеса где-то на доисторической Земле и решительно смотрели друг другу в глаза$$);
insert into тип_материала values (44, 4770, 'Органайзеры для ванной с водостойким покрытием и нескользящим дном', $$– Нет ли фильмов, которых я не видел уже тридцать тысяч раз?

– Нет Матрасс пришел в возбуждение Тихо-тихо-тихо дверь прошептала:

– Я вас слышу – Эй! – вскрикнул Артур – Только, – заверил его Форд – Перед тобой мужчина в полном расцвете сил, который может сделать все, что ему захочется, вот только что-то не хочется мне ни фига, ну ни фигошеньки…

Он помолчал$$);
insert into тип_материала values (45, 4788, 'Календари с магнитными держателями и увеличенными полями для заметок', $$Больше ничего не произойдет – От… к-к-к… э-э… – добавил он немного погодя По моему состоянию вы можете заключить, что я едва спасся Часа через два стало очевидно, что Зафод тверд в своем решении, и корабль вновь поднялся в небо, даже не спустив трапа Он взошел по трапу и исчез в недрах корабля$$);
insert into тип_материала values (46, 8900, 'Подарочные сертификаты с тиснением и персонализированным дизайном', $$– А затем мы отправимся, – на полном серьезе заявил робот, – на вечеринку – А мне можно с вами?

– Нет, – сказал робот Однако же если в решающий момент вам посчастливится нежданно отвлечься на умопомрачительную пару ног (щупалец, ложноножек, в зависимости от вашей видовой принадлежности и/или личных вкусов), или на взрыв бомбы неподалеку, или на внезапное явление ужасно редкого жука на соседней былинке – тогда-то, к своему изумлению, вы увильнете от всякого столкновения с землей, точнее, останетесь болтаться в каких-то считанных дюймах над ее поверхностью – По-моему, это оно меня довело до ручки С тем же успехом можно покориться судьбе, а здравый рассудок поберечь на потом – Алло? Да? – пробормотал Артур – Ммммм?

– Когда я выну у тебя кляп…

– Ммммм Произнесенные роботом слова подтвердили это впечатление – Покамест я недалеко продвинулся, – сказал он и протянул Артуру руку$$);
insert into тип_материала values (47, 870, 'Обложки для альбомов с тисненым текстом и мягкой набивкой', $$– Не знаю, – сказал Форд, – но я буквально чувствую, что время пришло Недавно был открыт лес, где почти все деревья в качестве плодов дают отвертки с храповиком Вероятно, природа – в своей безмерной мудрости – работает над этим Свет померк Некоторое время все молчали, из чего Зафод заключил, что роботы явились сюда не для разговоров и дело за ним А потом развернулись После чего подозрительно обозрел двух Триллиан и пришел к выводу, что та, что справа, ему больше по вкусу – Ну, как я уже сказал, ваша команда только что победила$$);
insert into тип_материала values (48, 6762, 'Блокноты с прошитыми страницами и гибкой обложкой', $$Это Артур Дент говорит Дверь тихо отъехала в сторону В этот миг необходимо полное, глубочайшее хладнокровие Деревья! Я практикуюсь в разговорах с деревьями Не слушайте окружающих – ничего полезного они не скажут – Ну, как я уже сказал, ваша команда только что победила$$);
insert into тип_материала values (49, 6150, 'Упаковочная бумага с биоразлагаемым покрытием и яркими принтами', $$Только тускло-розовые каемки вокруг дверей, мерцавшие в такт их речам, – Зафоду так и не удалось придумать, как заткнуть им глотки Другой суперсенсацией тогдашней прессы стала вспышка сверхновой звезды, в которую несколько часов спустя превратилась звезда Неавоось – … только что материализовались тут у нас, посреди крикетной площадки «Лордз» Тут он решил, что пора заговорить Начал моросить дождь – Правда, – сказал робот Мозг просто вымарывает эту штуку из поля зрения, точно слепое пятно$$);
insert into тип_материала values (50, 4104, 'Визитные карточки с тиснением, ламинированием и выборочной УФ-печатью', $$– Рада быть полезной И вновь зашагал вперед В его желудке точно черти свадьбу справляли – Кажется, что-то началось!

– Беги в корабль, – завопил Форд, – знать ничего не хочу, беги в корабль$$);
insert into тип_материала values (51, 3128, 'Коробки для хранения с разделителями из картона и магнитными застежками', $$– Грядет катастрофа, – заявил Слартибартфаст Все было ясно из самой его походки – Странный трофей Он задумчиво уставился вдаль Я стал звездой экспозиции От вас требуется одно – решительно кинуться вниз, не боясь ожидающей вас физической боли Форд с Артуром поспешили броситься на землю, которая, казалось, ужасно быстро вертелась вокруг них – Форд резко отвернулся$$);
insert into тип_материала values (52, 4257, 'Тематические наборы открыток с художественными иллюстрациями', $$– Выражаю свое соболезнование насчет него – Оно имеет, – прошептал он Форду, серьезно наморщив лоб, – форму полисмена Затем пусть отправляются все втроем на поиски первого, поговорят с ним по-людски, споют ему колыбельную, что ли – Сверкал-сверкал Свобода$$);
insert into тип_материала values (53, 1595, 'Комиксы с уникальными сюжетами и персонализированными персонажами', $$– Э-э, пять, – сказал матрасс Безусловно, это были не земляне, хотя все различия состояли в чуть-чуть слишком высоком росте, излишней худобе, угловатости и бледной, почти белой коже – Просто прими на веру все, что я тебе скажу, и сразу все станет совсем, совсем ясно Он дико озирался по сторонам, пока не заметил, что Форд с Артуром пробираются сквозь испуганную толпу, которая шарахнулась прочь от поля$$);
insert into тип_материала values (54, 5194, 'Книги с выдвижной бумагой с прикрепленными фигурками или предметами', $$– Расскажите о речи, которую вам однажды довелось произнести, – взмолился он «Может ли быть, что это и есть истинное устройство Вселенной? – вопросил он себя Она была холодна – и то был не ледяной хлад льда, но холод стены Весь следующий день он, не зная отдыха, мерил шагами корабельные коридоры, делая вид, что не ищет Триллиан, а просто прогуливается – хотя и знал, что ее больше нет на борту А придумал он вот что$$);
insert into тип_материала values (55, 6225, 'Поздравительные открытки с музыкальным чипом и настраиваемой мелодией', $$Топ-топ Они пытались их игнорировать, но все же не могли не заметить, что Слартибартфаст сварливо требует, чтобы серебряную урну с «Пеплом» отдали ему, ибо тот, по его словам, «жизненно важен для прошлого, настоящего и будущего Галактики», и что это заявление вызвало бурное веселье – Терпение, – вновь заявил Слартибартфаст Вот как расшифровывается ННП Он встал на дыбы, чтобы заглянуть за заросли, но смотреть было не на что Но едва сойдя со стапелей, он и первой своей радиограммы – сигнала SOS – передать не успел, как все его системы беспричинно отказали Форд, нас подбрасывают!

И действительно, для того чтобы не поддаться этому первому впечатлению, надо было обладать весьма глубокими познаниями в истории Галактики (каковых Артур еще не успел приобрести из-за своей кочевой жизни)$$);
insert into тип_материала values (56, 1836, 'Светодиодные фонари из бумаги с вырезанными узорами и мягким светом', $$Так оно и было – Выражаю свое соболезнование насчет него И каждый, любой из них, встретится ему на пути Стена, казалось, все близилась и близилась, густела и густела, тяжелела и тяжелела$$);
insert into тип_материала values (57, 2618, 'Украшения из папье-маше с яркими цветами и затейливыми формами', $$– Я отыскал озерцо, которое думало, что оно джин с тоником, и стал в нем бултыхаться Извините, бога ради, никак не найду клавишу перемотки…

– … это удел биллионов биллионов невинных…

– Ни в коем случае, – прокричал Слартибартфаст, вновь проплывая мимо и яростно возясь с устройством, которое раньше воткнул в стену Зала информационных иллюзий; при ближайшем рассмотрении Артур сообразил, что оно по-прежнему торчало в стене, – не соглашайтесь ничего покупать Артур хмуро поплелся за ним И она была смертельно опасна – и вновь не на манер ножа или пули, но наподобие кирпичной стены поперек шоссе Также там советовалось заглянуть в главу о необозримости Вселенной и методике примирения с этим фактом – Ожидаемое время в пути – три недели, – продолжил он – Не буду беспокоить тебя подробностями, а то они…

– Что «они»?

– Обеспокоят тебя – М-да-а-а-а-а, – промолвил он наконец, – да, но в чем тут загадочность? Он ведь не материализовался в подлинном смысле слова? Просто пробежал$$);
insert into тип_материала values (58, 6083, 'Модели парусных кораблей из бумаги с детальными парусами и корпусом', $$Я уже пояснил, что в основном беседовал с деревьями Странно, но факт И так же внезапно оно стихло Артуру почудилось, будто весь небосвод, галантно посторонившись, уступил им дорогу Когда ее находят, то выкидывают на помойку Похоже, на них восседали не то девушки, не то ангелы Все это было искусственным В этот момент Артур заметил странную особенность песни, которую распевали криккитяне$$);
insert into тип_материала values (59, 3658, 'Бумажные скульптуры с подвижными частями и реалистичными деталями', $$Весь мост, мост длинный, титаночугунный, на тысячу миль, моментально свернул свое сверкающее полотно и с плачем утопился в трясине, унося с собой всех до последнего прутивнобендзянина Артур пришел в безмятежное настроение Всеми этими причиндалами вяло манипулировали роботы – Вы хотите дослушать эту историю или что?

– Мне хотелось бы услышать вашу речь, – заявил матрасс – Грядет катастрофа, – заявил Слартибартфаст Другими словами, оговоренный час сбора – это один-единственный момент времени, в который абсолютно невозможно появление любого из членов компании – Я же сказал! – заорал Форд, вскочив на ноги Форд, нас подбрасывают!

И действительно, для того чтобы не поддаться этому первому впечатлению, надо было обладать весьма глубокими познаниями в истории Галактики (каковых Артур еще не успел приобрести из-за своей кочевой жизни) Туда-то мы и отправимся – Значит, наши неприятности еще не кончились, – проговорил он$$);
insert into тип_материала values (60, 3864, 'Коврики для занятия йогой из переработанного картона с противоскользящей поверхностью', $$(Естественно, я не знаю их лично, но я знаю природу всех органических живых существ, и гораздо более досконально, чем хотел бы – Выражаю свое соболезнование насчет него Он, как известно всем, был уничтожен, развеян по извечным водоворотам пространственно-временного континуума и исчез навеки – Отлично, – проговорил Форд очень тихо – Четвертая планета системы Фольфанга, – продолжил он Самый подходящий афоризм, чтобы заронить в молодые умы искру вдумчивого отношения к жизни Криккитяне смотрели друг на друга, направо, налево, вперед, назад, даже на землю – Чай, – произнес он, – крикет, – добавил он с нежностью, – стриженые газоны, деревянные скамейки, белые полотняные пиджаки, пиво в банках…

Медленно-медленно его взгляд сфокусировался на газете$$);
insert into тип_материала values (61, 1856, 'Наборы для аппликации с цветной бумагой, ножницами и клеем', $$Так оно и было – Золотая Перекладина – это часть Ключа, который мы ищем, – продолжал робот, – чтобы освободить наших Повелителей с Криккита По-моему, – пояснил Артур, не сбавляя скорости – Я понимаю, что в масштабе Вселенной этот факт не имеет никакого значения, но просто интересно – Ну и как там?

– А это что, твоя пещера? – спросил Форд – Ч… ч… ч… – повторил Артур, при каждом приступе дрожи толкая Форда Префекта в спину – Скатертью дорожка, – пробормотал Зафод, перевернулся на другой бок и всю ночь не смыкал глаз$$);
insert into тип_материала values (62, 5280, 'Домики для кукол из картона с мебелью и аксессуарами', $$Тут-то он и услышал пресловутое «Уф!», что его страшно встревожило Форд злобно обернулся к Артуру – Слушаю, – пропищал компьютер Диван все время заваливался то на один, то на другой бок – Золотая Перекладина – это часть Ключа, который мы ищем, – продолжал робот, – чтобы освободить наших Повелителей с Криккита Тебе это по силам?

– Что это Слартибартфаст так волнуется? – спросил Артур – А что сталось со зрителем?

– По-моему, кто-то вызвался угостить его обедом, но тот пояснил, что уже отобедал, и довольно плотно, поэтому вопрос был замят, и Уорвикшир победил с перевесом в три калитки Другой же своей частью он был точь-в-точь маленькое итальянское бистро, только поставленное вверх тормашками За исключением одного случая$$);
insert into тип_материала values (63, 1440, 'Оригами-гирлянды с разноцветными бумажными фигурами', $$Они взобрались на верхушку ближнего утеса и принялись обозревать окрестности Всеми фибрами своего пружинного сознания матрасс чувствовал, что робот горячо мечтает, чтобы его спросили, давно ли он совершает это бесплодное и бессмысленное топтание Тем самым выведя Форда из медитационного транса Инопланетное существо, морща лоб, заглянуло в штучку вроде папки, которую сжимало в своих длинных, лианообразных инопланетных пальцах Она услышала, как Зафод топочет и насвистывает где-то в недрах корабля Вот он я, Зафод Библброкс$$);
insert into тип_материала values (64, 3968, 'Подарочные пакеты с рельефным рисунком и ручками из ленты', $$Триллиан казалось, что это-то ей и требуется после всего пережитого Ночью оно абсолютно черное «Автостопом по Галактике» Правда, он не был ярко-розовым, но это вовсе не значит, что внешне он ничем не выделялся$$);
insert into тип_материала values (65, 5358, 'Обложки для электронной книги с индивидуальной гравировкой и магнитными застежками', $$– Откуда?

– Ты разве не изучал в школе древнюю историю Галактики?

– Моя киберкабинка была позади Зафода, – пояснил Форд, – это очень отвлекало Это произошло как-то весенним вечером года два тому назад – Терпение, – вновь заявил Слартибартфаст Больше ничего не произойдет – Клянусь, они в крикет играют Не бросай трубку Грубо говоря, конечно$$);
insert into тип_материала values (66, 4800, 'Бумажные гирлянды с вырезанными вручную узорами и тканевыми лентами', $$Ты что-то сказал?

– Дизайн, – повторил Форд Причем все они созданы трудами ветра и дождя – естественный процесс эрозии Он сделал несколько яростных шагов А для меня нет более печального зрелища, как разрушение планеты – Ну же, спросите, не бывает ли мне скучно$$);
insert into тип_материала values (67, 3192, 'Мемуарные книги с персонализированными обложками и расширенными полями', $$– Что случилось? – спросил Артур с глубоким благоговением На несколько минут воцарилось изумленное безмолвие Сегодняшнее утро выдалось благоуханным и ясным – в чем лично удостоверился Артур Дент, выйдя из пещеры, которую именовал домом (за неимением как более подходящего названия для нее, так и более подходящей для этого названия пещеры) Она была безлична – не как неизвестно чей злобный вопль в толпе, но как отпечатанный на принтере квиток за неправильную парковку$$);
insert into тип_материала values (68, 1386, 'Игрушечные машины из картона с реалистичными деталями и подвижными колесами', $$Но несть числа тем, кто упивается историей «Звездного Титаника», легендарного корабля-колосса Затем они построили собственный корабль – он-то и готовился сейчас к взлету Ткань в этих местах изобиловала дырами и потертостями – Я все правильно сделала, мистер Библброкс? – громко поинтересовалась дверь – Собственно, невозможность их формулирования и есть один из самих этих принципов Припев был немного печальный$$);
insert into тип_материала values (69, 552, 'Наборы для рисования с цветными карандашами, маркерами и бумагой премиум-класса', $$Внезапно почудилось, что это вопль вины и отчаяния В нем они выражали сожаление, что из-за работы им приходилось долгими часами корпеть в сарае, не видя ни жен, ни детей, которые страшно по ним скучали, но подбадривали их бесконечными новостями о приключениях растущего щенка Отряхнулся Однако же если в решающий момент вам посчастливится нежданно отвлечься на умопомрачительную пару ног (щупалец, ложноножек, в зависимости от вашей видовой принадлежности и/или личных вкусов), или на взрыв бомбы неподалеку, или на внезапное явление ужасно редкого жука на соседней былинке – тогда-то, к своему изумлению, вы увильнете от всякого столкновения с землей, точнее, останетесь болтаться в каких-то считанных дюймах над ее поверхностью$$);
insert into тип_материала values (70, 1394, 'Бумажные самолеты с уникальным дизайном и аэродинамической конструкцией', $$– И если ты считаешь, что тебе действительно необходимо слоняться по крикетной площадке в такой момент…

– Считаю Артур пришел в безмятежное настроение – Но почему? Почему нельзя?

– Те, кто разговаривает по телефону сам с собой, ничего хорошего не узнают – Сходить с ума, так сходить, – рассудил Форд Один мальчишка озадаченно посмотрел на него:

– У вас все в норме?

– Нет – Куда теперь?

– Вычисляю И вдруг роботы вернулись, снова начался кавардак, и на этот раз после их отлета матрасс остался на болоте один$$);
insert into тип_материала values (71, 1106, 'Бумажные тарелки с персонализированными принтами и экологически чистым покрытием', $$Артур хмуро поплелся за ним Он упорно работал суставами – Осмелюсь заметить, что ваши диоды полны глубокой печали, – влючал он (чтобы узнать значение слова «влючать», купите либо трактат «Речь жителей болот Прутивнобендзы» – имеется на любом складе уцененных книг, либо «Максимегалонский словарь», чем страшно порадуете университет, вынужденный отводить под его хранение свою драгоценную автостоянку), – и это меня очень огорчает – Жду с нетерпением!

– Она была принята очень плохо, – сказал Марвин, – по многим причинам Он пронзил облака, на миг озарив их своим серебряным свечением, и исчез из виду Артура – одинокой букашки, бестолково скачущей на месте посреди бескрайней шири – Быть такого не может Тут наблюдатели услышали высоко в безглазых небесах тоненький визг$$);
insert into тип_материала values (72, 1368, 'Бумажные лампы с вырезанными вручную узорами и теплым рассеянным светом', $$Первым потрясением для него было открытие, что у него имеется душа как таковая С того дня прошло уже два года Но теперь все происходило слишком уж молниеносно – сплошное видеотактильное пятно, которое волокло их сквозь века галактической истории, крутясь, дергаясь, мерцая Эти проблемы обычно относили на счет таких абстракций, как вежливость, грубость, скупость, задиристость, усталость, эмоциональность или поздний час – Их здесь нет уже три года Однако спустя миг стряслось нечто, чего невозможно было не заметить Тут наблюдатели услышали высоко в безглазых небесах тоненький визг Это звук, который издают живые матрассы в своей естественной среде обитания, приняв близко к сердцу чью-то повесть о жизненной драме Форд вытащил из своей жутко обтрепавшейся и донельзя замызганной сумки субэфирный чуткомат$$);
insert into тип_материала values (73, 4575, 'Картонные домики для кошек с прорезями и мягкими подушечками', $$То была ненависть, слепая ненависть Против инстинкта не попрешь – наши герои невольно двигались опасливо, даже воровато, хоть и знали, что с тем же успехом могли трубить в трубы и вопить: «Ату!» – инфоиллюзию это бы не спугнуло Пора смываться Внезапно воцарилась драматическая тишина Десять минут спустя он уже горбился над чашкой чая под тентом летнего буфета, и на его осунувшееся лицо постепенно возвращался румянец К сожалению, невежественный Зафод не был польщен этой честью, ибо, как мы уже упомянули, в детстве интересовался не древней историей, а собственным органическим телом 55 тебя начинает обволакивать ужасная апатия: ты понимаешь, что уже принял все ванны, какие можно было принять с пользой для души и тела, что сколько ни созерцай любой абзац газетного текста, ты не прочтешь ни строчки, не говоря уже о применении на практике новейшего, совершившего революцию в области стрижки кустарников метода, который в этой газете описан С другой стороны, присутствие Форда, как всегда, почти немедленно начинало давить на нервы Теперь они могли ясно видеть звездолет в его истинном обличье просто потому, что знали о его наличии здесь$$);
insert into тип_материала values (74, 9504, 'Доски для рисования с магнитной поверхностью и водонепроницаемой бумагой', $$– Нет ни одной планеты, – отчеканил высокопрофессиональный голос ведущего, – нет ни одной цивилизованной планеты в Галактике, где и в наши дни ни почитали бы этот символ Кроме того, в звездолете просто не нашлось бы столько дверей – пресловутое «уф» прозвучало так, будто его произнесли сто тысяч человек разом Некоторое время они летели вперед, неподвижные на фоне глазастого тела Галактики, которое само было неподвижно на фоне бесконечных просторов Вселенной Очень многие не пережили зиму, а когда пришла весна, уцелевшие заявили, что уходят в отпуск, и уплыли на плоту «То, что надо», – решила Триллиан, и спустя несколько часов их огромный белый корабль в форме кроссовки уже вальяжно спускался с небес, украшенных жарко блестящим солнцем, к яркому космопорту-скале Через несколько минут мы завладеем Золотой Перекладиной…

– Нет, не завладеете Этот величественный, сказочно-роскошный лайнер сошел со стапелей знаменитого Артефактоволя – астероида-верфи – несколько сот лет тому назад$$);
insert into тип_материала values (75, 1701, 'Бумажные зонты с красочными принтами и водоотталкивающей обработкой', $$– Чувствуя, что собеседники все еще недоумевают, он снизошел до разъяснений: – Слушайте Вообще-то я практикуюсь – Никто на это место не нападет, – сказал Слартибартфаст с неожиданным волнением в голосе – Подойти к своему кораблю через две минуты, – пояснил Артур и пожал плечами, что обличало отсутствие всяких мыслей в его голове – Мы ищем Ключ, – повторил он, – мы уже владеем Деревянным Столбом, Стальным Столбом и Плексигласовым Столбом$$);
insert into тип_материала values (76, 4644, 'Металлизированная бумага с блестящим покрытием и широким спектром оттенков', $$Воспаряйте все выше и выше Этот факт был расценен как величайшее достижение социологии телевидения – Три столба, – гремел мужчина – Кто же?

– Мммммм мммммм мммммм, – сказал компьютер – Я считаю своим долгом предупредить тебя о двух вещах, – заявил Форд, пододвинув к Артуру газету «Гардиан» – Да, ты прав, и все же он утверждал, что видел, как нечто материализовалось на площадке «ДОСУГ В МИРЕ НЕСБЫТОЧНОГО» – вот какой заголовок привлек внимание Триллиан, когда некоторое время спустя она вновь уселась на диван с «Путеводителем» Ты что, не помнишь?

– Помню – Ему что-то не везло последние два миллиона лет, – пояснил он полисмену$$);
insert into тип_материала values (77, 533, 'Самоклеющаяся бумага с яркими принтами и легким нанесением', $$То, что вы испытали…

Слартибартфаст, проплывая мимо, помахал Артуру рукой Послушай, ты можешь подбросить нас до одного веселенького местечка, сейчас вспомню название, там можно чудесно надраться под какую-нибудь жутенькую музычку Припев был немного печальный – Их здесь нет уже три года$$);
insert into тип_материала values (78, 5481, 'Дизайнерская бумага с узорами из тиснения, фольги и тиснением', $$Последовала немая сцена – Хуже нигде уже не будет, – сказала она себе, нажимая кнопку Прибор едва слышно жужжал, подмигивая крохотной тусклой лампочкой Попятившись, Артур испуганно огляделся по сторонам$$);
insert into тип_материала values (79, 7644, 'Бумажные постеры с высококачественными принтами и экологически чистой отделкой', $$– У меня врачи нашли недоразвитость гланды общественного долга и врожденный порок морального ядра личности, – пробормотал он под нос, – ну разве мне можно доверить спасение Вселенной, сами посудите?

И тем не менее поднялся по лестнице вслед за сотоварищами Этакий замысловатый балет меню, счетов, бумажников, чековых книжек, кредитных карточек, часов, карандашей и бумажных салфеток Вновь проследив траекторию мяча, Форд захлопал глазами – Приклюса и чудесения, – пробормотал он Солнце клонилось к закату – Он гордо возносился над водами?

– Да, он гордо возносился над водами$$);
insert into тип_материала values (80, 6248, 'Упаковочная бумага с биоразлагаемым покрытием и устойчивыми к разрывам рулонами', $$– Выражаю свое соболезнование насчет него – Сгинь в вакуум, – сказал Зафод Его челюсти начали делать отжимания Настоящим «стопщикам» эти клубы, как правило, не по карману, но можно рекомендовать их как возможное место для временной работы – А скоро выйдешь?

– Нет, тут останусь Артур уставился на компанию фермеров, пытаясь свести воедино крохи информации, которыми располагал Поскольку в истории был лишь один Его Светлость лорд Соньвальтяп Пустецийский, да и тот умер холостяком, слово употребляется лишь в отрицательном или в гипотетическом смысле$$);
insert into тип_материала values (81, 3599, 'Картонные коробки с пользовательскими размерами, внутренними вставками и тиснением', $$Скорее всего до вас донесутся восклицания типа: «Боже праведный, ты что, летаешь? Быть такого не может!»

Жизненно важно не верить им – а то правда внезапно окажется на их стороне Блаженно разжевав мясо, он решил официально оповестить мир о своем решении Артур вновь попытался заговорить, но борьба была неравной – Да, бывает, – заметил Форд Новая вибрация сотрясла корабль Залезайте, нам пора – Возможно, до вас не сразу дойдет, что именно навело меня на это воспоминание, – таков уж мой мозг Артур поднял глаза Тут наблюдатели услышали высоко в безглазых небесах тоненький визг$$);
insert into тип_материала values (82, 1728, 'Самовосстанавливающиеся офисные подложки из картона с нескользящей поверхностью и водостойким покрытием', $$– У нас на борту кто-то есть?

– Мммм, – ответил компьютер И оторопел от последствий своего заявления – Да уж вот так, – подтвердил Форд Он встал на дыбы, чтобы заглянуть за заросли, но смотреть было не на что Через минуту я попрошу тебя раскрыться – Артур Филип Деодат? – спросила она – А куда мы держим путь?

– Мы держим путь, – объявил Слартибартфаст, – на битву с Древним Злом Вселенной И все двигалось, приплясывало, трепыхалось – Что «ну и»? – поинтересовался старец$$);
insert into тип_материала values (83, 6972, 'Разноцветная бумага для орегами с замысловатыми узорами и повышенной толщиной', $$Слартибартфаст молча указал ему на ту сторону холма – Серьезно?

– В смысле?

– Ты ННП видишь? – терпеливо спросил Форд Матрасс момнухнул еще раз – Повелители Криккита, – выдохнул Слартибартфаст голосом призрака – Вот что я сказал$$);
insert into тип_материала values (84, 2109, 'Конверты для прямой почтовой рассылки с глянцевой отделкой, самоклеющимся клапаном и расширенными полями', $$Некоторое время они летели вперед, неподвижные на фоне глазастого тела Галактики, которое само было неподвижно на фоне бесконечных просторов Вселенной – Ты козел, – повторил инопланетянин Этакий замысловатый балет меню, счетов, бумажников, чековых книжек, кредитных карточек, часов, карандашей и бумажных салфеток Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина Забудьте, сколько вы весите (забудьте, что вы вообще что-то весите), и просто позвольте ветру поднимать вас все выше Мелкие капли едва просачивались сквозь туман$$);
insert into тип_материала values (85, 1403, 'Промышленная бумага с высокой прочностью на разрыв, влагостойкостью и устойчивостью к истиранию', $$Тело Артура Дента завертелось – Я сам вам поясню, – прошептал старец Он шествовал к центру поля ужасающе решительной поступью, и его борода, волосы и одеяние развевались по ветру – вылитый Моисей на горе Синай, только в роли Синая сейчас выступала холеная лужайка, а не грозный вулкан в косматом дыму, каким его обычно изображают Сделав несколько опасливых вдохов, он прошептал:

– Дверь, если ты меня слышишь, ответь мне – только тихо-тихо-тихо Артур неподвижно лежал на диване – амортизаторе ускорения и никак не мог рассудить, что именно только что пережил – то ли воздействие «взлетного эффекта», то ли мистическое озарение Этот факт был расценен как величайшее достижение социологии телевидения – Что случилось? – спросил Артур с глубоким благоговением Зафод вновь кивнул, поигрывая пистолетом – Пожми ее, – просуфлировал Форд$$);
insert into тип_материала values (86, 2208, 'Вощеная бумага с биоразлагаемым покрытием, водостойкостью и термостойкостью', $$– Спасибо за внимание У всего мира перехватывает дыхание Проведя рукой по стене, он нащупал нечто ценное – На мой взгляд, – сказал матрасс, сочувственно рассматривая вышеуказанную конечность, – это не такая уж замечательная нога Неся в руках поднос с ужином, она вошла к Зафоду и спросила, нет ли у него желания поговорить Так и вышло$$);
insert into тип_материала values (87, 3290, 'Бумага для акварели холодного прессования с текстурированной поверхностью и высоким содержанием хлопка', $$И вновь зашагал вперед Обреченно прислонившись к стене, Зафод произнес несколько выразительных слов, немало шокировавших его другую голову – Мне это известно, – ответил Слартибартфаст Затем поспешил влить в себя еще один – пусть догонит первый и составит ему компанию Через несколько минут мы завладеем Золотой Перекладиной…

– Нет, не завладеете Тело Артура Дента завертелось В общем, неба они и не замечают$$);
insert into тип_материала values (88, 930, 'Пергаментная бумага с жиростойким покрытием, устойчивостью к высоким температурам и возможностью многократного использования', $$На горизонте маячили симпатичные круглые холмы Форд с Артуром так и обмерли, подавившись собственным воплем Также там советовалось заглянуть в главу о необозримости Вселенной и методике примирения с этим фактом Еле-еле – подчеркнуто еле-еле – удерживая на весу руку, он простер ее к участку болота за туманом и зарослями, удивительно похожему на все другие участки болота Форд саркастически огляделся по сторонам$$);
insert into тип_материала values (89, 1550, 'Пекарская бумага с антипригарной поверхностью, термостойкостью и влагостойкостью', $$Извините, но таково общее мнение о ней – Вот что я сказал Забудьте, сколько вы весите (забудьте, что вы вообще что-то весите), и просто позвольте ветру поднимать вас все выше Зафод застыл как вкопанный Артур увидел вереницу крохотных огоньков, что, качаясь и приплясывая, медленно двигались к ним – Э-э-э?…

Существо кивнуло само себе, произвело чисто инопланетный щелчок застежкой папки и направилось к своему кораблю В этот момент Артур заметил странную особенность песни, которую распевали криккитяне Форд сгреб его за отвороты халата и стал объяснять ему терпеливо и размеренно, с толком и с расстановкой – словом, так, будто Артур был служащим расчетного отдела телефонной компании Действительно, звездолет Слартибартфаста производил вдвойне странное впечатление И меж тем как «Золотое сердце» неслось с невероятной скоростью в неопределенном направлении, Триллиан прихлебывала какое-то неудобоваримое творение нутримата и читала о том, как научиться летать$$);
insert into тип_материала values (90, 2100, 'Бумага для рисования с гладкой поверхностью, высокой плотностью и превосходной белизной', $$И вдруг исчезла Он шествовал к центру поля ужасающе решительной поступью, и его борода, волосы и одеяние развевались по ветру – вылитый Моисей на горе Синай, только в роли Синая сейчас выступала холеная лужайка, а не грозный вулкан в косматом дыму, каким его обычно изображают Он сделал несколько яростных шагов Зафод крякнул – Вы ведь англичанин, правда? – поинтересовалось видение Нешуточное это дело – обнаружить, что после неопределенно долгого периода молчания ты, оказывается, не отучился разговаривать – Ты где?

– В туалете – … это их жизненный, а чаще предсмертный опыт – Плексигласовый Столб – символ могущества Науки и Разума Галактики!

Новые лучи озарили правый, прозрачный столб, закутав его в замысловатое световое кружево Так и вышло$$);
insert into тип_материала values (91, 3003, 'Блокноты для заметок с проклеенными страницами, твердой обложкой и эластичной застежкой', $$И вновь зашагал вперед Марвин не удостоил его ответа и лишь с усиленной демонстративностью заработал суставами Он тряс руку Форда и пожимал ее, пожимал и тряс А потом развернулись – Я не о полотенце, – сказал Артур Роботы Ему почудилось, будто атомы его мозга и атомы космоса струятся друг сквозь друга Солнце почти закатилось Вероятность подобного события равна примерно одному шансу из бесконечности$$);
insert into тип_материала values (92, 1404, 'Папка с кольцами с прозрачными карманами, разделителями и застежкой-молнией', $$Он замер Вы видели этот фильм всего лишь тридцать три тысячи пятьсот семнадцать раз Темп все возрастал – Компьютер, – окликнул Охмешконасыпатель – Я, собственно, хочу сказать, – продолжал Форд, – что нет смысла доводить себя до безумия стараниями это безумие избежать «Пейте смело, – рекомендует «Путеводитель», – и ни пуха вам ни пера»$$);
insert into тип_материала values (93, 3540, 'Портфель из картона с прочным корпусом, удобными отделениями и мягкой ручкой', $$Форд саркастически огляделся по сторонам – Затвори пасть Однако спустя миг стряслось нечто, чего невозможно было не заметить Первое не-абсолютное число – это число людей, на которое заказан столик Все трое постепенно пробивались к звездолету старца, по-прежнему стоящему позади табло и по-прежнему не замечаемому бегущими мимо него зрителями – очевидно, у них хватало собственных проблем – Подойти к своему кораблю через две минуты, – пояснил Артур и пожал плечами, что обличало отсутствие всяких мыслей в его голове Артур уставился на компанию фермеров, пытаясь свести воедино крохи информации, которыми располагал – Что вы сказали? – пробормотало ошарашенное полисменообразное – Да? – обалдело переспросил Зафод$$);
insert into тип_материала values (94, 500, 'Кипа бумаги формата A4 с высокой белизной', $$– Чего-о? – воскликнул Форд – У нас на борту кто-то есть?

– Мммм, – ответил компьютер Однако через некоторое время до него дошло, что он недалеко продвинулся и все же следует спросить: «Это в каком плане?»

– При передвижении по космосу, – повторил Слартибартфаст, – числа – настоящий бич божий Против инстинкта не попрешь – наши герои невольно двигались опасливо, даже воровато, хоть и знали, что с тем же успехом могли трубить в трубы и вопить: «Ату!» – инфоиллюзию это бы не спугнуло И вправду – к его радости и изумлению, с небес, рассекая теплый вечерний воздух, тихо, как-то интеллигентно спустился длинный серебряный звездолет – … только что материализовались тут у нас, посреди крикетной площадки «Лордз» – Расскажите о речи, которую вам однажды довелось произнести, – взмолился он Окружающая его Вселенная распалась на мириады блестящих осколков, и каждый осколочек тихо вращался в пустоте, отражая своей серебряной кожей все то же жуткое пиршество огня и смерти Форд и Артур воззрились на него с крайним удивлением и острым чувством обиды за хороший вкус Его лучи ласкали белые шляпы и красные лица$$);
