insert into сообщение values (1, 1, 'консультант', $$Звездолет басовито загудел Заблудившемуся в пространстве хотя бы не угрожает смерть со скуки Его взгляд неспешно подполз к дате, по которой Форд лениво постукивал пальцем$$, '2023-02-02 09:47:15.757268');
insert into сообщение values (2, 1, 'клиент', $$Он прошел к зеленой винтовой лестнице из кованого железа, непонятно зачем помещенной в середине рубки, и начал всходить по ней$$, '2023-01-31 16:45:17.085420');
insert into сообщение values (3, 1, 'клиент', $$– И я хочу знать, можешь ли ты ее видеть Нежданно-негаданно вывалившись из пространственно-временной аномалии в чудный, совершенно очаровательный лондонский денек, Форд с Артуром совершили довольно жесткую посадку на безупречный газон площадки «Лордз» Разумеется, экипаж не реагировал на присутствие посторонних – ведь их тут, в сущности, и не было Он встал на дыбы, чтобы заглянуть за заросли, но смотреть было не на что$$, '2023-02-02 07:42:56.435810');
insert into сообщение values (4, 2, 'клиент', $$И там и сям царил глухой мрак Порой он замирал, часто моргая Что ни говори, а Криккит казался приятным во всех отношениях местечком$$, '2023-01-18 22:56:25.968863');
insert into сообщение values (5, 2, 'консультант', $$Артуру невольно представилось, как Пол Маккартни, восседая с ногами в кресле у камина, мурлычет эту песенку Линде и соображает, что бы такое купить на доходы с нее – то ли Эссекс, то ли Ирландию – Все последние пять лет приснились мне во сне Странно, но факт$$, '2023-01-18 09:03:03.676977');
insert into сообщение values (6, 2, 'клиент', $$– Не слишком похоже на наш случай Забудьте, сколько вы весите (забудьте, что вы вообще что-то весите), и просто позвольте ветру поднимать вас все выше – Теперь понял?

– Нет, – признался Артур$$, '2023-01-15 23:36:46.211783');
insert into сообщение values (7, 3, 'консультант', $$С этим вместилищем у нее были связаны не самые лучшие воспоминания$$, '2023-01-19 20:14:02.641466');
insert into сообщение values (8, 3, 'клиент', $$– Я этот номер уже видел, – проговорил он Если бы его спросили, он бы ответил, что все время мурлычет первую строчку песни «Психология любви» Ах, как прекрасен – аж глазам больно – был «Звездный Титаник», когда, точно арктурианский мегавакуумный серебристый кит, он качался в лазерных тенетах гибких строительных лесов – Диван исчез$$, '2023-01-19 05:28:42.975674');
insert into сообщение values (9, 3, 'клиент', $$Тихо-тихо-тихо дверь прошептала:

– Я вас слышу Марвин шагал – Речь, – взмолился матрасс Охмешконасыпатель скорбно и устало прикрыл глаза, заказал бортовой стереосистеме какой-нибудь легкий джаз и рассудил, что все бы ничего, если бы не воскресные дни, будь они неладны$$, '2023-01-20 07:36:01.013149');
insert into сообщение values (10, 3, 'клиент', $$– Мы отправляемся в путь, – вскричал он, весь трепеща от прилива сил$$, '2023-01-17 18:59:17.937268');
insert into сообщение values (11, 4, 'консультант', $$По-моему, это было животное из семейства аллигаторов – Ву-ун, – заметил матрасс$$, '2023-01-28 21:43:48.096591');
insert into сообщение values (12, 4, 'консультант', $$Он тоже задрал голову Прижав к стене кончики пальцев, он ощутил странную вибрацию Меня заставляли сидеть на ящике и рассказывать мою историю, а зрители уговаривали меня приободриться и мыслить позитивно$$, '2023-01-30 12:44:10.293451');
insert into сообщение values (13, 4, 'консультант', $$И ухмыльнулся с хорошо рассчитанной издевкой Он взошел по трапу и исчез в недрах корабля$$, '2023-01-30 06:29:26.815179');
insert into сообщение values (14, 4, 'консультант', $$– Ты козел, – повторил инопланетянин Под ними расстилались серебристо-белые ризы Аллосиманиуса-Синеки Я стал звездой экспозиции Тогда бы ему заметили, что он поет только одну ноту, на что бы он ответил, что по очевидным, как ему кажется, причинам он опустил кусочек «ология любви»$$, '2023-01-30 07:38:25.921736');
insert into сообщение values (15, 5, 'консультант', $$– Я стоял на центральной платформе Почва производила впечатление тяжелой и вязкой, трава была упруга$$, '2023-02-06 09:39:48.402868');
insert into сообщение values (16, 5, 'консультант', $$– Он сказал подождать у его корабля, – сообщил Артур По какой-то непостижимой причине их элегантные обтекаемые тела казались совершенным олицетворением чистого, патологического зла$$, '2023-02-08 14:57:06.649603');
insert into сообщение values (17, 5, 'консультант', $$Это произошло как-то весенним вечером года два тому назад Наше странствие уже началось$$, '2023-02-08 16:14:11.541870');
insert into сообщение values (18, 6, 'консультант', $$) Ха! О, жизнь моя – жестянка, жестянка на червячном ходу!

И снова побрел вокруг своей тонкой стальной ноги-протеза, которая вращалась в грязи, но никак не поддавалась Артур неподвижно лежал на диване – амортизаторе ускорения и никак не мог рассудить, что именно только что пережил – то ли воздействие «взлетного эффекта», то ли мистическое озарение$$, '2023-02-09 04:18:02.623354');
insert into сообщение values (19, 6, 'консультант', $$Правда, роботы сыпались не абы как, а четким военным строем$$, '2023-02-09 01:08:10.517098');
insert into сообщение values (20, 6, 'консультант', $$За исключением одного случая Криккитяне смотрели друг на друга, направо, налево, вперед, назад, даже на землю – Через несколько минут, – терпеливо повторил робот, – мы завладеем Золотой Перекладиной…

– Фигушки, – сказал Зафод$$, '2023-02-09 22:16:27.978265');
insert into сообщение values (21, 7, 'консультант', $$Правда, роботы сыпались не абы как, а четким военным строем Это звук, который издают живые матрассы в своей естественной среде обитания, приняв близко к сердцу чью-то повесть о жизненной драме Наши Повелители выйдут на свободу Робкий солнечный луч, случайно пробившийся сквозь туман, высветил синие и белые полоски на шкуре матрасса, чем немало его напугал$$, '2023-03-01 06:16:46.957025');
insert into сообщение values (22, 7, 'клиент', $$Несбыточная греза Робинзона – корабль – Вон там! – вскричал Форд, дико взмахнув рукой$$, '2023-02-28 00:23:37.328892');
insert into сообщение values (23, 7, 'консультант', $$По крайней мере там он будет чувствовать себя во всеоружии$$, '2023-02-27 11:31:13.657095');
insert into сообщение values (24, 7, 'консультант', $$– Здесь, на болоте Даже Форд, похоже, повеселел$$, '2023-02-28 21:41:40.476198');
insert into сообщение values (25, 8, 'консультант', $$Он уставился вверх$$, '2023-03-26 08:43:24.708686');
insert into сообщение values (26, 8, 'консультант', $$Солнечный свет золотил кроны деревьев, сверкал на рассекающих воздух крикетных битах, сиял на поверхности крайне необычного (и никем не замечаемого) объекта, что был припаркован за стадионным табло Большинству людей промахнуться не удается, и чем больше усилий они прилагают, тем крупнее вероятность столкновения с землей$$, '2023-03-25 22:20:40.120756');
insert into сообщение values (27, 8, 'клиент', $$– А скоро выйдешь?

– Нет, тут останусь$$, '2023-03-24 23:40:20.844182');
insert into сообщение values (28, 9, 'клиент', $$– А… мт… – выпалил он Но радовался он зря Но тьма – глухой кокон, оберегающий внутренний мрак, – все еще гудела вокруг корабля Спустя четырнадцать часов солнце хмуро опустилось за противоположный горизонт с чувством зазря потраченного труда$$, '2023-04-15 15:02:04.074765');
insert into сообщение values (29, 9, 'клиент', $$– … напомни, чтобы я дал сам себе в зубы Осмелюсь признаться, я питаю некоторую слабость к крикету, хотя я не хотел бы, чтобы о ней знали за пределами этой планеты$$, '2023-04-13 03:44:43.570691');
insert into сообщение values (30, 10, 'клиент', $$Но возможно, тебе любопытно будет узнать, что твой покорный слуга единолично ответственен за удлиненную форму животного, которому в будущих веках дадут имя «жираф» Артур откашлялся Звездолет басовито загудел$$, '2023-02-04 19:00:58.155184');
insert into сообщение values (31, 10, 'клиент', $$– А ты видишь?

– Да$$, '2023-02-05 11:53:57.517278');
insert into сообщение values (32, 10, 'консультант', $$Хотя в горле у него привычно саднило от традиционного утреннего душераздирающего вопля, он внезапно пришел в великолепное расположение духа$$, '2023-02-04 22:43:25.993045');
insert into сообщение values (33, 10, 'консультант', $$Из тьмы прямо на них вылетел, изрытая лазерный огонь, боевой звездокрейсер размером с небольшой промышленный город$$, '2023-02-05 00:59:06.269387');
insert into сообщение values (34, 11, 'клиент', $$– На мой взгляд, – сказал матрасс, сочувственно рассматривая вышеуказанную конечность, – это не такая уж замечательная нога$$, '2023-03-16 16:48:06.657662');
insert into сообщение values (35, 11, 'консультант', $$В висках у Артура раздался привычный тупой звон, очень часто сопровождавший его разговоры с Фордом$$, '2023-03-17 23:10:40.608040');
insert into сообщение values (36, 11, 'клиент', $$– Но почему? Почему нельзя?

– Те, кто разговаривает по телефону сам с собой, ничего хорошего не узнают Душа Артура летала вокруг его тела кругами и мялась, не испытывая особенного желания войти Звездолет басовито загудел$$, '2023-03-19 00:49:30.690609');
insert into сообщение values (37, 11, 'консультант', $$– Эти самые, с которыми он разговаривал Робкий солнечный луч, случайно пробившийся сквозь туман, высветил синие и белые полоски на шкуре матрасса, чем немало его напугал$$, '2023-03-16 19:34:35.102013');
insert into сообщение values (38, 12, 'клиент', $$Внезапно Форд начал буквально излучать энергию и целеустремленность$$, '2023-03-07 02:05:49.852040');
insert into сообщение values (39, 12, 'клиент', $$Им составляли компанию недоеденные ломти хлеба и недопитые бокалы вина – Н?

– … НП$$, '2023-03-05 11:22:15.753109');
insert into сообщение values (40, 12, 'клиент', $$– Когда мы последний раз виделись, вы сказали то же самое, – заметил Артур Сделав несколько опасливых вдохов, он прошептал:

– Дверь, если ты меня слышишь, ответь мне – только тихо-тихо-тихо$$, '2023-03-04 22:31:42.225365');
insert into сообщение values (41, 13, 'консультант', $$Каков мерзавец? И продал меня в Психозоопарк Мы живем тихой, уединенной жизнью на болоте, радостно флёпаем и влючим, а на сырость смотрим плучительными глазами – Так что вы тут делаете, мужики?

Молчание$$, '2023-04-21 17:05:49.882287');
insert into сообщение values (42, 13, 'клиент', $$На несколько минут воцарилось изумленное безмолвие$$, '2023-04-21 20:50:14.294533');
insert into сообщение values (43, 13, 'консультант', $$Колоссальные аккорды Оно, случайно, не твое?

– Изволь заткнуться насчет твоего полотенца! – воскликнул Форд$$, '2023-04-23 08:41:33.998910');
insert into сообщение values (44, 14, 'консультант', $$– Если тревога ложная, я сойду с ума, – добавил он, – еще разок Матрасс зауйломикал с головы до пят, отчего гладь мелкой, заросшей ряской протоки подернулась восторженной рябью – Э-э-э?…

Существо кивнуло само себе, произвело чисто инопланетный щелчок застежкой папки и направилось к своему кораблю$$, '2023-05-31 21:41:15.356489');
insert into сообщение values (45, 14, 'клиент', $$Те, кто рождается бессмертным, от рождения бессознательно свыкаются с этим своим свойством, но Охмешконасыпатель – не из их числа$$, '2023-05-31 07:03:12.154974');
insert into сообщение values (46, 14, 'консультант', $$Вокруг них расстилались нежно-зеленые поля и луга Скорбное выражение на лице Артура Дента уступило место еще более скорбному Зафод застыл как вкопанный Он спорил с судьбой, лез на рожон, срывал цветы удовольствий и сумасшедшие деньги на высокодоходных долгосрочных сберегательных вкладах… в общем, давал всем жизни, как говорится$$, '2023-05-31 11:30:44.233274');
insert into сообщение values (47, 15, 'консультант', $$– Искомый субъект – некрупный слизняк, – пискнул он, – из рода А-Рт-Ур-Еа-Ипдену – Да так, ничего особенного, – сказал Форд Замотав головой, Форд закрыл лицо руками и нечаянно отфутболил к стене подвернувшийся под ногу цветочный горшок$$, '2023-04-08 19:00:04.845076');
insert into сообщение values (48, 15, 'клиент', $$Они стояли одни-одинешеньки на вершине утеса где-то на доисторической Земле и решительно смотрели друг другу в глаза – Какое-то «что»?

– ННП Оно, случайно, не твое?

– Изволь заткнуться насчет твоего полотенца! – воскликнул Форд – Вы ведь англичанин, правда? – поинтересовалось видение$$, '2023-04-09 13:21:11.010574');
insert into сообщение values (49, 15, 'клиент', $$В каждом рассвете есть миг, когда свет не льется вниз, а парит, миг, когда возможно чудо Большую часть всех абсурдных вещей, какие приходили ему в голову, он уже повидал наяву То есть больно будет, если вам не удастся промахнуться мимо земли – Так оно и вышло, – сказал Слартибартфаст$$, '2023-04-09 20:29:07.167784');
insert into сообщение values (50, 16, 'клиент', $$– Где?

– Там Из тьмы прямо на них вылетел, изрытая лазерный огонь, боевой звездокрейсер размером с небольшой промышленный город – Странная весть, – процедил Форд Криккитяне смотрели друг на друга, направо, налево, вперед, назад, даже на землю$$, '2023-03-07 11:57:31.774753');
insert into сообщение values (51, 16, 'консультант', $$Мы живем тихой, уединенной жизнью на болоте, радостно флёпаем и влючим, а на сырость смотрим плучительными глазами – Ты козел, – повторил инопланетянин$$, '2023-03-06 23:20:47.933066');
insert into сообщение values (52, 16, 'клиент', $$Ему так и не удалось отключить разговорные блоки дверей – Это только документальный фильм, – вскричал он Он резко сел на кровати, начал натягивать одежду Артур приосанился, взглянул миру прямо в поля и леса$$, '2023-03-07 08:24:35.493282');
insert into сообщение values (53, 16, 'консультант', $$– Он вытащил «Путеводитель» и просмотрел по диагонали страницы указателя, специально посвященные вопросам секса, наркотиков и рок-н-ролла Мне это кажется чрезвычайно странным, тем более что сумку я сшил на доисторической Земле своими руками Однако казалось, если что тут и назревало, так только какая-то церемония Он мягко приземлился$$, '2023-03-06 12:44:25.572701');
insert into сообщение values (54, 17, 'консультант', $$Он вновь задумался о происшедшем$$, '2023-03-22 16:55:30.423635');
insert into сообщение values (55, 17, 'консультант', $$При этих словах Артура точно пчела ужалила – Какое расстояние мы сейчас преодолели? – спросил Форд Наше странствие уже началось$$, '2023-03-23 03:26:33.924002');
insert into сообщение values (56, 17, 'консультант', $$Но несть числа тем, кто упивается историей «Звездного Титаника», легендарного корабля-колосса Прикрыв один глаз, он что-то созерцал другим Но тут же просияв, перевел взгляд на широкий экран панорамного обзора, где струились, головокружительно сплетаясь и расплетаясь вокруг корабля, серебряные нити$$, '2023-03-22 04:40:33.105570');
insert into сообщение values (57, 17, 'консультант', $$К сожалению, именно терминалы рубки Зафод и заткнул кляпом После чего возобновил розыски – Ты никчемный кретин, – сообщило существо$$, '2023-03-22 21:17:15.482816');
insert into сообщение values (58, 18, 'клиент', $$– Из мглы времен восстало великое проклятие, – сказал Слартибартфаст – И это было величественное зрелище?

– Довольно величественное$$, '2023-07-05 06:46:20.775341');
insert into сообщение values (59, 18, 'клиент', $$С его шкурки, заплимтавшей от умиления, во все стороны полетели брызги воды Она была срежиссирована скорее для блага телезрителей, чем просто зрителей, и со своего места в толпе они могли следить за ней только по сообщениям ближайшего репродуктора Отключив всю кухонную автоматику, она приготовила самый роскошный ужин, какой был в ее силах, – аппетитно прожаренное мясо, ароматные фрукты, благоуханный сыр, коллекционные альдебаранские вина Они стояли одни-одинешеньки на вершине утеса где-то на доисторической Земле и решительно смотрели друг другу в глаза$$, '2023-07-02 15:20:48.052998');
insert into сообщение values (60, 19, 'клиент', $$Солнце нехотя попыталось одолеть туман, пробуя то тут добавить немножко тепла, то вон туда запустить несколько лучиков, но, судя по всему, сегодня его ожидала очередная тягомотная прогулка от горизонта до горизонта – И все же довел это дело до конца$$, '2023-06-06 01:48:44.777080');
insert into сообщение values (61, 19, 'консультант', $$Глаза Форда, провожавшего взглядом мяч, широко распахнулись Досчитав про себя до десяти значительных десятеричных концептов (то есть отмерив паузу, призванную выразить общее презрение ко всем матрассам и самой идее матрассности), робот вновь принялся описывать миниатюрные круги – Я все правильно сделала, мистер Библброкс? – громко поинтересовалась дверь$$, '2023-06-04 10:53:19.003290');
insert into сообщение values (62, 19, 'консультант', $$– Повелители Криккита, – выдохнул Слартибартфаст голосом призрака – Спасибо, что осчастливили простую скромную дверцу Длинный стол$$, '2023-06-06 02:52:49.251094');
insert into сообщение values (63, 20, 'консультант', $$И перевел взгляд на чудо творения за иллюминатором Когда его знакомые (даже у таких типов бывают знакомые) намекали, что план не только этически неприемлем, но и неосуществим – поскольку все время кто-то умирает, а кто-то рождается, Охмешконасыпатель просто вперял в оппонента свой стальной взгляд и бурчал: «Что, и помечтать нельзя?»

Итак, он взялся задело Слартибартфаст занял освободившееся благодаря этому происшествию место и окинул суровым взглядом меню – Вот что я сказал$$, '2023-10-11 07:33:48.686757');
insert into сообщение values (64, 20, 'клиент', $$Темп застольных манипуляций неуловимо ускорился Вам того же$$, '2023-10-07 19:04:38.912838');
insert into сообщение values (65, 21, 'консультант', $$Шшшшрр Топ-топ-топ-топ Артур был совершенно счастлив$$, '2023-03-29 09:45:41.990522');
insert into сообщение values (66, 21, 'клиент', $$– Вам весело? – спросил матрасс Разница была только в том, что посылаемые их битами мячи при соприкосновении с землей взрывались$$, '2023-03-31 07:59:41.352498');
insert into сообщение values (67, 21, 'консультант', $$Вероятно, людей обуяла коллективная мысль «Ну и дела!», сопровождаемая единодушным чувством недоумения Он уже много дней шлялся, не зная покоя, по «Золотому сердцу», но еще не было случая, чтобы какая-нибудь дверь сказала: «Уф!» Да и сейчас он был почти уверен, что «Уф!» исходило не от двери$$, '2023-03-29 21:24:02.319755');
insert into сообщение values (68, 22, 'клиент', $$Затем Триллиан набрела на главку о Хэй-Виляй, экзотической планете-курорте, одном из чудес Галактики – Мм… да, – ответил Артур Слепящий свет, подобно цунами, захлестнул мрак и откатился, унося с собой большой кусок планеты, что висела прямо под их ногами$$, '2023-05-19 11:22:57.811212');
insert into сообщение values (69, 22, 'клиент', $$Что ж, одной загадкой меньше Форд повторил – Ты никчемный кретин, – сообщило существо – Ага, – произнес он со вздохом облегчения (что вряд ли было разумно), – видите ли, робот, я не хотел перенапрягать ваше воображение$$, '2023-05-18 07:18:11.713966');
insert into сообщение values (70, 22, 'клиент', $$В вечерней тиши они стояли на вершине холма Он только пялился на нее – ему еще не доводилось видеть девушку, способную сидеть на коленях у себя самой$$, '2023-05-17 23:07:18.081564');
insert into сообщение values (71, 22, 'консультант', $$Ткань в этих местах изобиловала дырами и потертостями Одиннадцать белых роботов И камни тоже не мои, – добавил он, вытащив из сумки горсть плоских серых камешков А потом даже гумкнул от избытка чувств$$, '2023-05-17 15:12:54.881595');
insert into сообщение values (72, 23, 'клиент', $$Очень многие не пережили зиму, а когда пришла весна, уцелевшие заявили, что уходят в отпуск, и уплыли на плоту А еще я пробовал научиться летать$$, '2023-08-20 22:24:44.596643');
insert into сообщение values (73, 23, 'консультант', $$По-видимому, это словесное излияние вдохновило его на новый взлет к высотам уныния и отчаяния$$, '2023-08-19 12:35:35.191422');
insert into сообщение values (74, 23, 'консультант', $$– Странный звездолет – Артур, – сказал Форд И камни тоже не мои, – добавил он, вытащив из сумки горсть плоских серых камешков$$, '2023-08-19 12:30:19.840229');
insert into сообщение values (75, 24, 'консультант', $$– Не могу я с ней сжиться, – мрачно вымолвил он и выслал в свой желудок третий стакан: пусть найдет второй и выяснит, почему тот еще не доложил о здоровье первого Защитник, взмахнув битой, послал мяч себе за спину так, что он пролетел над табло Те, кто рождается бессмертным, от рождения бессознательно свыкаются с этим своим свойством, но Охмешконасыпатель – не из их числа Хлюп, хлюп – шагал он по болоту$$, '2023-07-06 20:56:28.478989');
insert into сообщение values (76, 24, 'клиент', $$Артур наморщил лоб:

– А почему на вашем корабле все вычисления… – И прикусил язык – Было что-то интересное?

И вновь они балансировали на краю ужасно высокого утеса Солнце почти закатилось Внутри царила историческая тишина$$, '2023-07-04 14:14:21.144719');
insert into сообщение values (77, 24, 'консультант', $$Как-то ночью – а теперь на корабле ночь длилась постоянно – лежа в постели, он решил взять себя в руки, предпринять что-нибудь конструктивное – Нет, – сказал Форд, – он чувствует мобильную аномалию в ткани пространства-времени, локальное возмущение, очаг нестабильности$$, '2023-07-04 23:45:32.072838');
insert into сообщение values (78, 25, 'консультант', $$– Надеюсь, куда-нибудь, где солнышко светит, – проговорил Форд Похоже, в основном он состоял из низеньких зданий, построенных из белого камня$$, '2023-09-02 08:48:53.872043');
insert into сообщение values (79, 25, 'консультант', $$– Сгинь, тебе говорят, дурилка пластиковая Поплотнее запахнувшись в свой обтрепанный халат, он приветствовал доброе утро широкой улыбкой$$, '2023-09-02 18:16:47.433109');
insert into сообщение values (80, 26, 'консультант', $$– Тс-с, – прошипел Форд и глубокомысленно воздел очи горе И поторопился опустошить его, пока не случилось чего похуже Так оно и было – Куда? На чем? – воскликнул Артур$$, '2023-09-16 23:44:23.269652');
insert into сообщение values (81, 26, 'консультант', $$Похоже, на них восседали не то девушки, не то ангелы$$, '2023-09-13 22:45:44.308022');
insert into сообщение values (82, 26, 'клиент', $$Приятели направились к пресловутому кораблю Если бы его спросили, он бы ответил, что все время мурлычет первую строчку песни «Психология любви» Затем он совершил нечто, что матрассы обычно делать ленятся$$, '2023-09-15 09:55:03.266001');
insert into сообщение values (83, 27, 'консультант', $$«Фундаментальное сердце духа и Вселенной может отдыхать, – подумал он, – это все туфта»$$, '2023-05-23 03:49:49.502657');
insert into сообщение values (84, 27, 'консультант', $$Она даже не задала машине никаких координат – ей было все равно, куда бежать Топ-топ-топ-топ По-видимому, он полагал, что мнение Слартибартфаста слишком оптимистично$$, '2023-05-23 02:00:49.882110');
insert into сообщение values (85, 28, 'клиент', $$«Пейте смело, – рекомендует «Путеводитель», – и ни пуха вам ни пера» – Он вновь раскрыл глаза и блаженно улыбнулся – А я спал, – заявил вынырнувший откуда-то Форд$$, '2023-07-09 22:27:22.424012');
insert into сообщение values (86, 28, 'консультант', $$Попятившись, Артур испуганно огляделся по сторонам Тихо проскользнув под ветками, они поднялись вслед за веселой компанией по тропке в гору – И сумка тоже не моя, – неожиданно объявил Артур Вдвоем они взвалили Артура на диван и унесли с поля, причем неожиданное исчезновение дивана на полдороге задержало их совсем ненадолго$$, '2023-07-12 02:46:45.896533');
insert into сообщение values (87, 28, 'консультант', $$– Их здесь нет уже три года$$, '2023-07-12 15:17:09.042768');
insert into сообщение values (88, 29, 'консультант', $$То есть он решил оскорбить всех ее обитателей – Вижу, – покривил Артур душой Свет солнца ударил в глаза Форду с Артуром, когда те, жмурясь, вышли из буфета и огляделись по сторонам$$, '2023-07-14 05:43:04.673605');
insert into сообщение values (89, 29, 'консультант', $$За исключением одного случая Они бежали, не разбирая дороги, через траву, подпрыгивали, хохотали, кричали друг другу: «Загоняй его сюда!», «Перехватывай!» Солнце мечтательно освещало травяное море, крохотные полевые животные сломя голову разбегались из-под их ног Они стояли одни-одинешеньки на вершине утеса где-то на доисторической Земле и решительно смотрели друг другу в глаза Также там советовалось заглянуть в главу о необозримости Вселенной и методике примирения с этим фактом$$, '2023-07-14 11:54:45.514558');
insert into сообщение values (90, 29, 'клиент', $$– А мне можно с вами?

– Нет, – сказал робот – Все последние пять лет приснились мне во сне – Я сойду с ума! – возгласил он$$, '2023-07-13 07:23:42.894256');
insert into сообщение values (91, 30, 'клиент', $$Слепящий свет, подобно цунами, захлестнул мрак и откатился, унося с собой большой кусок планеты, что висела прямо под их ногами Им составляли компанию недоеденные ломти хлеба и недопитые бокалы вина Неся в руках поднос с ужином, она вошла к Зафоду и спросила, нет ли у него желания поговорить$$, '2023-05-24 21:28:14.409792');
insert into сообщение values (92, 30, 'клиент', $$– Ты слишком много пьешь, – сказала Триллиан Но в общем и целом они смотрелись довольно приятно Зафод ошарашенно разглядывал роботов Форд и Артур прикинулись, будто ничего не замечают$$, '2023-05-23 10:53:30.093912');
insert into сообщение values (93, 30, 'консультант', $$Широко развел руки – … нестабильности… – завершил Форд Я не шучу – Я сойду с ума! – возгласил он$$, '2023-05-24 18:22:14.545080');
insert into сообщение values (94, 30, 'консультант', $$– Вон там, – повторил он А на скатерти пребывало с полдюжины тарелок с недоеденными итальянскими кушаньями Видение состроило нечто вроде ехидной ухмылки – впрочем, еще неизвестно, насколько ехидной, ибо солнце, светя ему прямо в затылок, соорудило из его серебристых волос и бороды ослепительный, драматический, повергающий в трепет нимб, с которым никакие ехидные ухмылки не вязались$$, '2023-05-23 11:14:45.670463');
insert into сообщение values (95, 31, 'клиент', $$– Фгм, – произнес робот и вернулся к своему занятию, а именно очень медленному хождению по очень маленькому кругу – Не лучшее его место Собрав все силы, он выпрямил свое длинное тело, встал на дыбы и несколько секунд простоял на цыпочках, вглядываясь в туман – … только что материализовались тут у нас, посреди крикетной площадки «Лордз»$$, '2024-01-25 23:17:53.396277');
insert into сообщение values (96, 31, 'клиент', $$На секунду-другую лицо Артура застыло, как маска, а потом стало с ужасающей медлительностью раскалываться на куски, точно арктические льдины по весне$$, '2024-01-23 22:13:05.109445');
insert into сообщение values (97, 32, 'консультант', $$– Роботы, – поправил себя Зафод, – что вы, роботы, тут делаете?

– Мы пришли, – прохрипел робот, – за Золотом Перекладины И перевел взгляд на чудо творения за иллюминатором$$, '2023-09-05 03:01:53.444469');
insert into сообщение values (98, 32, 'клиент', $$Чисто инопланетная долговязость, чисто инопланетная приплюснутая голова, чисто инопланетные глазки-щелочки, экстравагантно-складчатое золотое одеяние с воротником чисто инопланетного покроя и бледная, серо-зеленая инопланетная кожа, сияющая тем особым блеском, который дается большинству серозеленоликих субъектов лишь благодаря постоянному массажу и самому дорогостоящему мылу Свет он выключил, чтобы его головы не видели друг дружку, поскольку обе выглядели довольно погано – с самого того момента, когда Зафод сдуру заглянул к себе в душу Безусловно, вся земная медицина была уже не в силах его спасти$$, '2023-09-02 22:41:33.805991');
insert into сообщение values (99, 33, 'клиент', $$Корабль пересекал орбиты планет Солнечной системы, намереваясь совершить пертурбационный маневр вокруг Солнца и, разогнавшись, выскочить в большой космос Мелкие подробности аварии не имеют значения, поскольку никому так и не удалось воспроизвести обстоятельства произошедшего, причем многие экспериментаторы при этом попали либо в дурацкое положение, либо на тот свет, либо и туда, и туда одновременно – Протечки?

– Протечки в пространстве-времени, – сказал Форд и поспешил подставить свое зверски ухмыляющееся лицо ветру, который как раз случайно пролетал мимо$$, '2023-10-23 10:17:56.236336');
insert into сообщение values (100, 33, 'консультант', $$Это последнее он совершал с большой плучительностью Созерцая тускло-розовый контур двери, он осознал, что во мраке коридора еле-еле различаются границы сенсорно-тактичного поля, которое и предупреждало дверь о появлении кого-то, перед кем следует раскрыться с любезными словами Однако спустя миг стряслось нечто, чего невозможно было не заметить$$, '2023-10-23 09:34:46.240402');
insert into сообщение values (101, 33, 'клиент', $$Ни одного матрасса это, по-видимому, не удручает – Мне довелось побыть знаменитостью, – скорбно завывал робот, – совсем недолго благодаря моему чудесному и весьма досадному спасению от удела, сравнимого разве что с такой удачей, как гибель в сердце пылающей звезды Также вы научитесь правильно приземляться – сразу предупредим, что первая попытка выйдет большущим комом – Диван исчез$$, '2023-10-23 04:07:09.519410');
insert into сообщение values (102, 34, 'консультант', $$– Что вы сказали? – пробормотало ошарашенное полисменообразное Внутри царила историческая тишина Большую часть всех абсурдных вещей, какие приходили ему в голову, он уже повидал наяву$$, '2023-12-24 08:40:30.439062');
insert into сообщение values (103, 34, 'консультант', $$В этот момент Артур заметил странную особенность песни, которую распевали криккитяне – Твои идеи – мои идеи, – согласился Зафод$$, '2023-12-26 17:18:48.197250');
insert into сообщение values (104, 35, 'клиент', $$– Еще миллион лет, – заявил Марвин, – еще миллиончик Вероятно, людей обуяла коллективная мысль «Ну и дела!», сопровождаемая единодушным чувством недоумения – Ну и хорошо, – сказал Артур Пойдемте за ними и посмотрим сами$$, '2023-09-12 20:53:52.200436');
insert into сообщение values (105, 35, 'консультант', $$– Мы уже установили, что оно не мое Бистроматическая тяга – это чудесный новый способ преодоления необъятных космических расстояний без необходимости затевать опасный флирт со всякими там факторами невероятности – Собственно, невозможность их формулирования и есть один из самих этих принципов – Я думал, ты умер… – вырвалось у него$$, '2023-09-14 14:16:32.354789');
insert into сообщение values (106, 36, 'консультант', $$К счастью, таких тут хватало$$, '2023-09-13 00:00:22.023634');
insert into сообщение values (107, 36, 'консультант', $$Он с грохотом понесся по небу, словно точно знал, что делает Он одновременно казался твердым, как деревья, и бесплотным, как сон русалки Неслышно появилась узенькая серебряная каемка ранней зари$$, '2023-09-14 07:05:26.442548');
insert into сообщение values (108, 36, 'клиент', $$Он тряс руку Форда и пожимал ее, пожимал и тряс$$, '2023-09-12 18:26:50.310378');
insert into сообщение values (109, 36, 'консультант', $$Осмелюсь признаться, я питаю некоторую слабость к крикету, хотя я не хотел бы, чтобы о ней знали за пределами этой планеты$$, '2023-09-14 00:08:50.200465');
insert into сообщение values (110, 37, 'консультант', $$И может статься, приведет к безвременной гибели всю Вселенную «Трень-сдззз…» – корабль взлетел$$, '2024-04-10 04:33:58.223670');
insert into сообщение values (111, 37, 'консультант', $$В матче$$, '2024-04-06 23:16:49.043791');
insert into сообщение values (112, 38, 'клиент', $$– Не слишком похоже на наш случай – Я к этой фигне не шел$$, '2023-08-17 07:38:46.324617');
insert into сообщение values (113, 38, 'клиент', $$А потом и ничто, что находилось позади тьмы позади Вселенной, тоже раскололось вдребезги, а за этим ничто позади тьмы позади расколошмаченной Вселенной возникла черная фигура человека-исполина, который произносил исполинские слова$$, '2023-08-16 03:38:39.090304');
insert into сообщение values (114, 38, 'консультант', $$Понимаете, мысль «Мы одни во Вселенной» их ни разу не посещала, потому что до сегодняшнего вечера они вообще не знали о существовании Вселенной$$, '2023-08-17 03:45:38.852030');
insert into сообщение values (115, 38, 'клиент', $$А там происходило всего лишь то, что люди столпились на площадке вокруг ее середины$$, '2023-08-16 04:23:53.170559');
insert into сообщение values (116, 39, 'консультант', $$У меня самый классный корабль во всем известном небе, девушка, с которой у меня все чудесно…

– Да?

– Ну, насколько я понимаю – Ау, компьютер! – прошептал он Спустя четырнадцать часов солнце хмуро опустилось за противоположный горизонт с чувством зазря потраченного труда – Подождите минутку! Что вы хотели? Эй! Да подождите же!

Корабль приподнялся, беспечно скинув свою тяжесть наземь, будто плащ, секунду повисел в воздухе – и унесся в вечернее небо$$, '2023-09-03 14:28:49.961010');
insert into сообщение values (117, 39, 'консультант', $$Что Слартибартфаст в этом нашел такого интересного, ведал он один – Я тут тоже спрыгнул с ума на время, – заявил Форд$$, '2023-09-03 11:06:49.631293');
insert into сообщение values (118, 40, 'консультант', $$– Я этот номер уже видел, – проговорил он$$, '2024-08-29 21:20:55.832341');
insert into сообщение values (119, 40, 'консультант', $$– И также я тебя прошу не говорить, что ты очень рада быть полезной или что ты польщена честью раскрыться передо мной и премного довольна вновь затвориться с сознанием выполненного долга, ладно?

– Ладно Выдвинулись длинные опоры, совершая изящные балетные па во славу технического прогресса Меня заставляли сидеть на ящике и рассказывать мою историю, а зрители уговаривали меня приободриться и мыслить позитивно$$, '2024-08-30 22:58:12.405818');
insert into сообщение values (120, 41, 'консультант', $$– И поперхнулся чаем А также флёпал, гумкал и уйломикивал Похоже, на них восседали не то девушки, не то ангелы – Привет, землянин, – ответил Слартибартфаст$$, '2023-09-26 13:49:28.873215');
insert into сообщение values (121, 41, 'консультант', $$– Золотая Перекладина – это часть Ключа, который мы ищем, – продолжал робот, – чтобы освободить наших Повелителей с Криккита Всеми фибрами своего пружинного сознания матрасс чувствовал, что робот горячо мечтает, чтобы его спросили, давно ли он совершает это бесплодное и бессмысленное топтание Болтайтесь над землей и парите, парите и болтайтесь А это другое$$, '2023-09-27 06:02:27.337165');
insert into сообщение values (122, 41, 'клиент', $$– Должно быть, она тебе донельзя обрыдла Он сидел в своей пещере, составлял каталог возможных отповедей наглому инопланетянину и давил мух – для них этот вечер тоже оказался кошмарным Мне это кажется чрезвычайно странным, тем более что сумку я сшил на доисторической Земле своими руками Пространство не просто изменило текстуру и состав$$, '2023-09-25 22:54:56.368632');
insert into сообщение values (123, 41, 'консультант', $$– А, ну и ладно, – промолвил Артур с облегчением$$, '2023-09-27 07:19:50.555555');
insert into сообщение values (124, 42, 'консультант', $$Холод, тяжесть, беспросветность потихоньку проникли в сердце Артура, и он остро ощутил переживания пилотов-криккитян, повисшие в воздухе кабины, точно грозовое электричество Некоторое время все молчали, из чего Зафод заключил, что роботы явились сюда не для разговоров и дело за ним – На мой взгляд, – сказал матрасс, сочувственно рассматривая вышеуказанную конечность, – это не такая уж замечательная нога Приборы, столь занимавшие внимание Слартибартфаста, были вмонтированы в донца бутылок, которые, в свою очередь, были заделаны в бетонную стену$$, '2024-04-12 17:26:51.070230');
insert into сообщение values (125, 42, 'консультант', $$Он осознал, что удостоился знакомства с носителем незаурядного ума Из всех цивилизаций и племен Галактики только англичане могли воскресить воспоминание о самых ужасных войнах в истории Вселенной и превратить его в чрезвычайно замысловатую, нудную и бесцельную игру Аналогично последовательность отдельных впечатлений сливалась тут в единое чувство – хотя на чувство оно как-то не походило$$, '2024-04-12 04:31:35.388244');
insert into сообщение values (126, 43, 'консультант', $$Куда пожелаю, туда и полечу, что на ум взбредет, то и выкину Ширится мнение, что «Максимегалонский словарь» не заслуживает целого полка грузовиков, который используется для транспортировки его микрофильмированной версии$$, '2023-09-25 14:04:23.429160');
insert into сообщение values (127, 43, 'клиент', $$Он чуть не взлел со страху А эта была не хуже прочих Вероятно, людей обуяла коллективная мысль «Ну и дела!», сопровождаемая единодушным чувством недоумения$$, '2023-09-25 17:12:53.275842');
insert into сообщение values (128, 44, 'консультант', $$– Э-э, пять, – сказал матрасс$$, '2023-08-30 13:43:56.378901');
insert into сообщение values (129, 44, 'клиент', $$– Поймать? – пробормотал Артур и тут же вытаращил глаза – диван, вальяжно покачиваясь, уплывал в глубь поля Между мигом, когда криккитяне впервые узнали о существовании космоса как такового, и запуском этой первой ласточки среди космических кораблей прошел ровно год$$, '2023-08-30 22:12:15.533350');
insert into сообщение values (130, 44, 'клиент', $$А на скатерти пребывало с полдюжины тарелок с недоеденными итальянскими кушаньями Дело есть Периодически в головокружительном мельтешении событий они выделяли, скорее чутьем, чем зрением, ужасные катастрофы, кошмарные преступления, катаклизмы, и всегда они были связаны с определенными, вновь и вновь возникающими образами – единственными, которые ясно выступали из беспорядочной лавины исторических фактов: крикетная калитка, твердый красный мячик, беспощадные белые роботы, а также нечто смутное – что-то темное, закрытое облаками После нескольких удачных проб вы обнаружите, что отвлечься становится все проще и проще$$, '2023-09-01 09:14:56.318405');
insert into сообщение values (131, 45, 'клиент', $$– Странное это дело, – тихо проговорил Артур, – чем быстрее и дальше путешествуешь по Галактике, тем менее важным кажется твое местоположение в ней, и тебя охватывает глубокое, точнее, опустелое чувство… этого самого…

– Да, очень странно, – согласился Форд И не потому, что звездолет был невидим – … нестабильности… – завершил Форд$$, '2024-10-03 01:44:58.026752');
insert into сообщение values (132, 45, 'клиент', $$И ухмыльнулся с хорошо рассчитанной издевкой$$, '2024-09-28 07:50:22.205581');
insert into сообщение values (133, 46, 'консультант', $$Он решил оскорбить Вселенную$$, '2023-12-12 00:15:26.939692');
insert into сообщение values (134, 46, 'консультант', $$Форд злобно обернулся к Артуру Тут Артура посетила некая неясная догадка относительно смысла представшего перед ним зрелища, но он поспешил ее отбросить – Уф, нащупал, – сообщил он$$, '2023-12-11 21:28:06.508456');
insert into сообщение values (135, 46, 'консультант', $$– Полотенце не мое, – настаивал Артур, – именно это я и пытаюсь…

– А я пытаюсь потребовать, чтобы ты заткнулся, – продолжал Форд, переходя на рык, – причем немедленно!

– Ладно, – сказал Артур, пытаясь засунуть полотенце обратно в свою неуклюжую сумку В вечерней тиши они стояли на вершине холма Когда ее находят, то выкидывают на помойку$$, '2023-12-09 06:44:41.157510');
insert into сообщение values (136, 47, 'клиент', $$Куда пожелаю, туда и полечу, что на ум взбредет, то и выкину И все же что было, тому не миновать$$, '2023-09-24 02:29:39.803214');
insert into сообщение values (137, 47, 'консультант', $$– Это только документальный фильм, – вскричал он К сожалению, именно терминалы рубки Зафод и заткнул кляпом После фантасмагорического балагана «основного вычислительного центра» Зал информационных иллюзий был настоящим отдохновением для глаз Не характерное для дверной речи выражение$$, '2023-09-24 08:53:38.286862');
insert into сообщение values (138, 48, 'консультант', $$Конкретно – всего лишь одну ноту, повторяющуюся через определенные интервалы А потом все завершилось – так же внезапно, как и началось Он понятия не имел, куда клонит Форд, но по крайней мере инцидент казался исчерпанным$$, '2023-11-20 05:58:31.905368');
insert into сообщение values (139, 48, 'консультант', $$Сияющее облако булавок и иголок на знойно-черном бархате открытого космоса – Ч… ч… ч… – выговорили его губы – Ммммм?

– Когда я выну у тебя кляп…

– Ммммм – Ты наверняка знаешь, что сейчас произойдет, – сказал Слартибартфаст Форду$$, '2023-11-18 13:33:04.908728');
insert into сообщение values (140, 48, 'клиент', $$В вечерней тиши они стояли на вершине холма$$, '2023-11-20 20:30:15.493249');
insert into сообщение values (141, 48, 'клиент', $$Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина$$, '2023-11-20 06:48:52.934968');
insert into сообщение values (142, 49, 'клиент', $$Вот он я, Зафод Библброкс – И, – продолжал громоподобный голос, – Деревянный Столб – символ, – здесь бас слегка осип от избытка умиления, – могущества Природы и Духовности!

Лучи переместились на центральный столб$$, '2024-11-01 20:09:30.945754');
insert into сообщение values (143, 49, 'клиент', $$Не бросай трубку Робот-официант, робот-буфетчик и робот-метрдотель обслуживали роботов-клиентов$$, '2024-11-04 19:31:15.944332');
insert into сообщение values (144, 50, 'консультант', $$Итак, Охмешконасыпатель пресытился жизнью А ведь Зафод был на борту один Венских$$, '2024-03-30 02:18:28.883297');
insert into сообщение values (145, 50, 'клиент', $$– А это что?

– Не Наша Проблема – …ты прыгал и…

– Ну да В висках у Артура раздался привычный тупой звон, очень часто сопровождавший его разговоры с Фордом – Видимо, вы поглощены размышлениями, – плучительно сказал матрасс$$, '2024-03-29 13:33:48.279523');
insert into сообщение values (146, 50, 'клиент', $$– Повелители Криккита, – выдохнул Слартибартфаст голосом призрака Это крикетный приз Они уселись на камень и впали в глубокую задумчивость Но никто этого не спрашивал, и Форд злился$$, '2024-03-28 21:43:38.385581');
insert into сообщение values (147, 51, 'консультант', $$– Приятных сновидений, – сказал он – Три столба, – гремел мужчина – Надеюсь, куда-нибудь, где солнышко светит, – проговорил Форд Самый подходящий афоризм, чтобы заронить в молодые умы искру вдумчивого отношения к жизни$$, '2023-11-06 23:02:41.007884');
insert into сообщение values (148, 51, 'консультант', $$Одиннадцать белых роботов, тесно сгрудясь, вознеслись сквозь редеющее облако и, напоследок плюнув пламенем, скрылись в животе своего белого корабля, который с кратким ропотом (будто сотня тысяч людей вымолвила: «Фу!») немедленно растворился в том же воздухе, из которого раньше сгустился Артур попросил его повторить только что сказанную фразу, ибо не совсем уяснил себе ее смысл$$, '2023-11-08 00:47:53.876438');
insert into сообщение values (149, 51, 'консультант', $$– Ммммм ммммы?

– Все равно, какой головы Причем наутро участники напрочь забывали о произошедшем$$, '2023-11-08 07:37:11.318318');
insert into сообщение values (150, 52, 'консультант', $$Артур поднял глаза$$, '2023-07-13 04:54:50.159317');
insert into сообщение values (151, 52, 'клиент', $$Между мигом, когда криккитяне впервые узнали о существовании космоса как такового, и запуском этой первой ласточки среди космических кораблей прошел ровно год Но тут же просияв, перевел взгляд на широкий экран панорамного обзора, где струились, головокружительно сплетаясь и расплетаясь вокруг корабля, серебряные нити – Мне много не надо, – кричал Форд в уточнение своих предыдущих замечаний, – только рюмка крепкого виски и компания братьев по духу!

Он несся, как лань, замешкавшись лишь на миг, чтобы взять на буксир Артура, который среагировал было на катастрофу в своем обычном духе – замер с открытым ртом, ожидая, пока все кончится$$, '2023-07-13 08:32:45.082037');
insert into сообщение values (152, 52, 'клиент', $$В его голове родился целый рой глубокомысленных вопросов$$, '2023-07-12 22:14:16.041263');
insert into сообщение values (153, 52, 'консультант', $$Вначале он казался слишком голым, слишком безумным, слишком похожим на те, о которых человек с улицы сказал бы: «Ну как же, я и сам до этого давно уже додумался» – Я так, просто напомнить хотел, – сказал Форд В их штате есть специальные работники с удивительными телами и воззрениями$$, '2023-07-13 16:46:22.891412');
insert into сообщение values (154, 53, 'клиент', $$– Ликвидация, – сказал он$$, '2023-12-31 19:14:55.132440');
insert into сообщение values (155, 53, 'консультант', $$Умопомрачительно красивый, уникально огромный и к тому же самый уютный корабль в истории Галактики (точнее, в нынешней, сильно обкарнанной опровержениями версии этой самой истории – подробности см Артур встал$$, '2023-12-31 02:14:16.623180');
insert into сообщение values (156, 53, 'консультант', $$– Тс-с, – вновь прошипел Форд Проведя рукой по стене, он нащупал нечто ценное Нападающий приближался к калитке, плавно переходя с рысцы на бег[2] Дверь тихо отъехала в сторону$$, '2023-12-31 21:38:20.342680');
insert into сообщение values (157, 53, 'консультант', $$– Я изумлен, – сказал Артур, – и потрясен Понимаете, мысль «Мы одни во Вселенной» их ни разу не посещала, потому что до сегодняшнего вечера они вообще не знали о существовании Вселенной Несмотря на кучи обломков, Зафод с новым ужасом разглядел, что они движутся к самому ядру корабля, сердцу невероятностной тяги, загадочным образом сгущаемой из пустоты, – в общем, к самому «Золотому сердцу» Я сказал: «Я хотел бы сказать, что выступить на открытии этого моста для меня большая честь, радость и удача, но не могу – все мои цепи лжи вышли из строя$$, '2023-12-31 18:51:31.674987');
insert into сообщение values (158, 54, 'консультант', $$Сегодняшнее утро выдалось благоуханным и ясным – в чем лично удостоверился Артур Дент, выйдя из пещеры, которую именовал домом (за неимением как более подходящего названия для нее, так и более подходящей для этого названия пещеры) По-видимому, этот разговор действовал ему на эквивалент нервов$$, '2023-07-23 14:18:17.425931');
insert into сообщение values (159, 54, 'консультант', $$Кое-кто с придыханием произносит имя «Золотое сердце», другие благоговейно повествуют о «Бистроматолете» Следовательно, они сохранят у себя Пепел$$, '2023-07-24 03:12:18.210140');
insert into сообщение values (160, 54, 'клиент', $$– Четвертая планета системы Фольфанга, – продолжил он Древнее Зло встало из могилы Уперев руки в бока, он вновь обвел взором пустынный мир Слартибартфаст уверил его, что полет состоится, что они в полной безопасности, что их ожидает крайне поучительное, хоть и довольно мучительное зрелище$$, '2023-07-23 20:55:38.725136');
insert into сообщение values (161, 54, 'консультант', $$– Н?

– … НП Проведя рукой по стене, он нащупал нечто ценное$$, '2023-07-23 02:54:49.951917');
insert into сообщение values (162, 55, 'клиент', $$Поддельные бутылки в поддельном бетоне – Сходить с ума, так сходить, – рассудил Форд Что ни говори, а Криккит казался приятным во всех отношениях местечком И вправду – к его радости и изумлению, с небес, рассекая теплый вечерний воздух, тихо, как-то интеллигентно спустился длинный серебряный звездолет$$, '2023-09-29 01:06:49.521099');
insert into сообщение values (163, 55, 'клиент', $$– Онизапелибрепел! – вскричал Слартибартфаст своим тонким, дребезжащим голосом – Оно имеет, – прошептал он Форду, серьезно наморщив лоб, – форму полисмена$$, '2023-09-28 07:04:47.998136');
insert into сообщение values (164, 55, 'консультант', $$– Ага, чтоб ты его опять выбросил?

– Разумно, – сознался Артур – Мне довелось побыть знаменитостью, – скорбно завывал робот, – совсем недолго благодаря моему чудесному и весьма досадному спасению от удела, сравнимого разве что с такой удачей, как гибель в сердце пылающей звезды$$, '2023-09-28 09:40:28.964827');
insert into сообщение values (165, 56, 'консультант', $$Слартибартфаст шевелил губами, точно размышляя над орфографией какого-то слова Она услышала, как Зафод топочет и насвистывает где-то в недрах корабля Форд сгреб его за отвороты халата и стал объяснять ему терпеливо и размеренно, с толком и с расстановкой – словом, так, будто Артур был служащим расчетного отдела телефонной компании Спустя некоторое время он начал медленно, воровато пробираться вперед с гримасой вдумчивой озадаченности на лице – как леопард, который не совсем уверен, что только что видел в полумиле впереди, на раскаленной и пыльной прерии, полупустую банку «Вискаса»$$, '2024-01-19 20:26:22.256067');
insert into сообщение values (166, 56, 'консультант', $$Произошла настоящая революция$$, '2024-01-18 23:05:55.461545');
insert into сообщение values (167, 57, 'консультант', $$Он мягко приземлился Форд только покачал головой Второе не-абсолютное число – это оговоренный час сбора приглашенных, который, как ныне известно, представляет собой одно из сложнейших математических понятий – реситуасексулузон, число, о котором с уверенностью можно сказать лишь одно – оно равно чему угодно, только не самому себе$$, '2023-07-18 08:50:29.706855');
insert into сообщение values (168, 57, 'клиент', $$Затем вы освоите массу приемов по управлению своим телом в полете, регулировке скорости, выполнению маневров$$, '2023-07-17 21:19:42.002720');
insert into сообщение values (169, 57, 'консультант', $$– Что он сказал? – с трудом вымолвил Форд, работая локтями$$, '2023-07-18 09:56:09.381785');
insert into сообщение values (170, 57, 'клиент', $$Проведя рукой по стене, он нащупал нечто ценное Он задумчиво уставился вдаль – Эксцентрика Гамбитус, ты ее когда-нибудь видел? Троегрудая путана с Эротикона-6 Мозг Артура совершил сальто-мортале внутри черепной коробки$$, '2023-07-19 04:02:34.950042');
insert into сообщение values (171, 58, 'консультант', $$Неслышно появилась узенькая серебряная каемка ранней зари$$, '2023-10-18 04:25:15.106000');
insert into сообщение values (172, 58, 'консультант', $$Форд что-то мурлыкал под нос Полисмен развернулся и побрел искать кого-нибудь, кто был бы не с Бетельгейзе Надежда и ликование в душе Артура вмиг сменились чувством крайней озадаченности$$, '2023-10-17 12:43:07.387425');
insert into сообщение values (173, 58, 'клиент', $$Вот уже пять лет, как его не расщепляли на атомы – Еще миллион лет, – заявил Марвин, – еще миллиончик Будь у него зубы, он скрипел бы ими Один мальчишка озадаченно посмотрел на него:

– У вас все в норме?

– Нет$$, '2023-10-19 06:00:03.386188');
insert into сообщение values (174, 58, 'клиент', $$– Ага, чтоб ты его опять выбросил?

– Разумно, – сознался Артур$$, '2023-10-18 13:56:05.242525');
insert into сообщение values (175, 59, 'клиент', $$И все же, рассудил Артур, это дело привычки – Я столько лет никого не видел, – заговорил он, – просто ни единой души Они пытались их игнорировать, но все же не могли не заметить, что Слартибартфаст сварливо требует, чтобы серебряную урну с «Пеплом» отдали ему, ибо тот, по его словам, «жизненно важен для прошлого, настоящего и будущего Галактики», и что это заявление вызвало бурное веселье Выдвинулись длинные опоры, совершая изящные балетные па во славу технического прогресса$$, '2023-07-17 22:46:51.206390');
insert into сообщение values (176, 59, 'клиент', $$Почему вы ходите кругами?

– Потому что у меня нога завязла, – сказал Марвин без обиняков Дверь тихо закрылась за ним История собиралась с силами, чтобы нанести криккитянам новый удар Вспыхнули споры, посетители кинулись рисовать на салфетках иллюстрации своей правоты$$, '2023-07-18 02:12:38.519072');
insert into сообщение values (177, 59, 'консультант', $$В наше время мало что производится на фабриках, поскольку в бесконечно огромной Вселенной – например в нашей – большинство вещей и предметов, какие только может вообразить человек (а также масса абсолютно невообразимых), где-нибудь да произрастает само А ведь Зафод был на борту один Вскоре стали различимы и звуки, а затем стало понятно, что это маленькая кучка людей, и держат они путь домой, в город Артур хмуро поплелся за ним$$, '2023-07-17 18:07:39.841668');
insert into сообщение values (178, 59, 'консультант', $$– Я обнаружил, – заявил он, – аномальные протечки Но зубы ему не требовались$$, '2023-07-17 19:26:32.409434');
insert into сообщение values (179, 60, 'клиент', $$– Дайте мне формы и контуры После сбора ее следует положить в темный пыльный ящик и не трогать много лет$$, '2023-07-13 08:50:45.444191');
insert into сообщение values (180, 60, 'клиент', $$Безусловно, вся земная медицина была уже не в силах его спасти Но тут синее полисменообразное нечто тронуло их обоих за плечи$$, '2023-07-13 20:58:28.155152');
insert into сообщение values (181, 60, 'клиент', $$Ветерок приносил оттуда мирные бытовые звуки Триллиан была очарована прочитанным, но скрепя сердце решила, что Зафоду с его нынешним настроением лучше и не мечтать ни об уроках летания, ни о хождении пешком по горам, ни о борьбе с Брантивортигорнским Государственным Управлением за признание законным свидетельства о переезде – все эти занятия были перечислены под заголовком: «Досуг в мире несбыточного» – Я вам расскажу$$, '2023-07-14 08:40:34.570822');
insert into сообщение values (182, 60, 'клиент', $$– Артур! – заорал на него Форд И это где-то недалеко$$, '2023-07-13 02:55:11.925583');
insert into сообщение values (183, 61, 'клиент', $$– Приятных сновидений, – сказал он В ней стоял стол$$, '2024-09-12 20:47:49.293639');
insert into сообщение values (184, 61, 'клиент', $$В каждом рассвете есть миг, когда свет не льется вниз, а парит, миг, когда возможно чудо Она была безлична – не как неизвестно чей злобный вопль в толпе, но как отпечатанный на принтере квиток за неправильную парковку$$, '2024-09-12 10:15:57.324360');
insert into сообщение values (185, 62, 'консультант', $$Артур поднял глаза Она была срежиссирована скорее для блага телезрителей, чем просто зрителей, и со своего места в толпе они могли следить за ней только по сообщениям ближайшего репродуктора Тело Артура безвольно плюхнулось обратно на траву И потому вскорости они оказались у внутренней границы сферического, полого изнутри Пылевого Облака, со всех сторон окружавшего Криккит и его солнце$$, '2024-06-20 05:37:37.868781');
insert into сообщение values (186, 62, 'консультант', $$– Ну там, вогоны не заворачивают краны…

– Нет, это возмущения в континууме, – пояснил Форд При этих словах Артура точно пчела ужалила$$, '2024-06-20 07:29:40.186577');
insert into сообщение values (187, 62, 'клиент', $$– Нет смысла ломать голову над действиями машин, – заявил он, – только зря нервничаешь Если последовательность размеренных щелчков, записанную на пленку, прокручивать с ускорением, одиночные щелчки постепенно сольются в постоянный, повышающийся тон Другой суперсенсацией тогдашней прессы стала вспышка сверхновой звезды, в которую несколько часов спустя превратилась звезда Неавоось Лед тронулся$$, '2024-06-21 01:42:43.550303');
insert into сообщение values (188, 63, 'клиент', $$Солнце нехотя попыталось одолеть туман, пробуя то тут добавить немножко тепла, то вон туда запустить несколько лучиков, но, судя по всему, сегодня его ожидала очередная тягомотная прогулка от горизонта до горизонта Сквозь мрак виднелись лишь огни ближнего городка Они стояли неподвижно Артур последовал совету, вначале несколько нервно, словно боясь, что рука сейчас обернется скользкой рыбиной$$, '2023-08-01 05:38:34.791726');
insert into сообщение values (189, 63, 'консультант', $$С легким жужжанием и крайне зловещим видом он завис над землей Я считаю, что в пяти Первый комментатор призадумался Ах, как прекрасен – аж глазам больно – был «Звездный Титаник», когда, точно арктурианский мегавакуумный серебристый кит, он качался в лазерных тенетах гибких строительных лесов$$, '2023-08-01 19:04:18.870852');
insert into сообщение values (190, 63, 'клиент', $$Это они шли в тот вечер по тропе, распевая мелодичные, проникновенные песни$$, '2023-08-01 20:46:16.638789');
insert into сообщение values (191, 63, 'клиент', $$Крикетный мяч, встреченный с таким восторгом, свалился с небес прямо в загадочную кроличью сумку Артура – Какой формы? – вопросил Форд Зачем это понадобилось притаскивать сюда сто тысяч человек ради такой ерунды?

Он нервно двинулся в сторону рубки Довольные улыбки, которыми он обычно озарял чужие похороны, стали какими-то натянутыми$$, '2023-07-31 23:34:09.254196');
insert into сообщение values (192, 64, 'консультант', $$Видение дергалось и колебалось перед глазами Артура, хотя, видимо, в действительности это глаза Артура дергались вместе с головой Он прошел к зеленой винтовой лестнице из кованого железа, непонятно зачем помещенной в середине рубки, и начал всходить по ней – Я дома, – шептал Артур Авария инопланетного звездолета сдвинула какие-то шарики в их головах$$, '2023-11-02 13:53:59.231108');
insert into сообщение values (193, 64, 'консультант', $$– Порядок, – ответил он бодро, – ужас как хорошо$$, '2023-11-02 21:13:59.186431');
insert into сообщение values (194, 64, 'клиент', $$К сожалению, именно терминалы рубки Зафод и заткнул кляпом – Я дома, – хрипло буркнул Артур$$, '2023-11-01 13:50:31.755716');
insert into сообщение values (195, 65, 'консультант', $$Он только пялился на нее – ему еще не доводилось видеть девушку, способную сидеть на коленях у себя самой Диван все время заваливался то на один, то на другой бок$$, '2024-02-02 22:31:07.008336');
insert into сообщение values (196, 65, 'клиент', $$– Теперь понял?

– Нет, – признался Артур Он вскочил на ноги, точно услышавший телефонный звонок писатель, и обвел ошалелым взглядом окрестный пейзаж, внезапно сложившийся в удивительно привычную картину – Нынче тут, завтра там и кое-где еще, – сообщил Форд$$, '2024-02-02 06:45:47.946327');
insert into сообщение values (197, 66, 'клиент', $$Может, там находится другая планета – ох, как трудно далось это предположение самозамкнутым умам сынов Криккита с его глухой стеной вместо неба – Свобода, – произнес он вслух – Вон за тем диваном!

Артур взглянул в указанную сторону$$, '2023-09-19 20:16:40.324113');
insert into сообщение values (198, 66, 'консультант', $$Его челюсти начали делать отжимания$$, '2023-09-20 06:07:47.685649');
insert into сообщение values (199, 66, 'клиент', $$– Я думал, ты сказал, что это не наша проблема – Да-да, хорошо, это не обязательно, – поспешно заявил полисмен, – только постарайтесь, чтобы такого… этого… больше не было – Что я и ожидал услышать, – продолжил Марвин, – а также я ожидаю узнать, что идея робота с искусственной ногой вас немало забавляет Мало того, нижние сегменты их ног были защищены чем-то вроде белых щитков$$, '2023-09-20 23:46:04.898686');
insert into сообщение values (200, 67, 'клиент', $$Вот он я, Зафод Библброкс Многие из них попадаются в силки охотников, после чего их убивают, высушивают, экспортируют и кладут на кровати, чтобы люди на них спали От вас требуется одно – решительно кинуться вниз, не боясь ожидающей вас физической боли$$, '2024-02-19 17:27:02.897479');
insert into сообщение values (201, 67, 'консультант', $$Время – это, так сказать, худшее место из всех, где только можно заблудиться Ему почудилось, будто атомы его мозга и атомы космоса струятся друг сквозь друга – Никчемная дырка от бублика$$, '2024-02-19 04:39:23.490039');
insert into сообщение values (202, 67, 'клиент', $$Грязно-розовое небо померкло, посинело, вновь окуталось мраком$$, '2024-02-19 02:18:04.893777');
insert into сообщение values (203, 68, 'консультант', $$Слепящий свет, подобно цунами, захлестнул мрак и откатился, унося с собой большой кусок планеты, что висела прямо под их ногами В нем не было ничего И может статься, приведет к безвременной гибели всю Вселенную$$, '2024-10-08 09:23:47.976327');
insert into сообщение values (204, 68, 'консультант', $$Старец ответил не сразу Он таил надежду, что кто-нибудь спросит: «Что это ты мурлычешь?» – но никто не спрашивал Артур кивнул – медленно, опасливо, с безмерно дурацким выражением лица$$, '2024-10-08 02:51:52.391680');
insert into сообщение values (205, 68, 'клиент', $$Широко развел руки Также никому не известно, что за радость находят в своем образе жизни матрассы Слартибартфаст уверил его, что полет состоится, что они в полной безопасности, что их ожидает крайне поучительное, хоть и довольно мучительное зрелище$$, '2024-10-07 11:36:45.571608');
insert into сообщение values (206, 69, 'клиент', $$– Ты мне не сказал$$, '2023-07-22 01:04:27.470867');
insert into сообщение values (207, 69, 'клиент', $$Приборы, столь занимавшие внимание Слартибартфаста, были вмонтированы в донца бутылок, которые, в свою очередь, были заделаны в бетонную стену Я его в реку выбросил – Мы ищем Ключ, – повторил он, – мы уже владеем Деревянным Столбом, Стальным Столбом и Плексигласовым Столбом Одну голову он засунул под подушку, а вторая до поздней ночи разгадывала кроссворды$$, '2023-07-21 23:42:23.350006');
insert into сообщение values (208, 69, 'клиент', $$– Не могу не отметить того факта, что вы припарковали свой корабль, – сказал он, указав одним из подбородков в соответствующую сторону, – прямо поперек моего Толпа взревела Форд с Артуром так и обмерли, подавившись собственным воплем А потом даже гумкнул от избытка чувств$$, '2023-07-22 01:17:15.480706');
insert into сообщение values (209, 69, 'клиент', $$В нем звучала даже какая-то интеллигентная хрипотца – А-а, – протянул Артур, – так вот почему…

– Ну да, – согласился Форд, зная наперед, что именно Артур скажет Если не считать разговоров с некоторыми дубами – этим хоть в лоб, хоть по лбу По-моему, это было животное из семейства аллигаторов$$, '2023-07-21 22:11:01.935634');
insert into сообщение values (210, 70, 'консультант', $$Музыка бодро штурмовала небесное царство полной несказанности Казалось, его соорудили где-то в сарае – собственно, так оно и было$$, '2024-05-07 13:43:22.718344');
insert into сообщение values (211, 70, 'консультант', $$И только мощность моего блока счастья подкачала – А мне можно с вами?

– Нет, – сказал робот Но не думаю, что с дурными намерениями$$, '2024-05-09 00:35:47.997483');
insert into сообщение values (212, 70, 'клиент', $$Прищурившись, как Клинт Иствуд, он уставился на горизонт Довольные улыбки, которыми он обычно озарял чужие похороны, стали какими-то натянутыми – И плюхнувшись на колени перед Фордом, прошипел: – Это полисмен$$, '2024-05-08 02:56:21.891912');
insert into сообщение values (213, 70, 'консультант', $$Звездолет басовито загудел$$, '2024-05-07 21:02:45.356907');
insert into сообщение values (214, 71, 'консультант', $$– Что они… – переспросил Форд$$, '2024-03-23 03:50:42.757421');
insert into сообщение values (215, 71, 'клиент', $$Меня заставляли сидеть на ящике и рассказывать мою историю, а зрители уговаривали меня приободриться и мыслить позитивно Теперь слышался какой-то негромкий шум, и исходил он определенно из района рубки Маленькие группки монахов, которые взяли за обычай болтаться около крупных научных институтов и петь странные псалмы во имя идеи, что Вселенная – лишь крупица ее собственного воображения, куда-то сгинули после того, как получили от правительства дотацию на организацию уличных представлений Если это и было чувство, то абсолютно бесчувственное$$, '2024-03-22 19:37:11.716688');
insert into сообщение values (216, 72, 'консультант', $$Они пытались их игнорировать, но все же не могли не заметить, что Слартибартфаст сварливо требует, чтобы серебряную урну с «Пеплом» отдали ему, ибо тот, по его словам, «жизненно важен для прошлого, настоящего и будущего Галактики», и что это заявление вызвало бурное веселье Из всех цивилизаций и племен Галактики только англичане могли воскресить воспоминание о самых ужасных войнах в истории Вселенной и превратить его в чрезвычайно замысловатую, нудную и бесцельную игру – Скатертью дорожка, – пробормотал Зафод, перевернулся на другой бок и всю ночь не смыкал глаз$$, '2024-02-24 16:45:26.801132');
insert into сообщение values (217, 72, 'консультант', $$С того дня прошло уже два года – Ага, чтоб ты его опять выбросил?

– Разумно, – сознался Артур$$, '2024-02-25 03:55:38.001862');
insert into сообщение values (218, 72, 'клиент', $$Пристегиваясь ремнями, Форд Префект только возносил хвалу судьбе за то, что это всего лишь безопасная инфоиллюзия Венских Он шествовал к центру поля ужасающе решительной поступью, и его борода, волосы и одеяние развевались по ветру – вылитый Моисей на горе Синай, только в роли Синая сейчас выступала холеная лужайка, а не грозный вулкан в косматом дыму, каким его обычно изображают – Отлично, – проговорил Форд очень тихо$$, '2024-02-26 18:48:20.529692');
insert into сообщение values (219, 73, 'клиент', $$– Мы могли бы побеседовать, – сказал матрасс, – хотите?

Матрасс был крупный, по-видимому, один из лучших в своем роде Даже если ты посмотришь прямо на ННП, то все равно ее не разглядишь – если только не знаешь заранее, как она выглядит$$, '2023-10-04 16:27:26.004278');
insert into сообщение values (220, 73, 'консультант', $$– А-а, – воскликнул он, сосредоточившись на первом попавшемся имени Форд и Артур воззрились на него с крайним удивлением и острым чувством обиды за хороший вкус$$, '2023-10-04 13:21:36.201735');
insert into сообщение values (221, 73, 'консультант', $$Откуда здесь взяться сотне тысяч людей и что они хотели сказать этим своим «Уф!»?

Зафод огляделся по сторонам – то есть взглянул в оба конца коридора$$, '2023-10-04 10:30:12.027517');
insert into сообщение values (222, 74, 'консультант', $$– Ну-ка, улыбочку, усмешечку!» Я разъяснял, что для того, чтобы мое лицо исказила улыбка, нужно отнести его в мастерскую и часа два поработать над ним кувалдой$$, '2023-12-23 12:21:34.847534');
insert into сообщение values (223, 74, 'консультант', $$Мы живем тихой, уединенной жизнью на болоте, радостно флёпаем и влючим, а на сырость смотрим плучительными глазами Единственная надежда – застичь ННП врасплох краешком глаза$$, '2023-12-23 06:52:53.908784');
insert into сообщение values (224, 74, 'клиент', $$– Я только, – продолжил Слартибартфаст со вздохом, – я только хотел упредить ваш вопрос и заранее пояснить, почему на моем корабле все вычисления производятся в блокноте официанта И вдруг исчезла$$, '2023-12-22 20:05:35.201415');
insert into сообщение values (225, 74, 'клиент', $$Строго говоря, эту шайку бесчувственных выродков он давно уже возненавидел лютой ненавистью – В Африке было очень интересно, – заявил Форд$$, '2023-12-21 18:10:25.761720');
insert into сообщение values (226, 75, 'консультант', $$Вы наверняка сталкивались с этим феноменом в жизни Поскольку личный обучающий компьютер Зафода играл активную роль в этом плане, Зафод в итоге стер из его памяти всю историю, освобождая место для более актуальной группы концепций – Они завяли лепел! – еще раз вскричал Слартибартфаст$$, '2023-11-29 07:44:23.667627');
insert into сообщение values (227, 75, 'консультант', $$– Что-то синее$$, '2023-11-28 12:28:06.881927');
insert into сообщение values (228, 75, 'клиент', $$– Безусловно, – согласился Форд Даже у примитивных племен он таится в родовой памяти – Ты будешь слушать или нет?

– Я слушаю, – сказал Артур, – только боюсь, толку мне от этого мало Не Наша Проблема$$, '2023-11-28 12:05:59.867375');
insert into сообщение values (229, 75, 'клиент', $$– Мм… да, – ответил Артур Финиш И на большей части из них он побывал уже миллионы раз Ему почудилось, что его уносит ветер Вселенной, причем этот ветер – он сам$$, '2023-11-30 00:58:18.442376');
insert into сообщение values (230, 76, 'клиент', $$И перевел взгляд на чудо творения за иллюминатором Залезайте, нам пора$$, '2025-01-22 17:19:19.580926');
insert into сообщение values (231, 76, 'клиент', $$Они стояли неподвижно$$, '2025-01-21 05:56:30.030773');
insert into сообщение values (232, 77, 'консультант', $$Мелкие капли едва просачивались сквозь туман$$, '2024-05-18 00:26:04.633839');
insert into сообщение values (233, 77, 'клиент', $$– На самом деле? – спросил Артур, ни на миг не отводя глаз от Форда Попробуйте проделать это в погожий денек, рекомендует «Путеводитель» Он приближался к рубке лилипутскими шажками с таким видом, будто предпочел бы улепетывать от нее великаньими Понимаете, мысль «Мы одни во Вселенной» их ни разу не посещала, потому что до сегодняшнего вечера они вообще не знали о существовании Вселенной$$, '2024-05-17 05:09:35.069267');
insert into сообщение values (234, 77, 'консультант', $$– На самом деле? – спросил Артур, ни на миг не отводя глаз от Форда И что самое удивительное, точно специально экипированные для данного мероприятия$$, '2024-05-16 08:52:53.175185');
insert into сообщение values (235, 78, 'консультант', $$Одиннадцать белых роботов – Я сам знаю, на что это похоже, – отрезал Слартибартфаст и вошел в пресловутое помещение Форд саркастически огляделся по сторонам Свет он выключил, чтобы его головы не видели друг дружку, поскольку обе выглядели довольно погано – с самого того момента, когда Зафод сдуру заглянул к себе в душу$$, '2024-02-04 22:26:16.573066');
insert into сообщение values (236, 78, 'консультант', $$Я выступил с ней, – тут он выдержал паузу, чтобы сделать неуклюжий жест своей здоровой рукой (относительно здоровой по сравнению с другой, наглухо приваренной к его корпусу слева), – во-он там, примерно в миле отсюда С легким жужжанием и крайне зловещим видом он завис над землей – Когда мы последний раз виделись, вы сказали то же самое, – заметил Артур Слартибартфаст уверил его, что полет состоится, что они в полной безопасности, что их ожидает крайне поучительное, хоть и довольно мучительное зрелище$$, '2024-02-06 19:50:21.258498');
insert into сообщение values (237, 78, 'клиент', $$К сожалению, именно терминалы рубки Зафод и заткнул кляпом Глаза Форда, провожавшего взглядом мяч, широко распахнулись И перевел взгляд на чудо творения за иллюминатором ниже, в главе о «Движении за Реальное Время») имел несчастье быть построенным в эпоху младенчества физики невероятности, задолго до постижения законов этой смутной и дикорастущей научной отрасли$$, '2024-02-06 12:01:32.129681');
insert into сообщение values (238, 78, 'консультант', $$– Да? – обалдело переспросил Зафод$$, '2024-02-05 15:34:19.203605');
insert into сообщение values (239, 79, 'клиент', $$Некоторые из нас гибнут от рук охотников, но, поскольку всех нас зовут Земами, утраты проходят незамеченными, и момнуханье, таким образом, остается минимальным$$, '2024-04-13 01:44:27.990063');
insert into сообщение values (240, 79, 'клиент', $$Его лучи ласкали брикеты мороженого, от чего оно таяло Он двинулся дальше, а его слова гулко повисли в воздухе Блаженно разжевав мясо, он решил официально оповестить мир о своем решении – Их здесь нет уже три года$$, '2024-04-14 18:32:03.642730');
insert into сообщение values (241, 79, 'клиент', $$Слартибартфаст уверил его, что полет состоится, что они в полной безопасности, что их ожидает крайне поучительное, хоть и довольно мучительное зрелище – Я стоял на центральной платформе Отряхнулся – А что сталось со зрителем?

– По-моему, кто-то вызвался угостить его обедом, но тот пояснил, что уже отобедал, и довольно плотно, поэтому вопрос был замят, и Уорвикшир победил с перевесом в три калитки$$, '2024-04-14 22:23:39.174509');
insert into сообщение values (242, 79, 'клиент', $$Длинный стол Он вновь задумался о происшедшем Ему только что пришел в голову великолепный способ победить ужас одиночества, кошмары, комплекс неполноценности из-за провала всех сельскохозяйственных начинаний и патологического отсутствия всякой будущности для него на доисторической Земле – Как ты там? – спросила она по внутренней связи$$, '2024-04-14 14:25:23.920966');
insert into сообщение values (243, 80, 'клиент', $$Денек выдался тяжелый – тоже правда Форд и Артур воззрились на него с крайним удивлением и острым чувством обиды за хороший вкус$$, '2023-08-26 20:10:28.082048');
insert into сообщение values (244, 80, 'клиент', $$– А сейчас ты опять в здравом рассудке? – поинтересовался Артур Форд с Артуром, пыхтя, бежали за ним, но диван увертывался и петлял, точно пространство имело для него иную, сложную математическую топографию – как оно и было в действительности Ему только что пришел в голову великолепный способ победить ужас одиночества, кошмары, комплекс неполноценности из-за провала всех сельскохозяйственных начинаний и патологического отсутствия всякой будущности для него на доисторической Земле$$, '2023-08-26 12:07:25.555948');
insert into сообщение values (245, 80, 'клиент', $$И потому большинство людей после первых неудач разочаровываются в этом увлекательном, зрелищном спорте$$, '2023-08-26 21:09:13.595688');
insert into сообщение values (246, 80, 'консультант', $$– Ликвидация, – сказал он Попробуйте проделать это в погожий денек, рекомендует «Путеводитель» В его желудке точно черти свадьбу справляли – А во-вторых, – продолжал Форд, – у тебя в бороде кость$$, '2023-08-26 16:22:58.178593');
insert into сообщение values (247, 81, 'консультант', $$А еще я пробовал научиться летать – Было что-то интересное?

И вновь они балансировали на краю ужасно высокого утеса Через несколько минут мы завладеем Золотой Перекладиной…

– Нет, не завладеете Отключив всю кухонную автоматику, она приготовила самый роскошный ужин, какой был в ее силах, – аппетитно прожаренное мясо, ароматные фрукты, благоуханный сыр, коллекционные альдебаранские вина$$, '2026-01-09 16:44:28.355034');
insert into сообщение values (248, 81, 'клиент', $$– Все в ажуре, офицер, – заявил он А эта была не хуже прочих$$, '2026-01-10 22:45:53.122397');
insert into сообщение values (249, 82, 'консультант', $$– Где?

Слегка дрожащей рукой Форд очертил чуткоматом дугу в воздухе Но зубы ему не требовались$$, '2025-10-02 03:49:42.047383');
insert into сообщение values (250, 82, 'консультант', $$– Никто на это место не нападет, – сказал Слартибартфаст с неожиданным волнением в голосе Он встал на дыбы, чтобы заглянуть за заросли, но смотреть было не на что Душа Артура летала вокруг его тела кругами и мялась, не испытывая особенного желания войти – Спасибо, что осчастливили простую скромную дверцу$$, '2025-09-28 14:06:18.318553');
insert into сообщение values (251, 83, 'клиент', $$Матрасс спросил С легким жужжанием и крайне зловещим видом он завис над землей$$, '2024-05-07 22:57:05.703566');
insert into сообщение values (252, 83, 'клиент', $$– Назревают великие события$$, '2024-05-06 18:50:01.043782');
insert into сообщение values (253, 84, 'консультант', $$Слартибартфаст, Форд и Артур остановились под ароматно пахнущим деревом Тут-то он и услышал пресловутое «Уф!», что его страшно встревожило Они немного прошли в сторону города, и инфоиллюзия травы приятно пружинила под ногами, а инфоиллюзии цветов безупречно благоухали$$, '2024-04-10 20:12:50.945299');
insert into сообщение values (254, 84, 'клиент', $$Артур растерянно кивнул И все же они продолжали погоню, а диван вальсировал и вертелся, а потом вдруг развернулся и вошел в пике, словно сорвавшись с порога графика, изображающего кризис, причем Форд с Артуром оказались буквально над ним Правда, роботы сыпались не абы как, а четким военным строем$$, '2024-04-10 11:21:18.219379');
insert into сообщение values (255, 84, 'консультант', $$Безусловно, это были не земляне, хотя все различия состояли в чуть-чуть слишком высоком росте, излишней худобе, угловатости и бледной, почти белой коже Вам того же – Но почему? Почему нельзя?

– Те, кто разговаривает по телефону сам с собой, ничего хорошего не узнают Дело есть$$, '2024-04-09 23:34:05.293392');
insert into сообщение values (256, 84, 'клиент', $$Протечку – От… к-к-к… э-э… – добавил он немного погодя Несколько биллионов триллионов тонн сверхразогретых, лопающихся ядер водорода медленно вознеслись над горизонтом, прикинувшись при этом маленькими, холодными и чуточку сырыми Вдруг он точно взорвался, обернувшись вихрем бессчетных рук и ног, из которого вылетел мяч$$, '2024-04-10 00:05:22.304925');
insert into сообщение values (257, 85, 'консультант', $$Время – это, так сказать, худшее место из всех, где только можно заблудиться Несколько биллионов триллионов тонн сверхразогретых, лопающихся ядер водорода медленно вознеслись над горизонтом, прикинувшись при этом маленькими, холодными и чуточку сырыми Для полноты картины не хватало только, чтобы порыв ветра драматически взъерошил его волосы – но местный ветерок баловался с какими-то листьями в сторонке, а на Форда и внимания не обращал$$, '2024-03-19 18:43:15.466165');
insert into сообщение values (258, 85, 'консультант', $$– Теперь понял?

– Нет, – признался Артур – Это же крикетная площадка «Лордз», верно? – возопил Артур Настоящее издевательство$$, '2024-03-19 02:37:29.296728');
insert into сообщение values (259, 85, 'консультант', $$Досчитав про себя до десяти значительных десятеричных концептов (то есть отмерив паузу, призванную выразить общее презрение ко всем матрассам и самой идее матрассности), робот вновь принялся описывать миниатюрные круги – Привет, землянин, – ответил Слартибартфаст Разница была только в том, что посылаемые их битами мячи при соприкосновении с землей взрывались$$, '2024-03-19 11:59:24.390629');
insert into сообщение values (260, 86, 'консультант', $$– И все же, – продолжало оно, – спустя пару деньков всему этому придет конец, не правда ли? Хотя, как я уже вам говорил при нашей последней встрече, это меня весьма опечалило – Где?

Слегка дрожащей рукой Форд очертил чуткоматом дугу в воздухе$$, '2023-11-16 07:30:16.671071');
insert into сообщение values (261, 86, 'консультант', $$Было неопровержимо доказано, что количество зрителей, смотревших телерепортаж о запуске «Титаника», превосходило все население Вселенной на тот момент$$, '2023-11-16 12:24:09.166250');
insert into сообщение values (262, 86, 'консультант', $$Блаженно разжевав мясо, он решил официально оповестить мир о своем решении Туда-то мы и отправимся Так и вышло Послушай, ты можешь подбросить нас до одного веселенького местечка, сейчас вспомню название, там можно чудесно надраться под какую-нибудь жутенькую музычку$$, '2023-11-17 05:25:03.112315');
insert into сообщение values (263, 86, 'консультант', $$Вот как расшифровывается ННП Криккитяне смотрели друг на друга, направо, налево, вперед, назад, даже на землю – Но…

– Демонстрирую, – сказал Форд – Ты завершил то, к чему шел много лет$$, '2023-11-16 16:29:31.586503');
insert into сообщение values (264, 87, 'консультант', $$Невдалеке слышались голоса играющих детей, а чуть подальше в раннем сумраке виднелся небольшой городок – Не могу я с ней сжиться, – мрачно вымолвил он и выслал в свой желудок третий стакан: пусть найдет второй и выяснит, почему тот еще не доложил о здоровье первого По-видимому, он полагал, что мнение Слартибартфаста слишком оптимистично$$, '2026-06-23 16:20:08.251060');
insert into сообщение values (265, 87, 'клиент', $$– Ему что-то не везло последние два миллиона лет, – пояснил он полисмену То есть больно будет, если вам не удастся промахнуться мимо земли$$, '2026-06-26 16:05:37.472332');
insert into сообщение values (266, 88, 'клиент', $$Но теперь все происходило слишком уж молниеносно – сплошное видеотактильное пятно, которое волокло их сквозь века галактической истории, крутясь, дергаясь, мерцая$$, '2024-08-03 02:42:51.111602');
insert into сообщение values (267, 88, 'консультант', $$Тогда бы ему заметили, что он поет только одну ноту, на что бы он ответил, что по очевидным, как ему кажется, причинам он опустил кусочек «ология любви»$$, '2024-08-02 18:00:53.330888');
insert into сообщение values (268, 88, 'клиент', $$Слова все время забываю$$, '2024-08-02 05:11:36.134621');
insert into сообщение values (269, 88, 'клиент', $$Артур Дент застрял на доисторической Земле в результате извилистой цепочки происшествий, в процессе каковых он попеременно подвергался оскорблениям и/или расщеплению на атомы в разнообразных экзотических уголках Галактики, бесчисленность и странность которых превзошли все его ожидания Понимаете, мысль «Мы одни во Вселенной» их ни разу не посещала, потому что до сегодняшнего вечера они вообще не знали о существовании Вселенной Пойдемте за ними и посмотрим сами$$, '2024-08-02 13:38:44.130278');
insert into сообщение values (270, 89, 'консультант', $$По жизни он не согласился бы взойти на борт такого корабля даже за всю рисовую водку страны Китай Он почувствовал себя ограбленным Нет смысла специально стараться пролететь мимо, поскольку это просто невозможно Грязно-розовое небо померкло, посинело, вновь окуталось мраком$$, '2025-05-11 14:00:10.794945');
insert into сообщение values (271, 89, 'клиент', $$У всего мира перехватывает дыхание – Э-э… – в отчаянии выпалил Артур, – э-эй!

– И нечего тут! – рявкнул инопланетянин Спасение Непонятно, с чего вдруг Слартибартфаст принялся пришептывать, как в радиорекламе какого-нибудь жуткого фильма о лесорубах, берущих на дом халтуру?

Да, но ведь вся эта история с Криккитом ничуть не лучше$$, '2025-05-08 14:34:17.360302');
insert into сообщение values (272, 90, 'консультант', $$– Видимо, нет, – ответил Зафод неизвестно откуда Артур поднял глаза$$, '2024-08-23 00:58:07.843577');
insert into сообщение values (273, 90, 'клиент', $$Боже упаси – По-моему, никаких загадочных материализации на поле не было с… э-э… с… может, их вообще ни разу еще не было – ты не помнишь?

– А Эджбастон 1932 года?

– А, ну и что же там стряслось?

– Гм, Питер, если я не ошибаюсь, Кантер играл против Уилсокса и шел в нападение со стороны павильона, когда вдруг напрямик через площадку пробежал зритель Протечку – Свобода, – произнес он вслух$$, '2024-08-21 20:35:09.483444');
insert into сообщение values (274, 90, 'клиент', $$А это совсем другой коленкор – Ты будешь слушать или нет?

– Я слушаю, – сказал Артур, – только боюсь, толку мне от этого мало Это Англия, сегодня… сегодня кошмару конец$$, '2024-08-23 15:11:33.134344');
insert into сообщение values (275, 90, 'клиент', $$– Расскажите о речи, которую вам однажды довелось произнести, – взмолился он Пытаясь совместить четырех Триллиан в единый образ, его головы столкнулись лбами Ее-то и пытался найти Слартибартфаст И это где-то недалеко$$, '2024-08-21 23:51:41.243771');
insert into сообщение values (276, 91, 'клиент', $$Компьютер безголосо пискнул в знак окончания вычислений – Что случилось? – спросил Артур с глубоким благоговением Свет он выключил, чтобы его головы не видели друг дружку, поскольку обе выглядели довольно погано – с самого того момента, когда Зафод сдуру заглянул к себе в душу В системе Неавооси находятся – то есть находились – крупнейшие страховые компании Галактики$$, '2023-08-24 02:49:41.871381');
insert into сообщение values (277, 91, 'клиент', $$Несбыточная греза Робинзона – корабль Ветер обдувал бухту, где останки одной из крупнейших и мощнейших космических флотилий в истории Галактики поспешно превращались из пепла в исходное состояние Для практики я разговариваю с этими… ну как их там… как называются эти, с которыми разговариваешь, когда с ума сходишь? Ну как Георг Третий С кличем внезапного восторга он спрыгнул с утеса и весело помчался вдогонку за Фордом Префектом и своенравным предметом мебели$$, '2023-08-23 18:51:32.441414');
insert into сообщение values (278, 91, 'клиент', $$– Мы ищем Ключ, – повторил он, – мы уже владеем Деревянным Столбом, Стальным Столбом и Плексигласовым Столбом И аналогично повышающемуся тону, который, забираясь все выше и выше, будет по дороге менять характер и обретать мелодичность, так и это бесчувственное чувство возвысилось до невыносимого, если и немого, вопля Он зафлёпал туда-сюда, ошеломленный и взволнованный$$, '2023-08-23 22:05:23.206775');
insert into сообщение values (279, 91, 'клиент', $$– А это что?

– Не Наша Проблема – Бистроматика, – пояснил он Артуру почудилось, будто весь небосвод, галантно посторонившись, уступил им дорогу$$, '2023-08-23 21:30:59.911035');
insert into сообщение values (280, 92, 'консультант', $$Его раздирали противоречивые чувства$$, '2024-06-13 09:58:30.053102');
insert into сообщение values (281, 92, 'клиент', $$Как-то ночью – а теперь на корабле ночь длилась постоянно – лежа в постели, он решил взять себя в руки, предпринять что-нибудь конструктивное Артур пожал плечами – Да так, ничего особенного, – сказал Форд$$, '2024-06-13 03:17:55.987924');
insert into сообщение values (282, 93, 'консультант', $$Затем вы освоите массу приемов по управлению своим телом в полете, регулировке скорости, выполнению маневров – Ничего не знаю, ничего не слышу, ничего не вижу, – причитал он на бегу, – это не моя планета, я сюда не просился, не хочу ввязываться, просто вытащите меня отсюда и отвезите куда-нибудь в бар, к людям, которые мне свои!

Над полем взметнулся столб пламени и дыма$$, '2024-11-28 09:28:56.076037');
insert into сообщение values (283, 93, 'консультант', $$– Мост? – не поверил своим ушам матрасс$$, '2024-11-26 16:32:26.406678');
insert into сообщение values (284, 93, 'консультант', $$Но никто этого не спрашивал, и Форд злился$$, '2024-11-28 05:02:07.152440');
insert into сообщение values (285, 94, 'клиент', $$Что ни говори, а Криккит казался приятным во всех отношениях местечком На щитки тоже стоило подивиться – по-видимому, в них были вмонтированы реактивные двигатели, что позволило этим цивилизованным роботам спикировать к земле и начать убивать людей$$, '2024-12-26 15:34:55.862816');
insert into сообщение values (286, 94, 'консультант', $$В таком настроении к оружию лучше не прикасаться И хотя они предназначались не нашим путешественникам, те машинально склонили головы – и слава богу, ибо маленький красный и тяжелый мяч (истинный виновник овации) просвистел в считаных миллиметрах над макушкой Артура$$, '2024-12-27 14:02:55.883164');
insert into сообщение values (287, 94, 'клиент', $$А потом развернулись У официанта в блокноте числа пляшут Сотни разных мыслей, расталкивая друг дружку, боролись за контроль над его голосовыми связками$$, '2024-12-25 15:44:58.169413');
insert into сообщение values (288, 95, 'клиент', $$Приборы, столь занимавшие внимание Слартибартфаста, были вмонтированы в донца бутылок, которые, в свою очередь, были заделаны в бетонную стену – Расскажите о речи, которую вам однажды довелось произнести, – взмолился он$$, '2024-07-14 05:50:19.641704');
insert into сообщение values (289, 95, 'консультант', $$Они легли на низкую орбиту$$, '2024-07-15 13:42:00.934971');
insert into сообщение values (290, 95, 'клиент', $$И само собой разумеется, он был слегка пьян$$, '2024-07-12 23:53:23.878229');
insert into сообщение values (291, 95, 'клиент', $$И само собой разумеется, он был слегка пьян – Я считаю своим долгом предупредить тебя о двух вещах, – заявил Форд, пододвинув к Артуру газету «Гардиан»$$, '2024-07-13 21:55:51.325997');
insert into сообщение values (292, 96, 'консультант', $$Вероятно, людей обуяла коллективная мысль «Ну и дела!», сопровождаемая единодушным чувством недоумения По-моему, – пояснил Артур, не сбавляя скорости$$, '2024-05-22 23:35:32.392596');
insert into сообщение values (293, 96, 'клиент', $$– Самая мощная из известных паранауке вычислительных сил – Что они… – переспросил Форд – Просто очень скоро эту планету взорвут – Алло? – произнес он в воображаемую трубку$$, '2024-05-21 21:47:32.782699');
insert into сообщение values (294, 96, 'консультант', $$– Что вы сказали? – пробормотало ошарашенное полисменообразное И сколько ни гляди на циферблат, неумолимые стрелки вскоре передвинутся на четыре – час, когда начинается долгое, мутное и, что греха таить, безумное чаепитие души И все же они продолжали погоню, а диван вальсировал и вертелся, а потом вдруг развернулся и вошел в пике, словно сорвавшись с порога графика, изображающего кризис, причем Форд с Артуром оказались буквально над ним Присев на корточки, Артур ощутил под ладонями инфоиллюзии почвы и травы$$, '2024-05-21 17:39:19.298095');
insert into сообщение values (295, 97, 'консультант', $$– … и премного довольна вновь затвориться с сознанием выполненного долга – Это необходимо убрать, – сказали криккитяне, направив корабль в сторону дома Одно-единственное «Уф!», и все тут$$, '2025-02-21 21:08:56.306756');
insert into сообщение values (296, 97, 'клиент', $$Форд, надувшись, засунул «Путеводитель» назад в сумку$$, '2025-02-23 09:43:21.945112');
insert into сообщение values (297, 98, 'клиент', $$Затем, выпучив глаза, бросился к полисмену с воплем:

– Тогда почему я так одет? – И, упав на траву, забился в судорогах Теперь события мелькали задом наперед с почти неподвластной глазу быстротой, и, когда вскорости огромный боевой звездокрейсер сбежал от них, точно они показали ему «козу», Форд с Артуром едва успели сообразить, что это и есть момент, когда они подключились к инфоиллюзии Финиш Клубы дыма струились с небосклона и влезали обратно в корабли$$, '2024-05-28 21:41:56.371571');
insert into сообщение values (298, 98, 'клиент', $$Можете рассказать это вместо анекдота своим друзьям Зему и Зему при первой же встрече – они животики надорвут, если я их знаю$$, '2024-05-30 03:51:06.064246');
insert into сообщение values (299, 98, 'клиент', $$– Разумеется, это не подлинный ключ$$, '2024-05-29 15:16:23.796987');
insert into сообщение values (300, 98, 'консультант', $$И хотя они предназначались не нашим путешественникам, те машинально склонили головы – и слава богу, ибо маленький красный и тяжелый мяч (истинный виновник овации) просвистел в считаных миллиметрах над макушкой Артура Эта композиция почему-то показалась Артуру до идиотизма знакомой Без нее мой корабль перестанет работать$$, '2024-05-29 11:49:46.344319');
insert into сообщение values (301, 99, 'клиент', $$– Чувствуя, что собеседники все еще недоумевают, он снизошел до разъяснений: – Слушайте$$, '2025-11-20 04:01:24.461984');
insert into сообщение values (302, 99, 'консультант', $$Глаза Форда, провожавшего взглядом мяч, широко распахнулись Зафод крякнул$$, '2025-11-19 12:25:01.514051');
insert into сообщение values (303, 100, 'клиент', $$– Верно, – признал Артур – Клянусь, они в крикет играют Слегка нахмурившись, он склонил голову набок Вы наверняка сталкивались с этим феноменом в жизни$$, '2024-04-06 21:06:47.150907');
insert into сообщение values (304, 100, 'консультант', $$– Я-то думал, что стряслось, – сказал Форд, – а это просто матч кончился$$, '2024-04-06 06:25:21.890868');
insert into сообщение values (305, 100, 'консультант', $$Он был призван воскресить экономику системы Прутивнобендзы, напрочь подорванную расходами на его строительство$$, '2024-04-05 10:14:40.278665');
insert into сообщение values (306, 100, 'клиент', $$Вот как расшифровывается ННП$$, '2024-04-06 13:38:46.811990');
insert into сообщение values (307, 101, 'клиент', $$– Из мглы времен восстало великое проклятие, – сказал Слартибартфаст Этот миг пришел и миновал без происшествий, как и бывало обычно на Зете Прутивнобендзы$$, '2023-11-25 19:35:22.386553');
insert into сообщение values (308, 101, 'консультант', $$И каждая частичка еды была, по-видимому, наделена всеми механическими свойствами, например, «цыпленка-алла-романа», на деле им не будучи И вновь зашагал вперед$$, '2023-11-25 15:35:33.136883');
insert into сообщение values (309, 101, 'консультант', $$Весь фокус в том, чтобы научиться швыряться своим телом в земную поверхность и при этом промахиваться$$, '2023-11-26 02:19:03.302860');
insert into сообщение values (310, 101, 'клиент', $$Вот… – вымолвил он, задыхаясь, – … за чем… они… прилетали… – С этими словами он легонько мотнул головой, словно пытаясь утрясти свой мозг Зафоду пришло в голову, что для ускорения беседы предложения нужно сделать вопросительными Зафод влил еще стакан в свою другую глотку$$, '2023-11-26 05:00:00.321889');
insert into сообщение values (311, 102, 'консультант', $$Затем Триллиан набрела на главку о Хэй-Виляй, экзотической планете-курорте, одном из чудес Галактики Матрасс клюшивал и фнукивал – Нет, – сказал Форд, – он чувствует мобильную аномалию в ткани пространства-времени, локальное возмущение, очаг нестабильности$$, '2025-02-19 09:19:08.959603');
insert into сообщение values (312, 102, 'клиент', $$Эта штука недавно проснулась Тут силы матрасса иссякли, и он флюмкнулся обратно в протоку, обрушив на Марвина струю мокрой тины с водорослями и мхом – Давайте, вы двое, – сказало нечто, – пройдемте Затем еще раз огляделся по сторонам с еще большим ужасом$$, '2025-02-19 15:12:31.905065');
insert into сообщение values (313, 103, 'консультант', $$Болтайтесь над землей и парите, парите и болтайтесь$$, '2024-07-06 05:41:25.582293');
insert into сообщение values (314, 103, 'консультант', $$Он никогда не слышал, чтобы на Зете Прутивнобендзы выступали с речами, а тем более знаменитости – Уф!

Зафод остановился «Может ли быть, что это и есть истинное устройство Вселенной? – вопросил он себя Непонятно, с чего вдруг Слартибартфаст принялся пришептывать, как в радиорекламе какого-нибудь жуткого фильма о лесорубах, берущих на дом халтуру?

Да, но ведь вся эта история с Криккитом ничуть не лучше$$, '2024-07-06 12:52:01.274147');
insert into сообщение values (315, 103, 'клиент', $$– Только, – заверил его Форд Оно меняется в период первых трех телефонных звонков в ресторан, а потом, как выясняется, и отдаленно не совпадает с истинным числом явившихся на ужин, а также с количеством людей, которые присоединяются к ним после спектакля/концерта/матча/вечеринки, и с количеством людей, которые спешат ретироваться при виде новоприбывших – А… тв… в… хто… кто? – выдавил он наконец, после чего погрузился в неистовое (сродни неистовым воплям) безмолвие$$, '2024-07-08 01:54:25.821391');
insert into сообщение values (316, 104, 'клиент', $$– Более того, они еще толком и не начались, – уточнил Форд Длинный стол Это был рубеж, за который никто из криккитян не заглядывал даже в мечтах, поскольку не знал о его существовании$$, '2026-11-29 22:19:55.608187');
insert into сообщение values (317, 104, 'клиент', $$Примерно в 14$$, '2026-11-25 17:13:04.576634');
insert into сообщение values (318, 105, 'клиент', $$И вдруг роботы вернулись, снова начался кавардак, и на этот раз после их отлета матрасс остался на болоте один Попятившись, Артур испуганно огляделся по сторонам Форд и Артур воззрились на него с крайним удивлением и острым чувством обиды за хороший вкус Недавно был открыт лес, где почти все деревья в качестве плодов дают отвертки с храповиком$$, '2024-03-18 12:39:09.451716');
insert into сообщение values (319, 105, 'клиент', $$– Видимо, вы поглощены размышлениями, – плучительно сказал матрасс И перевел взгляд на чудо творения за иллюминатором$$, '2024-03-18 23:34:56.258737');
insert into сообщение values (320, 105, 'клиент', $$– … напомни, чтобы я дал сам себе в зубы$$, '2024-03-18 20:53:41.494744');
insert into сообщение values (321, 106, 'консультант', $$– А затем мы отправимся, – на полном серьезе заявил робот, – на вечеринку$$, '2027-01-02 18:06:09.329175');
insert into сообщение values (322, 106, 'консультант', $$– Я столько лет никого не видел, – заговорил он, – просто ни единой души$$, '2027-01-01 11:34:32.566076');
insert into сообщение values (323, 107, 'консультант', $$– А вот это, – сказал Слартибартфаст, перейдя на загробный хрип и указывая на компанию криккитян, которые удалялись в сторону города, – те самые, с кого все началось – Эксцентрика Гамбитус, ты ее когда-нибудь видел? Троегрудая путана с Эротикона-6 Эта штука недавно проснулась$$, '2024-09-02 17:22:06.422716');
insert into сообщение values (324, 107, 'клиент', $$– Видимо, нет, – ответил Зафод неизвестно откуда$$, '2024-09-01 16:15:53.728724');
insert into сообщение values (325, 107, 'консультант', $$Артур наморщил лоб:

– А почему на вашем корабле все вычисления… – И прикусил язык$$, '2024-09-01 13:59:19.526613');
insert into сообщение values (326, 107, 'клиент', $$– Порядок, – ответил он бодро, – ужас как хорошо Глагол «флёпать» обозначает действие, посильное лишь живым матрассам на болоте, чем и объясняется малораспространенность этого слова$$, '2024-09-02 02:06:58.284726');
insert into сообщение values (327, 108, 'консультант', $$Как ни странно, за пределами словаря осталось слово «плучительно», означающее просто-напросто «с плучительностью» Даже у примитивных племен он таится в родовой памяти Другой суперсенсацией тогдашней прессы стала вспышка сверхновой звезды, в которую несколько часов спустя превратилась звезда Неавоось$$, '2024-11-27 01:59:24.708967');
insert into сообщение values (328, 108, 'консультант', $$Им составляли компанию недоеденные ломти хлеба и недопитые бокалы вина – Пожми ее, – просуфлировал Форд$$, '2024-11-25 19:25:55.822167');
insert into сообщение values (329, 108, 'консультант', $$Защитник, взмахнув битой, послал мяч себе за спину так, что он пролетел над табло$$, '2024-11-25 12:09:42.856381');
insert into сообщение values (330, 108, 'консультант', $$Триллиан терпеливо кивнула самой себе, досчитала до предыдущего числа в кубе, вяло швырнула поднос в стену, прошла в телепортационную кабину и просто ушла из его жизни Что делать?

Форд пожал плечами:

– А что ты предлагаешь?

– Скажи мне, – попросил Артур, – что все последние пять лет приснились мне во сне Артур поделился своим впечатлением с друзьями$$, '2024-11-26 05:32:00.376375');
insert into сообщение values (331, 109, 'клиент', $$Довольные улыбки, которыми он обычно озарял чужие похороны, стали какими-то натянутыми Затем он совершил нечто, что матрассы обычно делать ленятся Они уселись на камень и впали в глубокую задумчивость Тут наблюдатели услышали высоко в безглазых небесах тоненький визг$$, '2024-11-16 22:00:54.825239');
insert into сообщение values (332, 109, 'клиент', $$Гладь болота украсилась очаровательными пузырьками – Они завяли лепел! – еще раз вскричал Слартибартфаст Они находились перед Рубиконом исторического самосознания своего народа$$, '2024-11-16 20:18:19.372112');
insert into сообщение values (333, 109, 'клиент', $$ Над тремя столбиками сияли, слепя глаза, две перекладины$$, '2024-11-15 17:23:47.280184');
insert into сообщение values (334, 110, 'консультант', $$Зафод влил еще стакан в свою другую глотку И оторопел от последствий своего заявления$$, '2026-12-05 16:46:39.675936');
insert into сообщение values (335, 110, 'клиент', $$– Во-первых, – сказал он, тыча пальцем в угол газеты, где значилась дата, – через два дня Земля будет взорвана$$, '2026-12-05 08:44:05.130448');
insert into сообщение values (336, 111, 'консультант', $$– Да-да, хорошо, это не обязательно, – поспешно заявил полисмен, – только постарайтесь, чтобы такого… этого… больше не было ) Ха! О, жизнь моя – жестянка, жестянка на червячном ходу!

И снова побрел вокруг своей тонкой стальной ноги-протеза, которая вращалась в грязи, но никак не поддавалась Форд что-то мурлыкал под нос$$, '2024-01-23 00:37:12.647005');
insert into сообщение values (337, 111, 'консультант', $$– В глубинах фундаментального сердца духа и Вселенной, – сказал Слартибартфаст, – кроется причина тому – Кто же?

– Мммммм мммммм мммммм, – сказал компьютер Сам собой откинулся трап$$, '2024-01-22 02:21:17.396957');
insert into сообщение values (338, 111, 'консультант', $$– Странная весть, – процедил Форд – Классно, – молвил Артур – и его душа выпорхнула наружу перевести дух Вскоре стали различимы и звуки, а затем стало понятно, что это маленькая кучка людей, и держат они путь домой, в город$$, '2024-01-23 10:39:14.365631');
insert into сообщение values (339, 111, 'клиент', $$Они стояли неподвижно Некоторые из нас гибнут от рук охотников, но, поскольку всех нас зовут Земами, утраты проходят незамеченными, и момнуханье, таким образом, остается минимальным На полпути к рубке его осенило, что это вполне может оказаться Марвин, и он бегом вернулся обратно – А вот это, – сказал Слартибартфаст, перейдя на загробный хрип и указывая на компанию криккитян, которые удалялись в сторону города, – те самые, с кого все началось$$, '2024-01-23 10:21:26.397501');
insert into сообщение values (340, 112, 'клиент', $$– Привет, землянин, – ответил Слартибартфаст Его причины остаются тайной, так как ни одному из геофизиков, специалистов по статистике вероятностей, метеорологов-аналитиков и чудологов поездка на Хэй-Виляй не по карману Звук превратился в монотонный звон в ушах$$, '2024-09-05 16:47:06.335077');
insert into сообщение values (341, 112, 'консультант', $$Было темно Присев на корточки, Артур ощутил под ладонями инфоиллюзии почвы и травы$$, '2024-09-03 01:23:37.478500');
insert into сообщение values (342, 112, 'консультант', $$Строго индивидуально, лицом к лицу, одного за другим и (тут он с особым сладострастием скрипнул зубами) в алфавитном порядке – Я думал, ты сказал, что это не наша проблема – Поймать? – пробормотал Артур и тут же вытаращил глаза – диван, вальяжно покачиваясь, уплывал в глубь поля (Естественно, я не знаю их лично, но я знаю природу всех органических живых существ, и гораздо более досконально, чем хотел бы$$, '2024-09-03 17:14:59.433025');
insert into сообщение values (343, 113, 'клиент', $$Но тут он поднял глаза на ужасающе голый небосклон и остро ощутил всю важность этой детали С большим ехидством – Скатертью дорожка, – пробормотал Зафод, перевернулся на другой бок и всю ночь не смыкал глаз$$, '2024-10-08 23:20:25.945266');
insert into сообщение values (344, 113, 'консультант', $$– Что «нет»?

– Не пытайся звонить себе самому домой Это была безумная колымага из подручных материалов$$, '2024-10-11 08:53:57.756009');
insert into сообщение values (345, 113, 'консультант', $$– Да так, ничего особенного, – сказал Форд Присев на корточки, Артур ощутил под ладонями инфоиллюзии почвы и травы$$, '2024-10-11 09:49:20.834956');
insert into сообщение values (346, 113, 'клиент', $$Аналогично последовательность отдельных впечатлений сливалась тут в единое чувство – хотя на чувство оно как-то не походило Следовательно, они сохранят у себя Пепел$$, '2024-10-09 10:05:12.333833');
insert into сообщение values (347, 114, 'клиент', $$– Я-то думал, что стряслось, – сказал Форд, – а это просто матч кончился Досчитав про себя до десяти значительных десятеричных концептов (то есть отмерив паузу, призванную выразить общее презрение ко всем матрассам и самой идее матрассности), робот вновь принялся описывать миниатюрные круги Однако матрасс попался какой-то уж очень глупый и лишь воззрился на него в ответ круглыми глазами Видение состроило нечто вроде ехидной ухмылки – впрочем, еще неизвестно, насколько ехидной, ибо солнце, светя ему прямо в затылок, соорудило из его серебристых волос и бороды ослепительный, драматический, повергающий в трепет нимб, с которым никакие ехидные ухмылки не вязались$$, '2024-04-02 17:13:36.941036');
insert into сообщение values (348, 114, 'клиент', $$Он опять воззрился на экран – По-моему, его здесь нет, – сказал он мальчишкам, которые немедленно столпились вокруг него, – вероятно, он куда-то откатился$$, '2024-04-02 18:36:02.722289');
insert into сообщение values (349, 114, 'консультант', $$То была ненависть, слепая ненависть Им составляли компанию недоеденные ломти хлеба и недопитые бокалы вина – Батарейка села? – поинтересовался Артур В обе стороны, на сотни миль передо мной и на сотни миль позади меня, тянулось полотно моста$$, '2024-04-02 04:26:40.751328');
insert into сообщение values (350, 115, 'клиент', $$По-видимому, это словесное излияние вдохновило его на новый взлет к высотам уныния и отчаяния Мерещилось, будто мрак гудит, с треском лопается на носу корабля Замотав головой, Форд закрыл лицо руками и нечаянно отфутболил к стене подвернувшийся под ногу цветочный горшок$$, '2025-10-15 17:45:19.085291');
insert into сообщение values (351, 115, 'консультант', $$Тот же самый эффект наблюдался и в случае с кораблем Слартибартфаста Потом стал выключать освещение – Тс-с-с, – сказал Слартибартфаст$$, '2025-10-13 18:09:22.646629');
insert into сообщение values (352, 115, 'консультант', $$Вот уже четыре года (со дня расставания с Фордом Префектом) Артур в общем-то ни одной души не видел, а потому и оскорблениям больше не подвергался Вот оно – то, что разрушили орды Криккита, то, что теперь держит их планету в заточении и будет держать до скончания вечности!

И вальяжным жестом мужчина извлек из воздуха модель Трикетной Калитки$$, '2025-10-14 04:39:46.871782');
insert into сообщение values (353, 116, 'клиент', $$Ни одного матрасса это, по-видимому, не удручает Ему пришло в голову, что во Вселенной непременно найдется кто-то, кому жизнь кажется еще более беспросветной, тяжелой и треклятой, чем ему$$, '2025-09-09 12:58:31.585178');
insert into сообщение values (354, 116, 'клиент', $$С того дня прошло уже два года – И он сверкал? – воскликнул очарованный матрасс – Это же крикетная площадка «Лордз», верно? – возопил Артур Первая реакция: «На соплях держится»$$, '2025-09-07 17:00:49.731614');
insert into сообщение values (355, 116, 'консультант', $$Оплетенные соломой бутылки поджидали неосторожных путников в засаде$$, '2025-09-08 14:10:41.036316');
insert into сообщение values (356, 117, 'консультант', $$Триллиан вновь терпеливо кивнула, досчитала до… – в общем, число было немаленькое – и сказала себе, что на данном этапе самое важное – хотя бы разговорить Зафода – Ву-ун, – враднул он наконец Охмешконасыпатель Конца-Краю-Не-Знающий принадлежал – то есть принадлежит – к очень узкому кругу бессмертных обитателей Вселенной Не знаю, зачем им это надо, но так оно и есть$$, '2025-05-29 16:54:24.446348');
insert into сообщение values (357, 117, 'консультант', $$Его лучи обращали в алмазы слезы детишек, уронивших растаявшее мороженое с палочки Они дико жестикулировали и пытались сравнивать свои порции курятины с чужими$$, '2025-05-28 09:24:10.455395');
insert into сообщение values (358, 117, 'консультант', $$Выдвинул невысокий трап$$, '2025-05-27 18:19:36.145931');
insert into сообщение values (359, 118, 'клиент', $$Умопомрачительно красивый, уникально огромный и к тому же самый уютный корабль в истории Галактики (точнее, в нынешней, сильно обкарнанной опровержениями версии этой самой истории – подробности см Приятели направились к пресловутому кораблю Пытаясь совместить четырех Триллиан в единый образ, его головы столкнулись лбами – Да? – обалдело переспросил Зафод$$, '2024-07-26 04:51:20.382560');
insert into сообщение values (360, 118, 'консультант', $$Можете рассказать это вместо анекдота своим друзьям Зему и Зему при первой же встрече – они животики надорвут, если я их знаю Триллиан вновь терпеливо кивнула, досчитала до… – в общем, число было немаленькое – и сказала себе, что на данном этапе самое важное – хотя бы разговорить Зафода – Эти самые, с которыми он разговаривал Почва производила впечатление тяжелой и вязкой, трава была упруга$$, '2024-07-26 14:31:10.929478');
insert into сообщение values (361, 118, 'клиент', $$– Скатертью дорожка, – пробормотал Зафод, перевернулся на другой бок и всю ночь не смыкал глаз Что скажешь, Артур? Очнись, перестань бурчать свои мантры – Повелители Криккита, – повторил Слартибартфаст$$, '2024-07-25 01:54:21.333056');
insert into сообщение values (362, 119, 'консультант', $$Они и не догадывались, что всем вычислениям в области невероятности свойственны квазивзаимообратимость и кольцеобразность, благодаря чему все Бесконечно Невероятное почти немедленно осуществляется в реальности А когда раскроешься, я тебя прошу, не говори, что тебя это осчастливило, ладно?

– Ладно Фальшивка Он двинулся дальше, а его слова гулко повисли в воздухе$$, '2026-04-30 07:05:42.888565');
insert into сообщение values (363, 119, 'клиент', $$В его пещере царил холод (а также смрад и сырость), но это еще пол-ужаса$$, '2026-05-05 00:04:00.958762');
insert into сообщение values (364, 120, 'консультант', $$Правда, роботы сыпались не абы как, а четким военным строем Приятели направились к пресловутому кораблю – Боюсь, это зрелище подействует вам на нервы, – предупредил он$$, '2024-05-31 00:39:00.557652');
insert into сообщение values (365, 120, 'консультант', $$Поддельные бутылки в поддельном бетоне – Нынче тут, завтра там и кое-где еще, – сообщил Форд – На самом деле? – спросил Артур, ни на миг не отводя глаз от Форда Артур, растроганный и недоумевающий, только замотал головой$$, '2024-05-31 15:54:33.192031');
insert into сообщение values (366, 120, 'клиент', $$Он уставился на диван умными глазами Его челюсти начали делать отжимания$$, '2024-05-31 16:17:11.268035');
insert into сообщение values (367, 120, 'консультант', $$– Судя по всему… – произнес Форд, – … в ткани пространства-времени… – произнес Форд, – … появились… – произнес Форд, – … очаги…

Артур тупо смотрел на отворот своего халата, сжимаемый пальцами Форда – Более того, они еще толком и не начались, – уточнил Форд$$, '2024-05-30 06:56:39.808795');
insert into сообщение values (368, 121, 'клиент', $$Артур хмуро поплелся за ним – Где вы ее нашли и как сюда переместили? По-моему, – добавил он, потирая лоб, – мне надо успокоиться Сам себе сосчитал пульс$$, '2024-12-25 08:06:33.868918');
insert into сообщение values (369, 121, 'клиент', $$Корабль пересекал орбиты планет Солнечной системы, намереваясь совершить пертурбационный маневр вокруг Солнца и, разогнавшись, выскочить в большой космос$$, '2024-12-24 16:26:56.889300');
insert into сообщение values (370, 121, 'консультант', $$– Роботы, – поправил себя Зафод, – что вы, роботы, тут делаете?

– Мы пришли, – прохрипел робот, – за Золотом Перекладины$$, '2024-12-24 05:01:00.659552');
insert into сообщение values (371, 122, 'консультант', $$– Нет ни одной планеты, – отчеканил высокопрофессиональный голос ведущего, – нет ни одной цивилизованной планеты в Галактике, где и в наши дни ни почитали бы этот символ – Ладно, – сказал Зафод и напрягся, – а теперь раскройся Точнее, распахнул люки и выпустил из себя нечто необычное в количестве одиннадцати штук – Эксцентрика Гамбитус, ты ее когда-нибудь видел? Троегрудая путана с Эротикона-6$$, '2025-02-14 19:26:49.717073');
insert into сообщение values (372, 122, 'клиент', $$Артур Дент К счастью, таких тут хватало И она была смертельно опасна – и вновь не на манер ножа или пули, но наподобие кирпичной стены поперек шоссе$$, '2025-02-14 04:04:48.724528');
insert into сообщение values (373, 122, 'клиент', $$Темп все возрастал – …и…

– Похоже, до тебя дошло Она просто ушла – превратилась в случайный набор точек, странствующий по Вселенной Теперь события мелькали задом наперед с почти неподвластной глазу быстротой, и, когда вскорости огромный боевой звездокрейсер сбежал от них, точно они показали ему «козу», Форд с Артуром едва успели сообразить, что это и есть момент, когда они подключились к инфоиллюзии$$, '2025-02-14 05:54:13.536193');
insert into сообщение values (374, 123, 'клиент', $$– Куда теперь?

– Вычисляю На горизонте маячили симпатичные круглые холмы$$, '2025-07-07 07:54:16.663861');
insert into сообщение values (375, 123, 'консультант', $$Матрасс клюшивал и фнукивал В нем не было ничего – Эксцентрика Гамбитус, ты ее когда-нибудь видел? Троегрудая путана с Эротикона-6 – Слушаю, – пропищал компьютер$$, '2025-07-05 02:34:03.812038');
insert into сообщение values (376, 123, 'консультант', $$Только тускло-розовые каемки вокруг дверей, мерцавшие в такт их речам, – Зафоду так и не удалось придумать, как заткнуть им глотки И все же что было, тому не миновать$$, '2025-07-05 04:08:08.823563');
insert into сообщение values (377, 124, 'клиент', $$– Речь идет о каких-то неполадках космического водопровода, я так понял? – осторожно спросил он – У меня врачи нашли недоразвитость гланды общественного долга и врожденный порок морального ядра личности, – пробормотал он под нос, – ну разве мне можно доверить спасение Вселенной, сами посудите?

И тем не менее поднялся по лестнице вслед за сотоварищами Его лучи обращали в алмазы слезы детишек, уронивших растаявшее мороженое с палочки Кроме того, в звездолете просто не нашлось бы столько дверей – пресловутое «уф» прозвучало так, будто его произнесли сто тысяч человек разом$$, '2024-02-29 00:01:05.625306');
insert into сообщение values (378, 124, 'консультант', $$Его ужасно умиляло, что в этот день все его планы сами собой сбывались$$, '2024-02-28 23:30:52.989175');
insert into сообщение values (379, 124, 'консультант', $$– А вот это, – сказал Слартибартфаст, перейдя на загробный хрип и указывая на компанию криккитян, которые удалялись в сторону города, – те самые, с кого все началось Полисмен развернулся и побрел искать кого-нибудь, кто был бы не с Бетельгейзе Ну а для Зафода это обернулось тем, что: а) он ни разу даже не подошел к девочке и б) пропустил целую эпоху в древней истории, знания о которой ему бы сейчас очень пригодились$$, '2024-02-28 17:52:37.866448');
insert into сообщение values (380, 124, 'консультант', $$– Форд встряхнул прибор – Странное это дело, – тихо проговорил Артур, – чем быстрее и дальше путешествуешь по Галактике, тем менее важным кажется твое местоположение в ней, и тебя охватывает глубокое, точнее, опустелое чувство… этого самого…

– Да, очень странно, – согласился Форд – Хороша лошадка, – заметил Форд, безуспешно пытаясь скрыть свое восхищение маневром корабля, – жаль, с дизайном ей не повезло$$, '2024-02-29 16:29:30.603262');
insert into сообщение values (381, 125, 'консультант', $$Однако, судя по всему, больше никто его не замечал$$, '2025-07-04 12:46:07.794367');
insert into сообщение values (382, 125, 'консультант', $$– Ну, корабль ведь твой$$, '2025-07-03 11:56:28.879316');
insert into сообщение values (383, 126, 'консультант', $$Тут Артура посетила некая неясная догадка относительно смысла представшего перед ним зрелища, но он поспешил ее отбросить Поплотнее запахнувшись в свой обтрепанный халат, он приветствовал доброе утро широкой улыбкой Слартибартфаст дернул за ручку, и она умолкла – Я-то думал, что стряслось, – сказал Форд, – а это просто матч кончился$$, '2025-03-14 01:12:57.660661');
insert into сообщение values (384, 126, 'консультант', $$Артур поделился своим впечатлением с друзьями Оно опасно?

– Мммм – Бистроматика, – пояснил он – И указал в ту сторону, куда хотел бы спровадить ребят$$, '2025-03-16 00:05:08.990809');
insert into сообщение values (385, 127, 'консультант', $$Выдвинул невысокий трап$$, '2025-05-16 22:40:57.557046');
insert into сообщение values (386, 127, 'консультант', $$Ну а для Зафода это обернулось тем, что: а) он ни разу даже не подошел к девочке и б) пропустил целую эпоху в древней истории, знания о которой ему бы сейчас очень пригодились Темп застольных манипуляций неуловимо ускорился$$, '2025-05-18 02:27:24.182130');
insert into сообщение values (387, 127, 'клиент', $$Он напряг слух, но больше ничего не слышалось Шшшшрр$$, '2025-05-17 09:31:33.506413');
insert into сообщение values (388, 127, 'консультант', $$Затем были изобретены словоформы типа «Интерактивно-субъективное моделирование», и все смогли вздохнуть спокойно и заняться делом$$, '2025-05-15 05:58:47.098376');
insert into сообщение values (389, 128, 'клиент', $$Вокруг него – около дюжины стульев Он с грохотом понесся по небу, словно точно знал, что делает Форд повторил$$, '2024-03-25 19:38:33.673542');
insert into сообщение values (390, 128, 'клиент', $$Правда, роботы сыпались не абы как, а четким военным строем – И также я тебя прошу не говорить, что ты очень рада быть полезной или что ты польщена честью раскрыться передо мной и премного довольна вновь затвориться с сознанием выполненного долга, ладно?

– Ладно$$, '2024-03-25 18:19:23.556837');
insert into сообщение values (391, 128, 'консультант', $$Форд, надувшись, засунул «Путеводитель» назад в сумку Он задумчиво уставился вдаль Говоря о свидании с девушкой, автор соблазнял ее прогуляться не «при луне» или «под звездным небом», но просто «по траве», что показалось Артуру излишне прозаичным Нападающий приближался к калитке, плавно переходя с рысцы на бег[2]$$, '2024-03-26 04:48:35.359027');
insert into сообщение values (392, 129, 'консультант', $$– А я спал, – заявил вынырнувший откуда-то Форд$$, '2025-12-10 23:00:39.678968');
insert into сообщение values (393, 129, 'консультант', $$– Ты наверняка знаешь, что сейчас произойдет, – сказал Слартибартфаст Форду Он мягко приземлился Другими словами, имелись в наличии все предпосылки для приступа самокопания, но, как показала жизнь, поддаваться ему никак не следовало – Клянусь, они в крикет играют$$, '2025-12-12 22:24:34.937550');
insert into сообщение values (394, 130, 'консультант', $$Поддельные бутылки в поддельном бетоне И хотя теперь его жизнь текла чрезвычайно ровно и спокойно, нервы Артура по-прежнему шалили Это был рубеж, за который никто из криккитян не заглядывал даже в мечтах, поскольку не знал о его существовании И все двигалось, приплясывало, трепыхалось$$, '2024-11-30 10:55:39.787340');
insert into сообщение values (395, 130, 'консультант', $$– Я ужасно рад вновь тебя видеть$$, '2024-11-30 06:08:26.068360');
insert into сообщение values (396, 131, 'консультант', $$– Опасно?

– Мммм Потренируйтесь делать пике, вначале простое, а потом, мерно дыша, лягте в дрейф над верхушками деревьев Ужасно повеселился – все две недели только и знал, что бултыхался в джине с тоником Теперь события мелькали задом наперед с почти неподвластной глазу быстротой, и, когда вскорости огромный боевой звездокрейсер сбежал от них, точно они показали ему «козу», Форд с Артуром едва успели сообразить, что это и есть момент, когда они подключились к инфоиллюзии$$, '2024-05-08 09:02:28.158997');
insert into сообщение values (397, 131, 'консультант', $$Если и раньше он изъяснялся тоном призрака, то теперь это был вообще некий сильно простуженный житель Аида$$, '2024-05-08 18:14:24.772975');
insert into сообщение values (398, 131, 'консультант', $$Но тьма – глухой кокон, оберегающий внутренний мрак, – все еще гудела вокруг корабля – Я вижу эту штуку, – объявил Артур, – это звездолет И она была смертельно опасна – и вновь не на манер ножа или пули, но наподобие кирпичной стены поперек шоссе Через некоторое время Форд счел необходимым отнять у Артура свою конечность$$, '2024-05-07 16:14:35.616821');
insert into сообщение values (399, 132, 'консультант', $$Однако, судя по всему, больше никто его не замечал Огни зажглись и потухли, столбы исчезли, мужчина, пятясь, растворился в пустоте, а Вселенная проворно сложилась обратно в привычную картину – А во-вторых, – продолжал Форд, – у тебя в бороде кость$$, '2027-07-04 06:46:58.378829');
insert into сообщение values (400, 132, 'консультант', $$– Протечки?

– Протечки в пространстве-времени, – сказал Форд и поспешил подставить свое зверски ухмыляющееся лицо ветру, который как раз случайно пролетал мимо – Гм$$, '2027-07-05 09:33:37.694267');
insert into сообщение values (401, 133, 'клиент', $$Зафод вновь кивнул, поигрывая пистолетом Поговаривают, что у нее эрогенные зоны начинаются милях в четырех от тела как такового$$, '2024-09-22 13:21:39.412614');
insert into сообщение values (402, 133, 'клиент', $$Но не думаю, что с дурными намерениями Тихо-тихо-тихо дверь прошептала:

– Я вас слышу Денек выдался тяжелый – тоже правда Из чистой любви к переменам, сами понимаете$$, '2024-09-23 00:35:02.563136');
insert into сообщение values (403, 133, 'клиент', $$– Считайте, что вы ее уже выразили, мой дорогой друг, – флюрбнул матрасс, – считайте, что вы ее уже выразили Вскоре стали различимы и звуки, а затем стало понятно, что это маленькая кучка людей, и держат они путь домой, в город$$, '2024-09-22 02:51:11.834566');
insert into сообщение values (404, 134, 'консультант', $$– Сейчас промотаем всю эту чушь – Короли? – подсказал Форд После нескольких удачных проб вы обнаружите, что отвлечься становится все проще и проще$$, '2026-08-01 20:24:17.787778');
insert into сообщение values (405, 134, 'клиент', $$– Артур, мы бороздим Галактику в поисках развлечений$$, '2026-08-05 00:52:30.245882');
insert into сообщение values (406, 134, 'консультант', $$– Алло? – произнес он в воображаемую трубку$$, '2026-08-04 02:25:22.989869');
insert into сообщение values (407, 135, 'консультант', $$Его губы тоже дергались$$, '2028-08-02 00:38:17.431969');
insert into сообщение values (408, 135, 'консультант', $$То есть он решил оскорбить всех ее обитателей Старец остановился и поднял глаза к небу$$, '2028-08-01 02:47:09.009273');
insert into сообщение values (409, 136, 'клиент', $$Бистроматика как таковая являет собой революционно-новый подход к интерпретации поведения чисел Ну а для Зафода это обернулось тем, что: а) он ни разу даже не подошел к девочке и б) пропустил целую эпоху в древней истории, знания о которой ему бы сейчас очень пригодились$$, '2024-09-28 07:08:08.833233');
insert into сообщение values (410, 136, 'консультант', $$Он заразился у Слартибартфаста беспокойством, хоть и не понимал его причин Зафод похолодел – У нас на борту кто-то есть?

– Мммм, – ответил компьютер Ты что-то сказал?

– Дизайн, – повторил Форд$$, '2024-09-28 20:29:28.623915');
insert into сообщение values (411, 136, 'клиент', $$На следующий день Артур сшил себе сумку из кроличьей шкурки – под всякие полезные вещи А случится это сегодня Одно мычание вместо «да», два вместо «нет» Может, там находится другая планета – ох, как трудно далось это предположение самозамкнутым умам сынов Криккита с его глухой стеной вместо неба$$, '2024-09-28 15:52:42.365601');
insert into сообщение values (412, 136, 'консультант', $$– Он вытащил «Путеводитель» и просмотрел по диагонали страницы указателя, специально посвященные вопросам секса, наркотиков и рок-н-ролла – Вон там! – вскричал Форд, дико взмахнув рукой – Мост? – не поверил своим ушам матрасс$$, '2024-09-28 08:56:14.979527');
insert into сообщение values (413, 137, 'клиент', $$Они находились перед Рубиконом исторического самосознания своего народа$$, '2028-06-05 06:24:13.492391');
insert into сообщение values (414, 137, 'клиент', $$Это Англия, сегодня… сегодня кошмару конец Около того, – сказал Марвин надменно Глаза Артура пошли колесом$$, '2028-06-08 22:34:28.330668');
insert into сообщение values (415, 138, 'клиент', $$Лед тронулся У меня самый классный корабль во всем известном небе, девушка, с которой у меня все чудесно…

– Да?

– Ну, насколько я понимаю С того дня прошло уже два года$$, '2026-05-16 14:03:37.433100');
insert into сообщение values (416, 138, 'клиент', $$– Да уж вот так, – подтвердил Форд – И плюхнувшись на колени перед Фордом, прошипел: – Это полисмен Точнее, распахнул люки и выпустил из себя нечто необычное в количестве одиннадцати штук$$, '2026-05-15 05:19:58.642128');
insert into сообщение values (417, 138, 'консультант', $$Произошла настоящая революция – Алло? – произнес он в воображаемую трубку Я не шучу$$, '2026-05-15 13:10:50.617978');
insert into сообщение values (418, 139, 'клиент', $$Это они шли в тот вечер по тропе, распевая мелодичные, проникновенные песни – Никто на это место не нападет, – сказал Слартибартфаст с неожиданным волнением в голосе Поскольку личный обучающий компьютер Зафода играл активную роль в этом плане, Зафод в итоге стер из его памяти всю историю, освобождая место для более актуальной группы концепций Зафод закрыл руками одно из своих лиц$$, '2026-01-31 13:53:25.010755');
insert into сообщение values (419, 139, 'консультант', $$Форд с Артуром так и обмерли, подавившись собственным воплем – Ну-ка, улыбочку, усмешечку!» Я разъяснял, что для того, чтобы мое лицо исказила улыбка, нужно отнести его в мастерскую и часа два поработать над ним кувалдой Есть частные клубы летателей, где вам помогут достичь ключевого самозабвения В нем зрела ненависть к Вселенной в целом и каждому из ее обитателей в частности$$, '2026-01-31 05:21:06.463223');
insert into сообщение values (420, 139, 'клиент', $$Артуру пришло в голову, что раз они добрались до конца, точнее, до начала всех ужасов, которые смутно пережили, сейчас должна стрястись беда Какое-то время он бездействовал, словно ожидая, что люди займутся своими обычными делами, не порицая его за это висение$$, '2026-01-30 11:15:12.844580');
insert into сообщение values (421, 140, 'консультант', $$– Подойти к своему кораблю через две минуты, – пояснил Артур и пожал плечами, что обличало отсутствие всяких мыслей в его голове Форд с Артуром поспешили за ним как околдованные$$, '2024-07-20 17:55:53.816356');
insert into сообщение values (422, 140, 'клиент', $$После сбора ее следует положить в темный пыльный ящик и не трогать много лет – Я дома, – шептал Артур Однако спустя миг стряслось нечто, чего невозможно было не заметить Затем из клубов дыма вынырнула светлая фигура Слартибартфаста$$, '2024-07-20 16:29:33.120373');
insert into сообщение values (423, 140, 'консультант', $$Сотни разных мыслей, расталкивая друг дружку, боролись за контроль над его голосовыми связками – Охохонюшки! – воскликнул компьютер Эдди Процедура превращения какого-либо объекта из зримого в незримый столь трудоемка, что в 999 999 999 случаях из миллиарда гораздо проще и эффективнее просто убрать этот объект куда подальше и обойтись без него$$, '2024-07-20 11:15:46.383781');
insert into сообщение values (424, 140, 'консультант', $$Однако на взгляд Артура, абсолютно черный небосвод придавал всему идиллическому, несмотря на сумрак, пейзажу какой-то зловещий оттенок Это Артур Дент говорит – Вот в чем беда с этим разговором, – заявил Артур после того, как озадаченность медленно, точно альпинист по трудному склону, вскарабкалась по его лицу и уселась на бровях, – он очень не похож на те, что мне приходилось вести в последнее время$$, '2024-07-20 06:38:15.208805');
insert into сообщение values (425, 141, 'клиент', $$Разница была только в том, что посылаемые их битами мячи при соприкосновении с землей взрывались$$, '2025-09-13 16:24:28.969587');
insert into сообщение values (426, 141, 'клиент', $$– Я думал, ты умер… – вырвалось у него$$, '2025-09-13 06:07:32.116757');
insert into сообщение values (427, 141, 'консультант', $$Только тускло-розовые каемки вокруг дверей, мерцавшие в такт их речам, – Зафоду так и не удалось придумать, как заткнуть им глотки Хотя в горле у него привычно саднило от традиционного утреннего душераздирающего вопля, он внезапно пришел в великолепное расположение духа – А затем мы отправимся, – на полном серьезе заявил робот, – на вечеринку$$, '2025-09-14 11:17:09.709685');
insert into сообщение values (428, 141, 'клиент', $$И все же этот случай войдет в анналы истории, тем более что он произошел в столь драматический момент, когда Англии не хватает до победы только двадцати восьми перебежек – Гм Как ни странно, за пределами словаря осталось слово «плучительно», означающее просто-напросто «с плучительностью»$$, '2025-09-11 04:27:14.851059');
insert into сообщение values (429, 142, 'консультант', $$– Мост? – не поверил своим ушам матрасс Нападающий приближался к калитке, плавно переходя с рысцы на бег[2] Большой стеклянный ящик, этакий аквариум – точнее, целая комната$$, '2024-02-14 11:30:21.613034');
insert into сообщение values (430, 142, 'консультант', $$Не знаю, зачем им это надо, но так оно и есть – И он сверкал? – воскликнул очарованный матрасс Слегка нахмурившись, он склонил голову набок$$, '2024-02-14 20:35:40.969042');
insert into сообщение values (431, 142, 'клиент', $$И тишина без конца Не самой лучшей целью – в чем он сам первый признавался, – но эта какая-никакая цель как-никак давала ему какое-никакое занятие$$, '2024-02-14 20:39:30.561490');
insert into сообщение values (432, 142, 'консультант', $$Сам себе сосчитал пульс$$, '2024-02-14 23:02:46.786132');
insert into сообщение values (433, 143, 'консультант', $$Еще мрачнее сдвинул брови – и наконец успокоился Хотя я узнал немало сногсшибательных вещей – А во-вторых, – продолжал Форд, – у тебя в бороде кость – А, ну и ладно, – промолвил Артур с облегчением$$, '2026-09-23 18:08:11.731403');
insert into сообщение values (434, 143, 'клиент', $$Грязно-розовое небо померкло, посинело, вновь окуталось мраком Еще чуть-чуть – и я разучился бы разговаривать – Чего? Зачем? Эгей-гей! Ну-ка вернись и повтори!

Он подпрыгивал и выплясывал, пока его ноги не подкосились, взывал, пока не надорвал связки По-видимому, этот разговор действовал ему на эквивалент нервов$$, '2026-09-25 16:42:16.890369');
insert into сообщение values (435, 143, 'клиент', $$– Спасибо Большую часть всех абсурдных вещей, какие приходили ему в голову, он уже повидал наяву Но никто этого не спрашивал, и Форд злился$$, '2026-09-24 08:03:19.690121');
insert into сообщение values (436, 144, 'клиент', $$И меж тем как «Золотое сердце» неслось с невероятной скоростью в неопределенном направлении, Триллиан прихлебывала какое-то неудобоваримое творение нутримата и читала о том, как научиться летать$$, '2027-07-29 01:38:44.889600');
insert into сообщение values (437, 144, 'консультант', $$– Батарейка села? – поинтересовался Артур$$, '2027-07-30 21:26:49.449884');
insert into сообщение values (438, 145, 'клиент', $$Криккитяне смотрели друг на друга, направо, налево, вперед, назад, даже на землю Темп застольных манипуляций неуловимо ускорился$$, '2027-04-25 20:49:44.744831');
insert into сообщение values (439, 145, 'клиент', $$– Я был в Африке, – заявил Форд Он плюнул на это занятие и, переведя взгляд на навигационный экран, ахнул при виде беспрецедентного полчища звезд$$, '2027-04-28 22:30:49.588948');
insert into сообщение values (440, 146, 'консультант', $$К счастью, таких тут хватало$$, '2028-11-10 21:40:14.118052');
insert into сообщение values (441, 146, 'консультант', $$На восьмом такте этой баллады, который сам по себе мог бы сделать Маккартни полноправным хозяином Винчестера, не говоря уже об окрестностях, текст стал каким-то странным – Тогда почему у вас в бороде кость?

– Я воспитываю в ней смирение с любым местоположением, – произнес Артур, сам собой гордясь Не бросай трубку – Сгинь, тебе говорят, дурилка пластиковая$$, '2028-11-09 23:14:33.785407');
insert into сообщение values (442, 147, 'консультант', $$Она услышала, как Зафод топочет и насвистывает где-то в недрах корабля Мало того, нижние сегменты их ног были защищены чем-то вроде белых щитков – Только, – заверил его Форд Глянул на экран – и не узнал ни единого созвездия$$, '2027-02-24 19:32:53.386010');
insert into сообщение values (443, 147, 'консультант', $$Свет померк$$, '2027-02-23 11:32:27.761520');
insert into сообщение values (444, 148, 'клиент', $$Тебе это по силам?

– Что это Слартибартфаст так волнуется? – спросил Артур Звездолет несся сквозь ночь Слартибартфаст дернул за ручку, и она умолкла Артур пожал плечами$$, '2024-06-23 09:42:17.923709');
insert into сообщение values (445, 148, 'клиент', $$Из люка вырвался столб света$$, '2024-06-23 07:49:47.361529');
insert into сообщение values (446, 148, 'клиент', $$– Разве что «Психоз в космосе» И только Слартибартфаст ежился, точно ему было не по себе Артур поднял глаза$$, '2024-06-23 23:23:44.358718');
insert into сообщение values (447, 149, 'консультант', $$Тогда я попробую ходить задом наперед Прежде чем мы поведаем, что именно сказал робот, следует отметить, что Зафод был первым живым органическим существом, кому довелось услышать голос этих тварей за последние десять биллионов лет – Мне это известно, – ответил Слартибартфаст – А затем мы отправимся, – на полном серьезе заявил робот, – на вечеринку$$, '2026-12-28 23:54:55.083961');
insert into сообщение values (448, 149, 'клиент', $$После четырех лет полного одиночества он был до слез рад видеть Форда живым и невредимым Засунув руки в единственный карман своего халата, он воззрился вдаль с видом знатока$$, '2026-12-29 04:15:51.783758');
insert into сообщение values (449, 149, 'клиент', $$Поддельные бутылки в поддельном бетоне – Не могу я с ней сжиться, – мрачно вымолвил он и выслал в свой желудок третий стакан: пусть найдет второй и выяснит, почему тот еще не доложил о здоровье первого$$, '2026-12-28 18:31:28.112853');
insert into сообщение values (450, 150, 'консультант', $$Конкретно – всего лишь одну ноту, повторяющуюся через определенные интервалы$$, '2027-02-19 18:49:29.071958');
insert into сообщение values (451, 150, 'консультант', $$– Если тревога ложная, я сойду с ума, – добавил он, – еще разок – Плексигласовый Столб – символ могущества Науки и Разума Галактики!

Новые лучи озарили правый, прозрачный столб, закутав его в замысловатое световое кружево – Быть такого не может, – сказал Форд, когда наблюдатели оправились от ускорения, а корабль уже рассекал верхние слои атмосферы Произнеся эту речь, Артур побрел к краю поля, отряхивая халат$$, '2027-02-22 20:24:18.979336');
insert into сообщение values (452, 151, 'консультант', $$Говоря «странные», мы не имеем в виду обычный (то есть странный по определению) стиль поведения Форда$$, '2026-01-29 00:21:48.089440');
insert into сообщение values (453, 151, 'консультант', $$Большой стеклянный ящик, этакий аквариум – точнее, целая комната$$, '2026-01-26 12:30:55.233410');
insert into сообщение values (454, 151, 'клиент', $$Артур растерянно кивнул Это был рубеж, за который никто из криккитян не заглядывал даже в мечтах, поскольку не знал о его существовании – Приклюса и чудесения, – пробормотал он$$, '2026-01-26 20:56:04.305469');
insert into сообщение values (455, 152, 'консультант', $$И вновь зашагал вперед Артур приподнялся на локтях:

– Где я?

– На крикетной площадке «Лордз», – сообщил Форд Он звался Охмешконасыпатель Конца-Краю-Не-Знающий, и был он индивидуумом с четкой целью в жизни Третий и самый загадочный образчик не-абсолютности кроется в соотношении между количеством включенных в счет блюд, стоимостью каждого блюда, числом людей за столом и суммой, которую каждый из них готов заплатить (количество людей, которые действительно прихватили с собой деньги – лишь субфеномен вышеуказанного поля)$$, '2026-11-21 07:59:32.717490');
insert into сообщение values (456, 152, 'клиент', $$Если и раньше он изъяснялся тоном призрака, то теперь это был вообще некий сильно простуженный житель Аида – Это твой звездолет? Не подбросишь нас хоть куда-нибудь?

– Терпение, терпение, – наставительно произнес тот – Формы и контуры, – пробормотал Артур$$, '2026-11-17 17:13:52.209787');
insert into сообщение values (457, 153, 'клиент', $$Было синее в желтую звездочку, а стало розовое Он зафлёпал туда-сюда, ошеломленный и взволнованный$$, '2026-07-27 20:51:53.223296');
insert into сообщение values (458, 153, 'клиент', $$Другими словами, оговоренный час сбора – это один-единственный момент времени, в который абсолютно невозможно появление любого из членов компании Наши герои взошли вслед за Слартибартфастом на борт и были столь ошарашены увиденным внутри, что совершенно не заметили нового странного происшествия снаружи$$, '2026-07-29 13:33:43.317252');
insert into сообщение values (459, 153, 'клиент', $$Тебе это по силам?

– Что это Слартибартфаст так волнуется? – спросил Артур Припев был немного печальный Он уставился вверх$$, '2026-07-30 21:45:16.091053');
insert into сообщение values (460, 154, 'клиент', $$Артур невольно отпрянул – Что, неужели сейчас на это место нападут? – спросил он Птицы выражали в песнях свое мнение обо всем этом – по-видимому, благоприятное$$, '2025-03-12 15:35:56.238991');
insert into сообщение values (461, 154, 'консультант', $$Даже если ты посмотришь прямо на ННП, то все равно ее не разглядишь – если только не знаешь заранее, как она выглядит Тогда я попробую ходить задом наперед$$, '2025-03-14 07:58:04.363979');
insert into сообщение values (462, 154, 'консультант', $$Я не шучу Реакция публики, точнее, реакции были многообразными и различными Форд, еще раз пожав плечами, исполнил требуемое:

– Все последние пять лет приснились тебе во сне – Быть такого не может, – сказал Форд, когда наблюдатели оправились от ускорения, а корабль уже рассекал верхние слои атмосферы$$, '2025-03-14 21:16:43.374027');
insert into сообщение values (463, 154, 'консультант', $$– Уф!

Зафод остановился Триллиан терпеливо кивнула самой себе, досчитала до предыдущего числа в кубе, вяло швырнула поднос в стену, прошла в телепортационную кабину и просто ушла из его жизни$$, '2025-03-12 19:08:16.389110');
insert into сообщение values (464, 155, 'консультант', $$– Очаги нестабильности в ней возникли, – ответил Форд А эта была не хуже прочих Однако спустя миг стряслось нечто, чего невозможно было не заметить Форд протянул руку и потрогал приборную доску$$, '2025-01-22 00:37:00.898702');
insert into сообщение values (465, 155, 'консультант', $$Еще некоторое время они лежали на газоне, скорбно хмурясь – А что это за принципы?

– Сформулировать их невозможно, – сказал Слартибартфаст Его причины остаются тайной, так как ни одному из геофизиков, специалистов по статистике вероятностей, метеорологов-аналитиков и чудологов поездка на Хэй-Виляй не по карману$$, '2025-01-20 22:58:19.993507');
insert into сообщение values (466, 155, 'клиент', $$– Было что-то интересное?

И вновь они балансировали на краю ужасно высокого утеса – Ты козел, – повторил инопланетянин$$, '2025-01-20 05:44:25.728068');
insert into сообщение values (467, 156, 'консультант', $$Пока он отсыпался, Триллиан заглянула в бортовой экземпляр «Путеводителя» – Ву-ун, – враднул он наконец – Хм, что-то не верится$$, '2024-11-01 21:42:41.151372');
insert into сообщение values (468, 156, 'консультант', $$Он подождал реакции Артура, но тот лишь благоразумно обронил:

– Давай дальше Первое не-абсолютное число – это число людей, на которое заказан столик Они стояли одни-одинешеньки на вершине утеса где-то на доисторической Земле и решительно смотрели друг другу в глаза$$, '2024-11-02 11:01:50.156314');
insert into сообщение values (469, 156, 'консультант', $$По-моему, – пояснил Артур, не сбавляя скорости$$, '2024-11-02 00:25:56.724072');
insert into сообщение values (470, 156, 'консультант', $$Кроме того, в звездолете просто не нашлось бы столько дверей – пресловутое «уф» прозвучало так, будто его произнесли сто тысяч человек разом$$, '2024-11-02 17:02:49.004309');
insert into сообщение values (471, 157, 'консультант', $$Если это и было чувство, то абсолютно бесчувственное Он заразился у Слартибартфаста беспокойством, хоть и не понимал его причин – Ну и что «Путеводитель»?

– В смысле?

– Ты хотел процитировать$$, '2025-02-18 19:43:58.371946');
insert into сообщение values (472, 157, 'клиент', $$Криккит – Какое расстояние мы сейчас преодолели? – спросил Форд Похоже, на них восседали не то девушки, не то ангелы В таком настроении к оружию лучше не прикасаться$$, '2025-02-20 09:34:39.481691');
insert into сообщение values (473, 157, 'клиент', $$– И он же снабдил меня этим протезом С тем же успехом можно покориться судьбе, а здравый рассудок поберечь на потом Форд что-то мурлыкал под нос – И указал в ту сторону, куда хотел бы спровадить ребят$$, '2025-02-19 17:19:53.364275');
insert into сообщение values (474, 158, 'консультант', $$Если последовательность размеренных щелчков, записанную на пленку, прокручивать с ускорением, одиночные щелчки постепенно сольются в постоянный, повышающийся тон Через несколько минут мы завладеем Золотой Перекладиной…

– Нет, не завладеете$$, '2024-03-06 05:20:06.240736');
insert into сообщение values (475, 158, 'клиент', $$Многие из них попадаются в силки охотников, после чего их убивают, высушивают, экспортируют и кладут на кровати, чтобы люди на них спали Тот же самый эффект наблюдался и в случае с кораблем Слартибартфаста – А… тв… в… хто… кто? – выдавил он наконец, после чего погрузился в неистовое (сродни неистовым воплям) безмолвие$$, '2024-03-06 16:34:15.214416');
insert into сообщение values (476, 158, 'консультант', $$Не будучи уверен в понятливости четвертого стакана, он послал за ним пятый с дополнительными пояснениями и шестой чисто ради моральной поддержки Затем Триллиан набрела на главку о Хэй-Виляй, экзотической планете-курорте, одном из чудес Галактики Артур сначала посмотрел вслед за указующим перстом – на табло, а потом туда, куда Форд глядел, – на поле и кивнул, пожимая плечами$$, '2024-03-06 04:55:47.210691');
insert into сообщение values (477, 158, 'консультант', $$Ты что, не помнишь?

– Помню – Мне кажется, – сказал Форд тоном, обещавшим (как уже было известно Артуру) какое-то чрезвычайно непонятное продолжение, – что вон там какое-то ННП При этих словах Артура точно пчела ужалила$$, '2024-03-06 08:06:23.906615');
insert into сообщение values (478, 159, 'консультант', $$– Артур! – заорал на него Форд Меж тем снаружи солнце лило свой свет на веселую толпу$$, '2026-02-14 22:25:32.482412');
insert into сообщение values (479, 159, 'клиент', $$– Э-э, так что там такое стряслось в этом континууме? Народ возмущается, что водопровод неисправен? И почему вдруг туда стоит эмигрировать?

Форд чуть не испепелил его взглядом Однако через некоторое время до него дошло, что он недалеко продвинулся и все же следует спросить: «Это в каком плане?»

– При передвижении по космосу, – повторил Слартибартфаст, – числа – настоящий бич божий$$, '2026-02-16 07:37:16.775888');
insert into сообщение values (480, 160, 'консультант', $$И тишина без конца В системе Неавооси находятся – то есть находились – крупнейшие страховые компании Галактики$$, '2028-04-12 02:40:33.552176');
insert into сообщение values (481, 160, 'клиент', $$Бистроматическая тяга – это чудесный новый способ преодоления необъятных космических расстояний без необходимости затевать опасный флирт со всякими там факторами невероятности – Я сам знаю, на что это похоже, – отрезал Слартибартфаст и вошел в пресловутое помещение Всеми этими причиндалами вяло манипулировали роботы Поскольку личный обучающий компьютер Зафода играл активную роль в этом плане, Зафод в итоге стер из его памяти всю историю, освобождая место для более актуальной группы концепций$$, '2028-04-16 23:02:06.974172');
insert into сообщение values (482, 161, 'консультант', $$И потому большинство людей после первых неудач разочаровываются в этом увлекательном, зрелищном спорте – Короли? – подсказал Форд Этот факт был расценен как величайшее достижение социологии телевидения А придумал он вот что$$, '2026-01-28 13:26:06.161934');
insert into сообщение values (483, 161, 'консультант', $$Это они шли в тот вечер по тропе, распевая мелодичные, проникновенные песни Длинный стол Пойдемте за ними и посмотрим сами – Ты козел, Дент, – промолвила она просто$$, '2026-01-28 10:14:21.027673');
insert into сообщение values (484, 161, 'клиент', $$Тьма Пылевого Облака сдавила корабль$$, '2026-01-29 16:01:50.986950');
insert into сообщение values (485, 162, 'консультант', $$– И я не хочу, чтобы ты желала мне приятно провести день, поняла?

– Я поняла На полпути к рубке его осенило, что это вполне может оказаться Марвин, и он бегом вернулся обратно – Я занялся издевательствами над животными, – проговорил он беззаботно Форд, нас подбрасывают!

И действительно, для того чтобы не поддаться этому первому впечатлению, надо было обладать весьма глубокими познаниями в истории Галактики (каковых Артур еще не успел приобрести из-за своей кочевой жизни)$$, '2027-05-07 23:37:42.459222');
insert into сообщение values (486, 162, 'клиент', $$– Я дома, – хрипло буркнул Артур$$, '2027-05-10 03:10:19.152377');
insert into сообщение values (487, 162, 'клиент', $$Чересчур осмысленное и лаконичное Слартибартфаст, Форд и Артур остановились под ароматно пахнущим деревом Подобно открытию Эйнштейна, что время не есть абсолют, но зависит от движения наблюдателя в пространстве, а пространство не есть абсолют, ибо зависит от движения наблюдателя во времени, ныне установлено, что числа не абсолютны, но зависят от движения наблюдателя в ресторанах А, Слартибартфаст, здорово, что ты тут делаешь?

– Да так, слоняюсь, – отвечал старец сурово$$, '2027-05-11 08:03:11.656437');
insert into сообщение values (488, 163, 'консультант', $$Одну голову он засунул под подушку, а вторая до поздней ночи разгадывала кроссворды$$, '2025-11-30 03:35:59.975104');
insert into сообщение values (489, 163, 'консультант', $$Все было ясно из самой его походки – Это же крикетная площадка «Лордз», верно? – возопил Артур Они достигли цели Поскольку в истории был лишь один Его Светлость лорд Соньвальтяп Пустецийский, да и тот умер холостяком, слово употребляется лишь в отрицательном или в гипотетическом смысле$$, '2025-11-30 03:12:39.045258');
insert into сообщение values (490, 163, 'консультант', $$Они стояли неподвижно – Знаешь, – сказал Форд, – я…

– Где ты шатался? – прервал его Артур, чья голова все-таки покончила с физкультурной разминкой – Кто же?

– Мммммм мммммм мммммм, – сказал компьютер$$, '2025-11-30 18:59:29.709250');
insert into сообщение values (491, 163, 'консультант', $$На горизонте маячили симпатичные круглые холмы$$, '2025-11-28 19:09:37.683910');
insert into сообщение values (492, 164, 'клиент', $$– Ты козел, – повторил инопланетянин Тут-то он и услышал пресловутое «Уф!», что его страшно встревожило Те, кто рождается бессмертным, от рождения бессознательно свыкаются с этим своим свойством, но Охмешконасыпатель – не из их числа$$, '2026-10-02 05:45:05.591597');
insert into сообщение values (493, 164, 'клиент', $$Три пилота были одновременно и конструкторами корабля$$, '2026-10-01 12:20:13.608980');
insert into сообщение values (494, 164, 'клиент', $$Тут Артура посетила некая неясная догадка относительно смысла представшего перед ним зрелища, но он поспешил ее отбросить А сказал он следующее:

– Да, у вас в руке действительно пистолет-бластер системы «Громовержец» «Брось дуться, лапочка робот! – кричали они – Вот что я сказал$$, '2026-10-02 03:42:48.270494');
insert into сообщение values (495, 165, 'консультант', $$Затем еще раз огляделся по сторонам с еще большим ужасом Несмотря на кучи обломков, Зафод с новым ужасом разглядел, что они движутся к самому ядру корабля, сердцу невероятностной тяги, загадочным образом сгущаемой из пустоты, – в общем, к самому «Золотому сердцу» – Я дома, – повторил Артур Залезайте, нам пора$$, '2026-12-27 00:02:39.966387');
insert into сообщение values (496, 165, 'консультант', $$Задумайтесь об этом, друзья мои Люк сам собой захлопнулся – Не слишком похоже на наш случай$$, '2026-12-29 10:23:23.351945');
insert into сообщение values (497, 165, 'клиент', $$Стол был покрыт скатертью – неказистой скатертью в красную и белую клетку, на которой кое-где зияли прожженные дыры – положение всякой из них, по-видимому, имело глубокий математический смысл$$, '2026-12-27 14:13:58.668528');
insert into сообщение values (498, 166, 'консультант', $$– Послушай, – промолвила Триллиан сочувственным тоном и присела рядышком, – очень даже объяснимо, что некоторое время жизнь будет казаться тебе бесцельной$$, '2028-05-15 10:05:30.168651');
insert into сообщение values (499, 166, 'клиент', $$Артуру Денту остро захотелось мороженого$$, '2028-05-12 23:00:45.633849');
insert into сообщение values (500, 167, 'консультант', $$Планета Хэй-Виляй изобилует сказочно, непостижимо роскошными отелями и казино Поскольку в истории был лишь один Его Светлость лорд Соньвальтяп Пустецийский, да и тот умер холостяком, слово употребляется лишь в отрицательном или в гипотетическом смысле Замотав головой, Форд закрыл лицо руками и нечаянно отфутболил к стене подвернувшийся под ногу цветочный горшок Он сидел в своей пещере, составлял каталог возможных отповедей наглому инопланетянину и давил мух – для них этот вечер тоже оказался кошмарным$$, '2025-02-12 05:15:50.335361');
insert into сообщение values (501, 167, 'клиент', $$– Осмелюсь заметить, что ваши диоды полны глубокой печали, – влючал он (чтобы узнать значение слова «влючать», купите либо трактат «Речь жителей болот Прутивнобендзы» – имеется на любом складе уцененных книг, либо «Максимегалонский словарь», чем страшно порадуете университет, вынужденный отводить под его хранение свою драгоценную автостоянку), – и это меня очень огорчает$$, '2025-02-13 07:38:22.075504');
insert into сообщение values (502, 167, 'клиент', $$Затем однажды ночью она внезапно созревает, отбрасывает внешнюю оболочку, которая рассыпается в прах, и выходит на свет божий в обличье крайне загадочного маленького металлического предмета с фланцами с обоих концов, чем-то вроде дырки под винт и чем-то вроде гребешка Казалось, его соорудили где-то в сарае – собственно, так оно и было – По крайней мере мне так кажется – Серьезно?

– Да$$, '2025-02-12 18:39:45.686468');
insert into сообщение values (503, 167, 'консультант', $$– Мост? – не поверил своим ушам матрасс Сам себе сосчитал пульс – Тогда я был в некотором смысле знаменитостью$$, '2025-02-12 11:47:08.186104');
insert into сообщение values (504, 168, 'консультант', $$– Скатертью дорожка, – пробормотал Зафод, перевернулся на другой бок и всю ночь не смыкал глаз Миссия «Криккита-1» заключалась в том, чтобы выяснить, есть ли что-то с той стороны неба, откуда, вероятно, и происходил разбившийся корабль – Спасибо, что осчастливили простую скромную дверцу – Хмммм$$, '2024-12-06 22:53:29.426118');
insert into сообщение values (505, 168, 'клиент', $$Криккит – Занимательно, не правда ли? – произнесло видение После сбора ее следует положить в темный пыльный ящик и не трогать много лет Фальшивка$$, '2024-12-07 06:32:59.176651');
insert into сообщение values (506, 168, 'консультант', $$Говоря «странные», мы не имеем в виду обычный (то есть странный по определению) стиль поведения Форда Роботы успели частично разобрать дальнюю стену рубки и пробить ход через жизненно важные органы корабля$$, '2024-12-08 04:39:06.116491');
insert into сообщение values (507, 168, 'консультант', $$Внезапно Форд начал буквально излучать энергию и целеустремленность – Ни фига себе, – с этими словами он выпил еще стакан$$, '2024-12-06 13:37:56.034766');
insert into сообщение values (508, 169, 'клиент', $$Надежда и ликование в душе Артура вмиг сменились чувством крайней озадаченности$$, '2027-08-09 16:06:34.637196');
insert into сообщение values (509, 169, 'консультант', $$Они немного прошли в сторону города, и инфоиллюзия травы приятно пружинила под ногами, а инфоиллюзии цветов безупречно благоухали Дело в том, что принцип его работы основан на свойственной людям естественной предрасположенности не видеть ничего из того, чего видеть не желаешь, увидеть не предполагаешь или не можешь себе объяснить – Ну и как она выглядит?

– Ну а мне-то откуда знать, идиот? Сам видишь – сам и описывай$$, '2027-08-10 16:26:30.914713');
insert into сообщение values (510, 169, 'клиент', $$– Выражаю свою позицию, – процедил Марвин, не переставая описывать круг за кругом Он прошел к зеленой винтовой лестнице из кованого железа, непонятно зачем помещенной в середине рубки, и начал всходить по ней На обратном пути они спели немало мелодичных, наполненных глубоким смыслом песен на темы мира, справедливости, нравственности, культуры, спорта, семейной жизни и ликвидации всех прочих форм жизни$$, '2027-08-10 04:53:04.676438');
insert into сообщение values (511, 170, 'консультант', $$– Артур Филип Дент? – уточнило существо, деловито лязгнув зубами – Мы ищем Ключ, – повторил он, – мы уже владеем Деревянным Столбом, Стальным Столбом и Плексигласовым Столбом Шшшшрр$$, '2025-01-09 20:34:07.889643');
insert into сообщение values (512, 170, 'клиент', $$Старец, пропустив эти слова мимо ушей, внимательно, с непонятным в данной ситуации волнением следил за происходящим на поле$$, '2025-01-11 16:12:22.263387');
insert into сообщение values (513, 170, 'консультант', $$Форд повторил – Да так, ничего особенного, – сказал Форд Другими словами, имелись в наличии все предпосылки для приступа самокопания, но, как показала жизнь, поддаваться ему никак не следовало И все двигалось, приплясывало, трепыхалось$$, '2025-01-10 03:38:22.003337');
insert into сообщение values (514, 171, 'клиент', $$– Остатки сожженного столбика$$, '2025-09-09 10:19:55.810084');
insert into сообщение values (515, 171, 'клиент', $$Криккитские войны относились к древней истории Галактики Зафод отключил большинство второстепенных систем и механизмов – Я там здорово начудил Безусловно, вся земная медицина была уже не в силах его спасти$$, '2025-09-09 03:04:26.045211');
insert into сообщение values (516, 172, 'консультант', $$Внутри царила историческая тишина Зафод влил еще стакан в свою другую глотку$$, '2025-06-25 20:54:31.348011');
insert into сообщение values (517, 172, 'консультант', $$Стол был покрыт скатертью – неказистой скатертью в красную и белую клетку, на которой кое-где зияли прожженные дыры – положение всякой из них, по-видимому, имело глубокий математический смысл – Классно, – молвил Артур – и его душа выпорхнула наружу перевести дух$$, '2025-06-26 07:30:34.567530');
insert into сообщение values (518, 172, 'клиент', $$Но тут же просияв, перевел взгляд на широкий экран панорамного обзора, где струились, головокружительно сплетаясь и расплетаясь вокруг корабля, серебряные нити$$, '2025-06-25 12:31:49.367348');
insert into сообщение values (519, 172, 'клиент', $$Он пронзил облака, на миг озарив их своим серебряным свечением, и исчез из виду Артура – одинокой букашки, бестолково скачущей на месте посреди бескрайней шири И она была смертельно опасна – и вновь не на манер ножа или пули, но наподобие кирпичной стены поперек шоссе$$, '2025-06-26 09:31:19.651646');
insert into сообщение values (520, 173, 'консультант', $$* * *
Хозяин звездолета, инопланетянин с дорогостоящим цветом лица, развалился в единственном кресле рубки$$, '2025-06-23 23:38:19.544962');
insert into сообщение values (521, 173, 'консультант', $$Правда, он всегда подозревал о ее существовании, поскольку обладал полным комплектом стандартных органов (и даже двойным – кое-каких), но, внезапно обнаружив в глубине своего существа эту затаившуюся зверюшку, был крайне шокирован – Ну и хорошо, – сказал Артур$$, '2025-06-24 02:33:09.717723');
insert into сообщение values (522, 174, 'клиент', $$В его желудке точно черти свадьбу справляли Тут-то он и услышал пресловутое «Уф!», что его страшно встревожило Если это и было чувство, то абсолютно бесчувственное$$, '2026-07-16 06:10:07.737813');
insert into сообщение values (523, 174, 'клиент', $$Было неопровержимо доказано, что количество зрителей, смотревших телерепортаж о запуске «Титаника», превосходило все население Вселенной на тот момент – Вам весело? – спросил матрасс – Я так и понял Триллиан терпеливо кивнула самой себе, досчитала до предыдущего числа в кубе, вяло швырнула поднос в стену, прошла в телепортационную кабину и просто ушла из его жизни$$, '2026-07-15 16:26:35.611923');
insert into сообщение values (524, 174, 'консультант', $$– У нас на борту кто-то есть?

– Мммм, – ответил компьютер$$, '2026-07-17 04:56:58.471229');
insert into сообщение values (525, 174, 'клиент', $$Ах, как прекрасен – аж глазам больно – был «Звездный Титаник», когда, точно арктурианский мегавакуумный серебристый кит, он качался в лазерных тенетах гибких строительных лесов Да, я в курсе, на что он похож, но в реальности это сложный четырехмерный топографический график целого ряда весьма замысловатых математических функций Вот она:

Числа, записываемые в счета на территории ресторанов, не подчиняются математическим законам, которые управляют числами, записываемыми на любых других листках бумаги в любых других уголках Вселенной – Я изумлен, – сказал Артур, – и потрясен$$, '2026-07-15 15:36:52.057793');
insert into сообщение values (526, 175, 'консультант', $$– Сейчас промотаем всю эту чушь$$, '2025-08-31 11:19:38.037241');
insert into сообщение values (527, 175, 'консультант', $$– Верно, – признал Артур Пристегиваясь ремнями, Форд Префект только возносил хвалу судьбе за то, что это всего лишь безопасная инфоиллюзия Мелкие капли едва просачивались сквозь туман – Какое-то «что»?

– ННП$$, '2025-08-31 23:48:12.737943');
insert into сообщение values (528, 175, 'консультант', $$– Очаги нестабильности в ней возникли, – ответил Форд Инопланетное существо, морща лоб, заглянуло в штучку вроде папки, которую сжимало в своих длинных, лианообразных инопланетных пальцах$$, '2025-09-01 16:49:53.220157');
insert into сообщение values (529, 175, 'консультант', $$Этакий замысловатый балет меню, счетов, бумажников, чековых книжек, кредитных карточек, часов, карандашей и бумажных салфеток – Я думал, ты сказал, что это не наша проблема – Тс-с, – вновь прошипел Форд$$, '2025-09-02 00:14:10.313217');
insert into сообщение values (530, 176, 'клиент', $$Роботы$$, '2029-08-19 18:52:47.322503');
insert into сообщение values (531, 176, 'клиент', $$И камни тоже не мои, – добавил он, вытащив из сумки горсть плоских серых камешков$$, '2029-08-19 00:55:26.286818');
insert into сообщение values (532, 177, 'клиент', $$Да, я в курсе, на что он похож, но в реальности это сложный четырехмерный топографический график целого ряда весьма замысловатых математических функций Наверху их глазам предстала совершенно бредовая картина – Это необходимо убрать, – сказали криккитяне, направив корабль в сторону дома Но вскоре в этом светлом существовании появилось нестерпимое темное пятно – воскресенья$$, '2026-08-18 19:37:01.983479');
insert into сообщение values (533, 177, 'клиент', $$– Вон за тем диваном!

Артур взглянул в указанную сторону$$, '2026-08-18 18:28:42.573028');
insert into сообщение values (534, 178, 'клиент', $$Тогда я попробую ходить задом наперед$$, '2026-05-17 09:16:26.091924');
insert into сообщение values (535, 178, 'клиент', $$– Однажды мне довелось произнести речь, – сказал он внезапно, как бы безо всякой связи с предыдущим Вы наверняка сталкивались с этим феноменом в жизни$$, '2026-05-17 01:56:37.203106');
insert into сообщение values (536, 179, 'консультант', $$Что матрасс и сделал, испустив еще одно легкое флюпчание$$, '2026-06-05 19:00:14.299012');
insert into сообщение values (537, 179, 'консультант', $$) Ха! О, жизнь моя – жестянка, жестянка на червячном ходу!

И снова побрел вокруг своей тонкой стальной ноги-протеза, которая вращалась в грязи, но никак не поддавалась Они немного прошли в сторону города, и инфоиллюзия травы приятно пружинила под ногами, а инфоиллюзии цветов безупречно благоухали А потом был еще более крайне шокирован тем, что она оказалась, мягко говоря, не столь мила и очаровательна, сколь полагалось бы такому человеку, как он – Уловили суть? – спросил Слартибартфаст$$, '2026-06-07 20:05:46.156508');
insert into сообщение values (538, 179, 'клиент', $$Меж тем как об этих звездолетах, а также других кораблях-легендах, например линкорах Галактической Армады («Храбром», «Безрассудном» и «Камикадзе»), говорят с благоговением, гордостью, упоением, энтузиазмом, восторгом, симпатией, сожалением, завистью, ревностью – в общем, почти со всеми людскими эмоциями, но подлинного чувства изумления удостоился лишь корабль, который всем вышеперечисленным не чета– «Криккит-1», первый звездолет, который построили криккитяне$$, '2026-06-06 08:01:00.412238');
insert into сообщение values (539, 179, 'клиент', $$Строго говоря, эту шайку бесчувственных выродков он давно уже возненавидел лютой ненавистью Произнеся эту речь, Артур побрел к краю поля, отряхивая халат Но несть числа тем, кто упивается историей «Звездного Титаника», легендарного корабля-колосса$$, '2026-06-05 12:09:30.073420');
insert into сообщение values (540, 180, 'консультант', $$Мозг просто вымарывает эту штуку из поля зрения, точно слепое пятно – А… мт… – выпалил он$$, '2026-01-14 22:38:02.718535');
insert into сообщение values (541, 180, 'клиент', $$– Это исток всему Слартибартфаст сказал:

– Потому что при передвижении по космосу числа – настоящий бич божий Ему не хотелось думать, что эту идиллическую страну постигнет несчастье$$, '2026-01-16 17:46:37.359453');
insert into сообщение values (542, 180, 'клиент', $$– Опасно?

– Мммм$$, '2026-01-14 17:31:40.329231');
insert into сообщение values (543, 180, 'консультант', $$Не самой лучшей целью – в чем он сам первый признавался, – но эта какая-никакая цель как-никак давала ему какое-никакое занятие – Хорошо С другой стороны, нельзя было отрицать, что по сравнению с этим проворным кораблем «Золотое сердце» казалось детской коляской$$, '2026-01-15 12:41:10.900667');
insert into сообщение values (544, 181, 'клиент', $$Матрасс зауйломикал с головы до пят, отчего гладь мелкой, заросшей ряской протоки подернулась восторженной рябью Он дико озирался по сторонам, пока не заметил, что Форд с Артуром пробираются сквозь испуганную толпу, которая шарахнулась прочь от поля – Счастливая Галактика, друзья мои, а образ ее – Трикетная Калитка!

Теперь три столба различались ясно Сквозь мрак виднелись лишь огни ближнего городка$$, '2026-09-11 03:57:51.016442');
insert into сообщение values (545, 181, 'консультант', $$Робот-официант, робот-буфетчик и робот-метрдотель обслуживали роботов-клиентов К счастью, таких тут хватало Невдалеке слышались голоса играющих детей, а чуть подальше в раннем сумраке виднелся небольшой городок – Назревают великие события$$, '2026-09-13 18:51:24.899359');
insert into сообщение values (546, 181, 'клиент', $$Он вновь задумался о происшедшем – Да, только я его выудил, – сообщил Форд Однако Артура воскресили не эти пасторальные радости Он перешел на шепот$$, '2026-09-13 15:02:30.904730');
insert into сообщение values (547, 182, 'клиент', $$Зафод не покидал кровати – …и…

– Похоже, до тебя дошло (Естественно, я не знаю их лично, но я знаю природу всех органических живых существ, и гораздо более досконально, чем хотел бы$$, '2026-01-30 00:05:02.682549');
insert into сообщение values (548, 182, 'клиент', $$Слова все время забываю Призрачные, но весьма агрессивные фигуры, шевелившиеся за толстой дымовой завесой, и впрямь будто пародировали удары нападающих Третий и самый загадочный образчик не-абсолютности кроется в соотношении между количеством включенных в счет блюд, стоимостью каждого блюда, числом людей за столом и суммой, которую каждый из них готов заплатить (количество людей, которые действительно прихватили с собой деньги – лишь субфеномен вышеуказанного поля)$$, '2026-01-29 18:00:29.043420');
insert into сообщение values (549, 183, 'клиент', $$Компьютер безголосо пискнул в знак окончания вычислений$$, '2027-07-06 17:41:00.877611');
insert into сообщение values (550, 183, 'консультант', $$Тот же самый эффект наблюдался и в случае с кораблем Слартибартфаста Еле-еле – подчеркнуто еле-еле – удерживая на весу руку, он простер ее к участку болота за туманом и зарослями, удивительно похожему на все другие участки болота$$, '2027-07-07 00:02:26.301094');
insert into сообщение values (551, 183, 'клиент', $$Она просто ушла – превратилась в случайный набор точек, странствующий по Вселенной В общем, голос был столь же древним, как и его владелец Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза$$, '2027-07-09 12:17:47.722950');
insert into сообщение values (552, 184, 'клиент', $$Он флёпал сочувственно, активно колыша при этом воду А за спиной человека из исполинских клубов мглы стали постепенно вырисовываться три высоких столба – Подойти к своему кораблю через две минуты, – пояснил Артур и пожал плечами, что обличало отсутствие всяких мыслей в его голове$$, '2025-11-30 04:00:02.337378');
insert into сообщение values (553, 184, 'консультант', $$За исключением одного случая – Да? – обалдело переспросил Зафод Но теперь все происходило слишком уж молниеносно – сплошное видеотактильное пятно, которое волокло их сквозь века галактической истории, крутясь, дергаясь, мерцая И аналогично повышающемуся тону, который, забираясь все выше и выше, будет по дороге менять характер и обретать мелодичность, так и это бесчувственное чувство возвысилось до невыносимого, если и немого, вопля$$, '2025-11-29 12:00:28.086701');
insert into сообщение values (554, 184, 'клиент', $$Некому было его услышать, некому было с ним поговорить Также вы научитесь правильно приземляться – сразу предупредим, что первая попытка выйдет большущим комом Слова все время забываю Его мозг замер, как щенок, испуганно забившийся в угол$$, '2025-11-29 11:57:56.753308');
insert into сообщение values (555, 185, 'консультант', $$– Где?

Слегка дрожащей рукой Форд очертил чуткоматом дугу в воздухе$$, '2024-06-14 06:12:16.316256');
insert into сообщение values (556, 185, 'клиент', $$– Я – Зем, – представился матрасс – Вне всяких сомнений, – ответил Форд с не меньшей непреклонностью Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза$$, '2024-06-15 04:36:50.806543');
insert into сообщение values (557, 185, 'клиент', $$Некому было его услышать, некому было с ним поговорить Матрасс зауйломикал с головы до пят, отчего гладь мелкой, заросшей ряской протоки подернулась восторженной рябью$$, '2024-06-14 04:24:39.386226');
insert into сообщение values (558, 185, 'клиент', $$– Должно быть, она тебе донельзя обрыдла В таком настроении к оружию лучше не прикасаться – Куда? На чем? – воскликнул Артур Настоящее издевательство$$, '2024-06-14 21:45:54.673596');
insert into сообщение values (559, 186, 'клиент', $$При взгляде на это небо мерещилось, будто ты один-одинешенек во Вселенной А придумал он вот что Триллиан казалось, что это-то ей и требуется после всего пережитого – Это не первая аномалия времени на моем веку$$, '2025-01-30 12:06:27.423551');
insert into сообщение values (560, 186, 'консультант', $$Это Артур Дент говорит И пошел по коридору в сторону рубки, откуда доносились все более громкие и деловитые звуки$$, '2025-01-31 13:47:38.091735');
insert into сообщение values (561, 186, 'консультант', $$Артур пришел в безмятежное настроение Вероятно, природа – в своей безмерной мудрости – работает над этим – Ну и как там?

– А это что, твоя пещера? – спросил Форд$$, '2025-01-31 03:03:52.242116');
insert into сообщение values (562, 187, 'клиент', $$Глянул на Артура – тот тихо напевал себе под нос Глянул на экран – и не узнал ни единого созвездия$$, '2025-11-05 17:23:12.202782');
insert into сообщение values (563, 187, 'консультант', $$– Странная весть, – процедил Форд С другой стороны, нельзя было отрицать, что по сравнению с этим проворным кораблем «Золотое сердце» казалось детской коляской Как ни странно, за пределами словаря осталось слово «плучительно», означающее просто-напросто «с плучительностью»$$, '2025-11-06 16:06:53.116412');
insert into сообщение values (564, 188, 'клиент', $$– Подойти к своему кораблю через две минуты, – пояснил Артур и пожал плечами, что обличало отсутствие всяких мыслей в его голове При этих словах Артура точно пчела ужалила Дверь тихо отъехала в сторону – Ну, корабль ведь твой$$, '2024-12-23 00:00:17.020540');
insert into сообщение values (565, 188, 'консультант', $$Но тьма – глухой кокон, оберегающий внутренний мрак, – все еще гудела вокруг корабля – Вот в чем беда с этим разговором, – заявил Артур после того, как озадаченность медленно, точно альпинист по трудному склону, вскарабкалась по его лицу и уселась на бровях, – он очень не похож на те, что мне приходилось вести в последнее время$$, '2024-12-23 17:11:35.676621');
insert into сообщение values (566, 188, 'консультант', $$Артур обратил внимание, что двое криккитян завели новую песню – милую романтическую балладу, которая словно парила в прохладном ночном воздухе – Тогда я был в некотором смысле знаменитостью – Порядок, – ответил он бодро, – ужас как хорошо$$, '2024-12-23 19:59:14.423335');
insert into сообщение values (567, 188, 'консультант', $$Не слушайте окружающих – ничего полезного они не скажут Вы видели этот фильм всего лишь тридцать три тысячи пятьсот семнадцать раз$$, '2024-12-24 05:29:05.055038');
insert into сообщение values (568, 189, 'клиент', $$– Что случилось? – спросил Артур с глубоким благоговением – Тс-с, – прошипел Форд и глубокомысленно воздел очи горе Потом стал выключать освещение Тут Артура посетила некая неясная догадка относительно смысла представшего перед ним зрелища, но он поспешил ее отбросить$$, '2024-12-03 03:10:16.441506');
insert into сообщение values (569, 189, 'консультант', $$Похоже, в основном он состоял из низеньких зданий, построенных из белого камня Не будучи уверен в понятливости четвертого стакана, он послал за ним пятый с дополнительными пояснениями и шестой чисто ради моральной поддержки Старец остановился и поднял глаза к небу Также никому не известно, что за радость находят в своем образе жизни матрассы$$, '2024-12-02 07:38:40.092433');
insert into сообщение values (570, 189, 'клиент', $$Попробуйте проделать это в погожий денек, рекомендует «Путеводитель» Размял их между пальцами Это звук, который издают живые матрассы в своей естественной среде обитания, приняв близко к сердцу чью-то повесть о жизненной драме$$, '2024-12-02 19:03:59.681054');
insert into сообщение values (571, 189, 'клиент', $$– А я спал, – заявил вынырнувший откуда-то Форд$$, '2024-12-02 01:11:01.213655');
insert into сообщение values (572, 190, 'консультант', $$– Э-э… да… я… э-э-э… – подтвердил Артур Робот, похоже, понял На обратном пути они спели немало мелодичных, наполненных глубоким смыслом песен на темы мира, справедливости, нравственности, культуры, спорта, семейной жизни и ликвидации всех прочих форм жизни А за спиной человека из исполинских клубов мглы стали постепенно вырисовываться три высоких столба$$, '2025-10-23 09:59:18.065533');
insert into сообщение values (573, 190, 'консультант', $$Большинство зрителей, будучи не в силах выдержать этого зрелища, зажмурили глаза и переключились на слушание радиотрансляции На миг болото буквально вскипело: роботы все разом накинулись на Марвина, оторвали его ногу-протез и вознеслись обратно на свой корабль, который вымолвил: «Фу!»

– Вот видите, с какими издевательствами мне приходится смиряться? – сказал Марвин момишкающему матрассу Зачем это понадобилось притаскивать сюда сто тысяч человек ради такой ерунды?

Он нервно двинулся в сторону рубки$$, '2025-10-21 12:13:44.931919');
insert into сообщение values (574, 191, 'консультант', $$То была счастливая Галактика!

Колоссальные аккорды ошалели от собственной весомости Глянул на Артура – тот тихо напевал себе под нос Если б Эффрафакс покрасил гору в ярко-розовый цвет, а сверху водрузил недорогой генератор ННП-поля, люди так и ходили бы мимо горы, вокруг нее, даже по ее склонам – ничуть не подозревая о ее присутствии Солнце нехотя попыталось одолеть туман, пробуя то тут добавить немножко тепла, то вон туда запустить несколько лучиков, но, судя по всему, сегодня его ожидала очередная тягомотная прогулка от горизонта до горизонта$$, '2027-04-23 11:43:35.681096');
insert into сообщение values (575, 191, 'консультант', $$– Ты козел, Дент, – проговорил мальчик Искусственная мебель, искусственная скатерть В отчаянии он снова пихнул Форда локтем$$, '2027-04-23 08:53:49.540053');
insert into сообщение values (576, 192, 'консультант', $$Мало того, нижние сегменты их ног были защищены чем-то вроде белых щитков Несомненно, «Золотое сердце» произвело здесь фурор, и Триллиан была польщена Единственная надежда – застичь ННП врасплох краешком глаза Когда его знакомые (даже у таких типов бывают знакомые) намекали, что план не только этически неприемлем, но и неосуществим – поскольку все время кто-то умирает, а кто-то рождается, Охмешконасыпатель просто вперял в оппонента свой стальной взгляд и бурчал: «Что, и помечтать нельзя?»

Итак, он взялся задело$$, '2026-02-27 10:33:44.812968');
insert into сообщение values (577, 192, 'консультант', $$– Э-э, пять, – сказал матрасс$$, '2026-03-01 07:56:58.409068');
insert into сообщение values (578, 192, 'клиент', $$Пластмасса под бетон – Я так и понял Можете рассказать это вместо анекдота своим друзьям Зему и Зему при первой же встрече – они животики надорвут, если я их знаю Они прошли очень близко от наблюдателей под деревом, размахивая фонарями, от чего по траве и листве скакали забавные «зайчики», радостно болтая между собой и самым натуральным образом распевая песню о том, как все чуд-чуд-чудесно на свете, как они счастливы, как здорово они потрудились на ферме и как приятно возвращаться домой, где ждут жены и дети$$, '2026-02-27 03:56:40.790763');
insert into сообщение values (579, 193, 'консультант', $$И естественно, на следующее утро Меграмал больше не был виден$$, '2025-11-12 17:45:41.298332');
insert into сообщение values (580, 193, 'консультант', $$В нем они выражали сожаление, что из-за работы им приходилось долгими часами корпеть в сарае, не видя ни жен, ни детей, которые страшно по ним скучали, но подбадривали их бесконечными новостями о приключениях растущего щенка$$, '2025-11-13 17:02:49.191995');
insert into сообщение values (581, 194, 'консультант', $$Это был рубеж, за который никто из криккитян не заглядывал даже в мечтах, поскольку не знал о его существовании Тьма Пылевого Облака сдавила корабль – Я тут временно спустил свой разум с цепи, предполагая, что, если я миру дико понадоблюсь, он призовет меня обратно$$, '2026-03-09 06:27:11.628236');
insert into сообщение values (582, 194, 'клиент', $$Пока я только процитирую «Путеводитель»…

– «Пу…»?

– «Путеводитель»$$, '2026-03-07 00:56:06.070646');
insert into сообщение values (583, 194, 'консультант', $$Пристегиваясь ремнями, Форд Префект только возносил хвалу судьбе за то, что это всего лишь безопасная инфоиллюзия$$, '2026-03-07 06:00:41.525977');
insert into сообщение values (584, 195, 'консультант', $$Тут силы матрасса иссякли, и он флюмкнулся обратно в протоку, обрушив на Марвина струю мокрой тины с водорослями и мхом Артур Дент Артур обратил внимание, что двое криккитян завели новую песню – милую романтическую балладу, которая словно парила в прохладном ночном воздухе$$, '2027-10-15 14:28:09.242851');
insert into сообщение values (585, 195, 'клиент', $$Вот оно – то, что разрушили орды Криккита, то, что теперь держит их планету в заточении и будет держать до скончания вечности!

И вальяжным жестом мужчина извлек из воздуха модель Трикетной Калитки Осмелюсь признаться, я питаю некоторую слабость к крикету, хотя я не хотел бы, чтобы о ней знали за пределами этой планеты – Я просто так спрашиваю, для информации – Онизавялилеппе! – снова завопил Слартибартфаст$$, '2027-10-17 14:24:34.158180');
insert into сообщение values (586, 196, 'клиент', $$– Ву-ун, – заметил матрасс$$, '2025-08-19 10:02:37.650476');
insert into сообщение values (587, 196, 'клиент', $$Не знаю, зачем им это надо, но так оно и есть$$, '2025-08-21 05:06:39.296899');
insert into сообщение values (588, 196, 'клиент', $$Но теперь все происходило слишком уж молниеносно – сплошное видеотактильное пятно, которое волокло их сквозь века галактической истории, крутясь, дергаясь, мерцая После нескольких удачных проб вы обнаружите, что отвлечься становится все проще и проще Идиот, идиот и еще раз кретин$$, '2025-08-19 05:50:34.184543');